INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_7ce18a5bdaa62468f57f9b6c","wiki/sources/fragenkatalog-annex-vii-data.md",48,"Seite 26","V.IWF 41 Fragenkatalog 26",4,"{\"canonical_url\":null,\"normalized_sha256\":\"964d24cd41f50e75b8bb1d06f76d9cc47af41a110c36b4bb8a20597a3a823500\",\"page\":26,\"source_id\":\"src_49e6bd4a29f18c068815\",\"source_sha256\":\"ad7a22df2cd5529c685aa7d10d878783f41dcf2902c4bb7c1a233c97810359ca\",\"source_version_id\":\"sv_ad7a22df2cd5529c685aa7d1\"}","288717789c3d3bb6bc82a21e8ecdc0ce8c9afdf9c4bd6fd4690922792553c377"],["chunk_c4518f2dd2a89ee145cd24f7","wiki/sources/fragenkatalog-annex-vii-data.md",49,"Seite 27","1.17 Muss weiterhin das Excel-Formular für baubedingte Zusatzleistungen ausgefüllt\r\n\r\nwerden oder erfolgt das zukünftig auch über ein digitales Tool?\r\n\r\nBis zur Einführung von TAF/TAP-TSI muss weiterhin via Excel-Liste bestellt werden.\r\n\r\n1.18 Mit der Herausgabe tagesscharf, das dann sicherlich auch EBula, werden wir arbeiten können. Ich prüfe ja auch den Regelfahrplan nicht jeden Tag. Wie sehe ich aber, dass\r\n\r\ndie Baumaßnahme korrekt verarbeitet wurde. Denn dafür müsste es ja sowas wie ein Angebot geben (ggf. auch tabellarisch).\r\n\r\nDer Prozess für die Abstimmung und Konsultation von Baumaßnahmen findet sich in der Richtlinie 402.0305 (Umsetzung Annex VII Prozess).\r\n\r\nWeitere Informationen finden Sie auf folgender Internetseite:\r\n\r\nhttps://www.dbinfrago.com/web/schienennetz/fahren_und_bauen/annex-vii-richtlinie-2012-34eu-11857512\r\n\r\n1.19 Was bedeutet der Zeitraum z-3? Bedeutet dies, dass ein EVU erst drei Tage vor der\r\n\r\nentsprechenden netzbedingten Einschränkung über diese Einschränkung informiert\r\n\r\nwird? Oder bedeutet dies, dass erst drei Tage vor der Einschränkung ein Fahrplan versendet wird? Oder handelt es sich hier nicht um Tage, sondern um Monate?\r\n\r\nDie Richtlinie 402.0305 (Umsetzung Annex VII Prozess) definiert Zeitpunkte, an denen sogenannte Verfügbarkeitseinschränkungen an die EVU kommuniziert werden müssen. Wie weit im\r\n\r\nVoraus eine Verfügbarkeitseinschränkung kommuniziert werden muss, hängt von verschiedenen Faktoren ab. Das \"z\" bedeutet immer \"Wochen vor Baubeginn\". Das bedeutet, \"z-3\" heißt\r\n\r\n\"3 Wochen vor Baubeginn\" wird der Zug am Verkehrstag mittels digitaler Baufplo versendet.\r\n\r\nWeitere Informationen finden Sie auf folgender Internetseite:\r\n\r\nhttps://www.dbinfrago.com/web/schienennetz/fahren_und_bauen/annex-vii-richtlinie-2012-34eu-11857512",217,"{\"canonical_url\":null,\"normalized_sha256\":\"964d24cd41f50e75b8bb1d06f76d9cc47af41a110c36b4bb8a20597a3a823500\",\"page\":27,\"source_id\":\"src_49e6bd4a29f18c068815\",\"source_sha256\":\"ad7a22df2cd5529c685aa7d10d878783f41dcf2902c4bb7c1a233c97810359ca\",\"source_version_id\":\"sv_ad7a22df2cd5529c685aa7d1\"}","d198482f7348da06112f3237bbb2ff7a7d3572fcfa15e87bc1e852f27cf7b662"],["chunk_ea0e6ba977e921b71f4b3110","wiki/sources/fragenkatalog-annex-vii-data.md",50,"Seite 27","1.20 Wie ist das Zusammenspiel und die Übermittlung der BauFplo-Fahrplaninformationen über die anderen Fahrplanschnittstellen der DB InfraGo (NSS mit GFD und BZD und\r\n\r\nzukünftig TAF/TAP TSI) vorgesehen? – Sind weiterhin Konstellationen möglich, wo Informationen zum nicht mehr gültigen Regelfahrplan erst nach der übermittelten BauFplo bei\r\n\r\nuns eintreffen?\r\n\r\nDie Richtlinie 402.0305 (Umsetzung Annex VII Prozess) sieht eine vorgegebene Reihenfolge\r\n\r\nder Veröffentlichung von Fahrplandokumenten vor, die den Regelprozess darstellt.\r\n\r\nWeitere Informationen finden Sie auf folgender Internetseite:\r\n\r\nhttps://www.dbinfrago.com/web/schienennetz/fahren_und_bauen/annex-vii-richtlinie-2012-34eu-11857512\r\n\r\n1.21 Was genau wird unter einer netzausgelösten Änderung verstanden? Worin besteht\r\n\r\nder Unterschied zu einer BauFplo? In welchem Format erhalten wir die NAÄ?\r\n\r\nIn Abschnitt 8 Absatz 6 der Richtlinie 402.0305 der INB 2027 sind Regelungen zur BauFplo und\r\n\r\nnetzausgelösten Änderung (NAÄ) enthalten. Mit der NÄA werden die vertragsrelevanten Vorgaben aus der FPE umgesetzt, deswegen löst die DB InfraGO AG mit der Bereitstellung des FPE\r\n\r\nzeitgleich die NAÄ aus. Im Gegensatz dazu ist die BauFplo ein betriebliches Informationsdokument. Sie informiert die Triebfahrzeugführenden und den Betrieb über alle baubedingten Auswirkungen auf den Zuglauf. Die NAÄ wird über das TPN an das EVU übermittelt. Die BauFplo\r\n\r\nkann im digitalen Datenformat (XML, JSON) über eine Schnittstelle abgerufen werden, wird\r\n\r\naber gleichzeitig auch noch als PDF-Format per E-Mail versendet.\r\n\r\nV.IWF 41 Fragenkatalog 27",204,"{\"canonical_url\":null,\"normalized_sha256\":\"964d24cd41f50e75b8bb1d06f76d9cc47af41a110c36b4bb8a20597a3a823500\",\"page\":27,\"source_id\":\"src_49e6bd4a29f18c068815\",\"source_sha256\":\"ad7a22df2cd5529c685aa7d10d878783f41dcf2902c4bb7c1a233c97810359ca\",\"source_version_id\":\"sv_ad7a22df2cd5529c685aa7d1\"}","4e87673bc84606adeb075691efe6cbcd05cd84719bb220cea9438caf3b80e93d"],["chunk_b8ea77da011e9bad4c8cf2c6","wiki/sources/fragenkatalog-annex-vii-data.md",51,"Seite 28","1.22 Damit RNE eindeutige IST-Zeiten liefern kann, bedarf es einer Übereinstimmung der\r\n\r\ngelieferten und der gefahrenen Ortsverläufe. Werden Informationen zu Fahrzeiten und\r\n\r\nOrtsverläufen aus der BauFplo auch in der Datenlieferung an die RNE enthalten sein und\r\n\r\ndamit im RNE TIS abrufbar?\r\n\r\nAuf der BauFplo wird es zum aktuellen Kenntnisstand keine TAF/TAP-TSI-Identifier geben, da\r\n\r\ndie Spezifikation zu TAF/TAP-TSI keine Vorgaben zur BauFplo macht.\r\n\r\n1.23 Wie wird sichergestellt, dass alle Verkehre einen Fahrplan bekommt, wo heute nur\r\n\r\nmit Trickserei (keine konfliktfreie Planung oder weiter +XX) überhaupt was möglich ist?\r\n\r\nDer Prozess für die Abstimmung und Konsultation von Baumaßnahmen findet sich in der Richtlinie 402.0305 (Umsetzung Annex VII Prozess).\r\n\r\nWeitere Informationen finden Sie auf folgender Internetseite:\r\n\r\nhttps://www.dbinfrago.com/web/schienennetz/fahren_und_bauen/annex-vii-richtlinie-2012-34eu-11857512\r\n\r\n1.24 Gibt es eine \"deadline\", ab wann es keine Änderungen zur Fplo mehr gibt bzw geben\r\n\r\ndarf?\r\n\r\nDie Richtlinie 402.0305 (Umsetzung Annex VII Prozess) definiert Zeitpunkte, an denen sogenannte Verfügbarkeitseinschränkungen an die EVU kommuniziert werden müssen. Wie weit im\r\n\r\nVoraus eine Verfügbarkeitseinschränkung kommuniziert werden muss, hängt von verschiedenen Faktoren ab. Das \"z\" bedeutet immer \"Wochen vor Baubeginn\". Das bedeutet, \"z-3\" heißt\r\n\r\n\"3 Wochen vor Baubeginn\" wird der Zug am Verkehrstag mittels digitaler Baufplo versendet.\r\n\r\nWeitere Informationen finden Sie auf folgender Internetseite:\r\n\r\nhttps://www.dbinfrago.com/web/schienennetz/fahren_und_bauen/annex-vii-richtlinie-2012-34eu-11857512\r\n\r\n1.25 Wenn mehrere Baumaßnahmen in unterschiedlichen Regionen durchfahren werden,\r\n\r\nist die zeitliche Konsistenz sichergestellt?",210,"{\"canonical_url\":null,\"normalized_sha256\":\"964d24cd41f50e75b8bb1d06f76d9cc47af41a110c36b4bb8a20597a3a823500\",\"page\":28,\"source_id\":\"src_49e6bd4a29f18c068815\",\"source_sha256\":\"ad7a22df2cd5529c685aa7d10d878783f41dcf2902c4bb7c1a233c97810359ca\",\"source_version_id\":\"sv_ad7a22df2cd5529c685aa7d1\"}","df0054a051638913be990a4b980215fcf09daedae44866ebdaaf896f0f44802e"],["chunk_12129e18cc50c8cb7d9b644d","wiki/sources/fragenkatalog-annex-vii-data.md",52,"Seite 28","Mit der Einführung von TAF/TAP-TSI und gemäß der Richtlinie 402.0305 der INB 2027 (Umsetzung Annex VII Prozess) wird es im FPE keine räumlichen Inkonsistenzen mehr geben und somit würden sie auch nicht in der BauFplo sichtbar sein. Zeitliche Inkonsistenzen können wir aktuell leider nicht ausschließen. An dieser Thematik arbeiten wir weiterhin.\r\n\r\n1.26 Mit welchem Vorlauf wird die digitale BauFplo versendet?\r\n\r\nDie Richtlinie 402.0305 (Umsetzung Annex VII Prozess) definiert Zeitpunkte, an denen sogenannte Verfügbarkeitseinschränkungen an die EVU kommuniziert werden müssen. Wie weit im\r\n\r\nVoraus eine Verfügbarkeitseinschränkung kommuniziert werden muss, hängt von verschiedenen Faktoren ab. Das \"z\" bedeutet immer \"Wochen vor Baubeginn\". Das bedeutet, \"z-3\" heißt\r\n\r\n\"3 Wochen vor Baubeginn\" wird der Zug am Verkehrstag mittels digitaler Baufplo versendet.\r\n\r\nWeitere Informationen finden Sie auf folgender Internetseite:\r\n\r\nhttps://www.dbinfrago.com/web/schienennetz/fahren_und_bauen/annex-vii-richtlinie-2012-34eu-11857512\r\n\r\n1.27 Identifikatoren für Betriebsstellen im Zuglauf: Alle Datenelemente, die eine Betriebsstelle referenzieren (z.B. /content/fahrplan/laufwegänderung/betriebsstelle), verwenden in\r\n\r\nder digitale BauFplo weiterhin den herkömmlichen RL100-Code zur Identifikation der Betriebsstelle. Künftig mit TAF/TAP TSI werden jedoch die PrimaryLocationCodes (PLC) der\r\n\r\nführende und alleinige Identifikator für Betriebsstellen sein. Beabsichtigen Sie, die digitale BauFplo auf die PLC-Systematik umzustellen (spätestens mit Einführung von TTT im\r\n\r\nBereich Fahrplan der DB InfraGO ab JFpl 2027)? Hinweis: Die Verwendung von PLC/SLC\r\n\r\nV.IWF 41 Fragenkatalog 28",201,"{\"canonical_url\":null,\"normalized_sha256\":\"964d24cd41f50e75b8bb1d06f76d9cc47af41a110c36b4bb8a20597a3a823500\",\"page\":28,\"source_id\":\"src_49e6bd4a29f18c068815\",\"source_sha256\":\"ad7a22df2cd5529c685aa7d10d878783f41dcf2902c4bb7c1a233c97810359ca\",\"source_version_id\":\"sv_ad7a22df2cd5529c685aa7d1\"}","d0d523d6115eb8f5a63b7978f7c132c300a951e1ccdfdf932a15acbff536b262"],["chunk_00b00ecdb56d761432a77f4d","wiki/sources/fragenkatalog-annex-vii-data.md",53,"Seite 29","zur Identifikation von Betriebsstellen ist ein europäischer Standard/Vorgabe gemäß\r\n\r\nTAF/TAP TSI.\r\n\r\nWir werden auch die Veröffentlichungsdokumente, wie die BauFplo, in einen TAF/TAP-TSI-konformen Zustand überführen. Allerdings werden weiterhin RL 100-Codes für die Betriebsstellen\r\n\r\nangezeigt.\r\n\r\n1.28 Datentypen und Validierungen: Sie verwenden vielfach den Datentyp „String“ für Attribute, die eigentlich eine wohlbekannte Wertemenge darstellen und deshalb nach Stand\r\n\r\nder Technik als Enumeration definiert werden sollten – Beispiel: Bremsstellung – oder\r\n\r\nfür die man auf andere Art eine Einschränkung der erlaubten Wertemenge vornehmen\r\n\r\nsollte – Beispiel: statt die KV-Profile einfach nur als „String“ zu definieren wäre der Stand\r\n\r\nder Technik, auf diesem String eine Einschränkung wie <pattern value=\"\\d{3}\"/> zu definieren. Aus meiner Sicht entspricht die aktuelle Vorgabe nicht dem Stand der Technik,\r\n\r\nund die wesentlichen Vorgaben hätten leicht aus dem TAF/TAP TSI-Standard übernommen werden können.\r\n\r\nUm die Schnittstelle flexibel nutzbar zu halten, wurde zunächst auf generische Typen gesetzt.\r\n\r\nZudem ist die BauFplo nicht unmittelbar an den TAF/TAP-TSI-Standard gebunden, da es sich\r\n\r\num Dokumente für die Durchführung der Zugfahrt handelt, deren Einführung zeitlich versetzt zu\r\n\r\nden TAF/TAP-TSI-Vorgaben erfolgt.\r\n\r\n1.29 Zugnummer, OTN und TrainID: Sie verwenden die generische Bezeichnung „Zugnummer“ (z.B. /content/zug/nummer). Ist damit gemeint:\r\n\r\n- die „klassische“ Zugnummer heutiger Prägung gemeint\r\n\r\n- die betriebliche Zugnummer nach TAF/TAP TSI Standard, die sog. OTN\r\n\r\n- die planerische Zugnummer nach TAF/TAP TSI Standard, die sog. TrainID\r\n\r\n(jetzt und auch nach Einführung von TAF/TAP TSI in Fahrplan und Betrieb ab JFpl 2027)",233,"{\"canonical_url\":null,\"normalized_sha256\":\"964d24cd41f50e75b8bb1d06f76d9cc47af41a110c36b4bb8a20597a3a823500\",\"page\":29,\"source_id\":\"src_49e6bd4a29f18c068815\",\"source_sha256\":\"ad7a22df2cd5529c685aa7d10d878783f41dcf2902c4bb7c1a233c97810359ca\",\"source_version_id\":\"sv_ad7a22df2cd5529c685aa7d1\"}","d4ff5caf5b14e5cdbc749de9c42477ff4074d7ae552770d629410a68fdbf333f"],["chunk_fd8c081927afb7f6ba1e65a1","wiki/sources/fragenkatalog-annex-vii-data.md",54,"Seite 29","Mit „Zugnummer“ ist im Kontext der BauFplo die betriebliche Zugnummer (OTN) nach TAF/TAP\r\n\r\nTSI gemeint.\r\n\r\n1.30 Technische Abstimmung mit \"Fahrplan\" und \"Betrieb\" bei DB InfraGO\r\n\r\nGibt es an irgendeiner andere Stelle Abstimmungen mit den Datenformaten und den Datenstrukturen, die die TAF/TAP TSI kompatiblen Systeme der DB InfraGO verwenden (PathOS, BDV Betriebsdatenverteiler, etc.)?\r\n\r\nMein erster Eindruck ist, dass das Format der „digitalen BauFplo“ von diesen Standards\r\n\r\nkomplett losgelöst definiert ist.\r\n\r\nFür Mitte 2026 ist vorgesehen, die Veröffentlichungsdokumente – einschließlich der BauFplo –\r\n\r\nin einen TAF/TAP TSI-konformen Zustand zu überführen.\r\n\r\nAktuell ist die BauFplo noch losgelöst von den TAF/TAP TSI-Strukturen, da diese Vorgaben\r\n\r\nsich nicht auf die Fahrplandokumente beziehen.\r\n\r\n1.31 Frage zur Einführung der digitalen FPLO: Mein Verständnis ist, das mit der Einführung TAP-TSI / Annex VII zum Fahrplan 2027 komplett auf die digitale FPLO umgestellt\r\n\r\nwird. Meine Frage bezieht sich auf den Einführungspfad: Was bedeutet das für den Hochlauf ab ca. 08/26? Werden alle Dokumente, die sich auf den Fpl 2027 beziehen automatisch im neuen Format versendet? Dokumente mit Bezug bis zum Datum des Fpl-Wechsels (also noch der komplette Fahrplan 2026) werden über den alten Weg und Formate\r\n\r\nkommuniziert?\r\n\r\nV.IWF 41 Fragenkatalog 29",192,"{\"canonical_url\":null,\"normalized_sha256\":\"964d24cd41f50e75b8bb1d06f76d9cc47af41a110c36b4bb8a20597a3a823500\",\"page\":29,\"source_id\":\"src_49e6bd4a29f18c068815\",\"source_sha256\":\"ad7a22df2cd5529c685aa7d10d878783f41dcf2902c4bb7c1a233c97810359ca\",\"source_version_id\":\"sv_ad7a22df2cd5529c685aa7d1\"}","0c0ce5c2178f68abd49e59739fcf803646160068663b99cd6dac7dce9cc23512"],["chunk_81aabd7a6f990bb27d2a7553","wiki/sources/fragenkatalog-annex-vii-data.md",55,"Seite 30","Wird eine Bautrasse nach Richtlinie 402.0305 (Umsetzung Annex VII Prozess) konsultiert und\r\n\r\nmit einem GPE, FPE und NAÄ veröffentlicht, wird es nur im neuen Format möglich sein die\r\n\r\nBauFplo zu versenden. Ab Oktober 2026 muss mit dem Format gerechnet werden.\r\n\r\n1.32 Inwiefern ist die Einführung der digitalen BauFplo mit der Einführung von Taf/Tap\r\n\r\nTSI zusammenhängend? Welche technischen Gründe liegen für einen Zusammenhang\r\n\r\nder Einführung von Taf/Tap TSI und der digitalen BauFplo vor?\r\n\r\nGenerell ist die Einführung der digitalen BauFplo nicht von TAF/TAP-TSI abhängig. Die DVO\r\n\r\n2017/2075 (Umsetzung Annex VII Prozess) schreibt aber einen Zugbezug vor. Mit dem FPE\r\n\r\nund GPE veröffentlichen wir zugbezogen, daher brauchen wir aber auch eine neue Form der\r\n\r\nBauFplo.\r\n\r\n1.33 Wir schreiben das Fahrplanjahr 2027. TTT ist erfolgreich eingeführt. Dann erhalten\r\n\r\nwir für jede Veränderung an der Trasse, egal mit welchem Vorlauf immer eine PDM durch\r\n\r\nInfraGO mit dem letzten gültigen laufweg und Zeiten. Wird dann für jede dieser Versionen\r\n\r\nauch immer automatisch ein Dokument in BSV angestoßen?\r\n\r\nWenn es nach der Richtlinie 402.0305 der INB 2027 (Umsetzung Annex VII Prozess) ein FPE\r\n\r\nund ein NAÄ gibt, dann gibt es auch eine BauFplo aus BSV. Zu einer anderen PDM, die es aus\r\n\r\nanderen Fahrplanphasen oder vom Betrieb geben kann, wird es keine BauFplo aus BSV geben.\r\n\r\n1.34 Wenn ein Zuglauf unterbrochen wird, z.B. Zug 18412 verkehrt nicht von A bis Z sondern nur von A bis B, dann Ausfall und dann wieder von X bis Z. Der ''hintere'' Zug\r\n\r\nbraucht eine neue Zugnummer. Die wird von InfraGO vergeben und nicht von mir als\r\n\r\nEVU. Erkennt man den Zusammenhang zwischen diesen Zügen?\r\n\r\nIn der digitalen BauFplo ist in diesem Fall kein Bezug bei der Trasse mit der neuen Zugnummer",282,"{\"canonical_url\":null,\"normalized_sha256\":\"964d24cd41f50e75b8bb1d06f76d9cc47af41a110c36b4bb8a20597a3a823500\",\"page\":30,\"source_id\":\"src_49e6bd4a29f18c068815\",\"source_sha256\":\"ad7a22df2cd5529c685aa7d10d878783f41dcf2902c4bb7c1a233c97810359ca\",\"source_version_id\":\"sv_ad7a22df2cd5529c685aa7d1\"}","f61b33b10d3f6b89e3799ff1fb337f0692b4ac2b9c72fc25000b0ba70d524115"],["chunk_fc1fbea1626def80ed4c45c6","wiki/sources/fragenkatalog-annex-vii-data.md",56,"Seite 30","auf die Originaltrasse ersichtlich. Dieser kann aus dem dazugehörigen FPE ermittelt werden.\r\n\r\nDas FPE enthält das Attribut pathIdOld aus TTT, über dieses die Referenz zur Originaltrasse\r\n\r\nherge-stellt werden kann.\r\n\r\nWenn über das Bestellportal pathOS eine baubedingte Zusatzleistung bestellt wird, so ist die\r\n\r\nPathId, auf die sich die zusätzliche Trasse bezieht, dort anzugeben (z.B. baubetroffene Trasse\r\n\r\nenthält Teilausfall, die baubedingte Zusatzleistung ist die Leerfahrt in die Abstellung, in diesem\r\n\r\nFall wird auf die pathId der baubetroffenen Trasse (FPE) referenziert).\r\n\r\n1.35 Ist aus der BauFplo bei Bauzugnummern der Bezug zur ursprünglichen Zugnummer\r\n\r\nersichtlich?\r\n\r\nIn der digitalen BauFplo ist in diesem Fall kein Bezug bei der Trasse mit der neuen Zugnummer\r\n\r\nauf die Originaltrasse ersichtlich. Dieser kann aus dem dazugehörigen FPE ermittelt werden.\r\n\r\nDas FPE enthält das Attribut pathIdOld aus TTT, über dieses die Referenz zur Originaltrasse\r\n\r\nherge-stellt werden kann.\r\n\r\nWenn über das Bestellportal pathOS eine baubedingte Zusatzleistung bestellt wird, so ist die\r\n\r\nPathId, auf die sich die zusätzliche Trasse bezieht, dort anzugeben (z.B. baubetroffene Trasse\r\n\r\nenthält Teilausfall, die baubedingte Zusatzleistung ist die Leerfahrt in die Abstellung, in diesem\r\n\r\nFall wird auf die pathId der baubetroffenen Trasse (FPE) referenziert).\r\n\r\n1.36 Ist in den digitalen FPLOen bei einem Ersatzzug der ursprüngliche Zug (Originalzug)\r\n\r\nersichtlich?\r\n\r\nIn der digitalen BauFplo ist in diesem Fall kein Bezug bei der Trasse mit der neuen Zugnummer\r\n\r\nauf die Originaltrasse ersichtlich. Dieser kann aus dem dazugehörigen FPE ermittelt werden.\r\n\r\nDas FPE enthält das Attribut pathIdOld aus TTT, über dieses die Referenz zur Originaltrasse\r\n\r\nherge-stellt werden kann.",246,"{\"canonical_url\":null,\"normalized_sha256\":\"964d24cd41f50e75b8bb1d06f76d9cc47af41a110c36b4bb8a20597a3a823500\",\"page\":30,\"source_id\":\"src_49e6bd4a29f18c068815\",\"source_sha256\":\"ad7a22df2cd5529c685aa7d10d878783f41dcf2902c4bb7c1a233c97810359ca\",\"source_version_id\":\"sv_ad7a22df2cd5529c685aa7d1\"}","f025e0e34fdde66c0e5a7549a51a75ef0c56fb8da71ec9fabb4121f7683071ab"],["chunk_59a5581936c58745142cabce","wiki/sources/fragenkatalog-annex-vii-data.md",57,"Seite 30","Wenn über das Bestellportal pathOS eine baubedingte Zusatzleistung bestellt wird, so ist die\r\n\r\nPathId, auf die sich die zusätzliche Trasse bezieht, dort anzugeben (z.B. baubetroffene Trasse\r\n\r\nenthält Teilausfall, die baubedingte Zusatzleistung ist die Leerfahrt in die Abstellung, in diesem\r\n\r\nFall wird auf die pathId der baubetroffenen Trasse (FPE) referenziert).\r\n\r\nV.IWF 41 Fragenkatalog 30",53,"{\"canonical_url\":null,\"normalized_sha256\":\"964d24cd41f50e75b8bb1d06f76d9cc47af41a110c36b4bb8a20597a3a823500\",\"page\":30,\"source_id\":\"src_49e6bd4a29f18c068815\",\"source_sha256\":\"ad7a22df2cd5529c685aa7d10d878783f41dcf2902c4bb7c1a233c97810359ca\",\"source_version_id\":\"sv_ad7a22df2cd5529c685aa7d1\"}","c27ce662666d0ee69db9148c85a68f48da49f2993a6ccc6e37c0ac2646175ba3"],["chunk_4f3dd2f537d880ddb724e505","wiki/sources/fragenkatalog-annex-vii-data.md",58,"Seite 31","1.37 (Wo/Wie) Ist bei baubedingten Zusatz-/Ersatzleistungen der Zusammenhang zur Ursprungsleistung erkennbar?\r\n\r\nIn der digitalen BauFplo ist in diesem Fall kein Bezug bei der Trasse mit der neuen Zugnummer\r\n\r\nauf die Originaltrasse ersichtlich. Dieser kann aus dem dazugehörigen FPE ermittelt werden.\r\n\r\nDas FPE enthält das Attribut pathIdOld aus TTT, über dieses die Referenz zur Originaltrasse\r\n\r\nherge-stellt werden kann.\r\n\r\nWenn über das Bestellportal pathOS eine baubedingte Zusatzleistung bestellt wird, so ist die\r\n\r\nPathId, auf die sich die zusätzliche Trasse bezieht, dort anzugeben (z.B. baubetroffene Trasse\r\n\r\nenthält Teilausfall, die baubedingte Zusatzleistung ist die Leerfahrt in die Abstellung, in diesem\r\n\r\nFall wird auf die pathId der baubetroffenen Trasse (FPE) referenziert).\r\n\r\n1.38 Ist bei Bauzugnummern (z.B. Ersatzzug nach Ausfall mitten im Regelzuglauf) der Bezug zum ursprünglichen Zug erkennbar, bzw. umgekehrt, das eine neue Zugnummern\r\n\r\nnach der Baustelle verkehrt?\r\n\r\nIn der digitalen BauFplo ist in diesem Fall kein Bezug bei der Trasse mit der neuen Zugnummer\r\n\r\nauf die Originaltrasse ersichtlich. Dieser kann aus dem dazugehörigen FPE ermittelt werden.\r\n\r\nDas FPE enthält das Attribut pathIdOld aus TTT, über dieses die Referenz zur Originaltrasse\r\n\r\nherge-stellt werden kann.\r\n\r\nWenn über das Bestellportal pathOS eine baubedingte Zusatzleistung bestellt wird, so ist die\r\n\r\nPathId, auf die sich die zusätzliche Trasse bezieht, dort anzugeben (z.B. baubetroffene Trasse\r\n\r\nenthält Teilausfall, die baubedingte Zusatzleistung ist die Leerfahrt in die Abstellung, in diesem\r\n\r\nFall wird auf die pathId der baubetroffenen Trasse (FPE) referenziert).\r\n\r\n1.39 Ist die folgende Annahme richtig? Ein Ausfall ist in BSV X für Zug 1 geregelt, in BSV",246,"{\"canonical_url\":null,\"normalized_sha256\":\"964d24cd41f50e75b8bb1d06f76d9cc47af41a110c36b4bb8a20597a3a823500\",\"page\":31,\"source_id\":\"src_49e6bd4a29f18c068815\",\"source_sha256\":\"ad7a22df2cd5529c685aa7d10d878783f41dcf2902c4bb7c1a233c97810359ca\",\"source_version_id\":\"sv_ad7a22df2cd5529c685aa7d1\"}","14d464df97ff10dc92d8b37f5a9c5fde070d2d1e2f5966025a52bd4184beb15b"],["chunk_f682e290df2833dd54dc958e","wiki/sources/fragenkatalog-annex-vii-data.md",59,"Seite 31","Y ist dann der Ersatzzug für Zug 1 aus BSV X als zusätzlicher Zug abgebildet. Diese Verknüpfung ist auch in BSV Y erkennbar.\r\n\r\nIn der digitalen BauFplo ist in diesem Fall kein Bezug bei der Trasse mit der neuen Zugnummer\r\n\r\nauf die Originaltrasse ersichtlich. Dieser kann aus dem dazugehörigen FPE ermittelt werden.\r\n\r\nDas FPE enthält das Attribut pathIdOld aus TTT, über dieses die Referenz zur Originaltrasse\r\n\r\nherge-stellt werden kann.\r\n\r\nWenn über das Bestellportal pathOS eine baubedingte Zusatzleistung bestellt wird, so ist die\r\n\r\nPathId, auf die sich die zusätzliche Trasse bezieht, dort anzugeben (z.B. baubetroffene Trasse\r\n\r\nenthält Teilausfall, die baubedingte Zusatzleistung ist die Leerfahrt in die Abstellung, in diesem\r\n\r\nFall wird auf die pathId der baubetroffenen Trasse (FPE) referenziert).\r\n\r\n1.40 In dem zu Verfügung gestellten xml Dokument sehe ich kein Attribut, welches auf\r\n\r\neinen Verweis zu einem anderen Zug schließen lässt. Ist es sichergestellt, dass Züge, die\r\n\r\naufgrund von Baumaßnahmen ausfallen und aufgrund derer ein neuer (Ersatz)zug hinzu\r\n\r\nkommt, diese Verknüpfung sichtbar ist? Nicht SEV.\r\n\r\nIn der digitalen BauFplo ist in diesem Fall kein Bezug bei der Trasse mit der neuen Zugnummer\r\n\r\nauf die Originaltrasse ersichtlich. Dieser kann aus dem dazugehörigen FPE ermittelt werden.\r\n\r\nDas FPE enthält das Attribut pathIdOld aus TTT, über dieses die Referenz zur Originaltrasse\r\n\r\nherge-stellt werden kann.\r\n\r\nWenn über das Bestellportal pathOS eine baubedingte Zusatzleistung bestellt wird, so ist die\r\n\r\nPathId, auf die sich die zusätzliche Trasse bezieht, dort anzugeben (z.B. baubetroffene Trasse\r\n\r\nenthält Teilausfall, die baubedingte Zusatzleistung ist die Leerfahrt in die Abstellung, in diesem\r\n\r\nFall wird auf die pathId der baubetroffenen Trasse (FPE) referenziert).",259,"{\"canonical_url\":null,\"normalized_sha256\":\"964d24cd41f50e75b8bb1d06f76d9cc47af41a110c36b4bb8a20597a3a823500\",\"page\":31,\"source_id\":\"src_49e6bd4a29f18c068815\",\"source_sha256\":\"ad7a22df2cd5529c685aa7d10d878783f41dcf2902c4bb7c1a233c97810359ca\",\"source_version_id\":\"sv_ad7a22df2cd5529c685aa7d1\"}","1d0ca2e418c60e275f4fe738a05441af12416c21bae9ab8dbca0a5157a1a4a59"],["chunk_359a5e11a30df0ed00de1b32","wiki/sources/fragenkatalog-annex-vii-data.md",60,"Seite 31","1.41 Wo / wie erfolgt die Zuordnung einer Bau-Zugnummer zur Regelzugnummer?\r\n\r\nIn der digitalen BauFplo ist in diesem Fall kein Bezug bei der Trasse mit der neuen Zugnummer\r\n\r\nauf die Originaltrasse ersichtlich. Dieser kann aus dem dazugehörigen FPE ermittelt werden.\r\n\r\nDas FPE enthält das Attribut pathIdOld aus TTT, über dieses die Referenz zur Originaltrasse\r\n\r\nherge-stellt werden kann.\r\n\r\nV.IWF 41 Fragenkatalog 31",61,"{\"canonical_url\":null,\"normalized_sha256\":\"964d24cd41f50e75b8bb1d06f76d9cc47af41a110c36b4bb8a20597a3a823500\",\"page\":31,\"source_id\":\"src_49e6bd4a29f18c068815\",\"source_sha256\":\"ad7a22df2cd5529c685aa7d10d878783f41dcf2902c4bb7c1a233c97810359ca\",\"source_version_id\":\"sv_ad7a22df2cd5529c685aa7d1\"}","4544430246acdc07e44374af3b11127a5a542183577bd0d353a5267ad704e722"],["chunk_bb299b4d387fabcfe935748a","wiki/sources/fragenkatalog-annex-vii-data.md",61,"Seite 32","Wenn über das Bestellportal pathOS eine baubedingte Zusatzleistung bestellt wird, so ist die\r\n\r\nPathId, auf die sich die zusätzliche Trasse bezieht, dort anzugeben (z.B. baubetroffene Trasse\r\n\r\nenthält Teilausfall, die baubedingte Zusatzleistung ist die Leerfahrt in die Abstellung, in diesem\r\n\r\nFall wird auf die pathId der baubetroffenen Trasse (FPE) referenziert).\r\n\r\n1.42 Wie werden die Ersatzzugnummern abgebildet/vergeben auf dem Streckenabschnitt\r\n\r\nan dem der Zug weiterhin verkehren kann? Paradebeispiel hier wäre, wenn Züge durch\r\n\r\nvorzeitige Abfahrt am Startbahnhof einen Tagwechsel -1 bekommen.\r\n\r\nIn der digitalen BauFplo ist in diesem Fall kein Bezug bei der Trasse mit der neuen Zugnummer\r\n\r\nauf die Originaltrasse ersichtlich. Dieser kann aus dem dazugehörigen FPE ermittelt werden.\r\n\r\nDas FPE enthält das Attribut pathIdOld aus TTT, über dieses die Referenz zur Originaltrasse\r\n\r\nhergestellt werden kann.\r\n\r\nWenn über das Bestellportal pathOS eine baubedingte Zusatzleistung bestellt wird, so ist die\r\n\r\nPathId, auf die sich die zusätzliche Trasse bezieht, dort anzugeben (z.B. baubetroffene Trasse\r\n\r\nenthält Teilausfall, die baubedingte Zusatzleistung ist die Leerfahrt in die Abstellung, in diesem\r\n\r\nFall wird auf die pathId der baubetroffenen Trasse (FPE) referenziert).\r\n\r\n1.43 Was passiert dann mit kurzfristigen Baustellen, die nach den neuen Fristen für die\r\n\r\nFPLO ja dann viele Wochen sind? Wie soll das dann gelöst werden? Heute laufen wir den\r\n\r\nfehlerbehafteten FPLO bis zu einen Tag vor Gültigkeit hinterher.\r\n\r\nDie Richtlinie 402.0305 (Umsetzung Annex VII Prozess) definiert Zeitpunkte, an denen sogenannte Verfügbarkeitseinschränkungen an die ZB kommuniziert werden müssen. Wie weit im",235,"{\"canonical_url\":null,\"normalized_sha256\":\"964d24cd41f50e75b8bb1d06f76d9cc47af41a110c36b4bb8a20597a3a823500\",\"page\":32,\"source_id\":\"src_49e6bd4a29f18c068815\",\"source_sha256\":\"ad7a22df2cd5529c685aa7d10d878783f41dcf2902c4bb7c1a233c97810359ca\",\"source_version_id\":\"sv_ad7a22df2cd5529c685aa7d1\"}","40495b91fb31042e50515e6b0f37ffd1b12a09c1db462410f6812ece3e197458"],["chunk_3e2c0d412f952897e5a178b7","wiki/sources/fragenkatalog-annex-vii-data.md",62,"Seite 32","Voraus eine Verfügbarkeitseinschränkung kommuniziert werden muss, hängt von verschiedenen Faktoren ab. Das \"z\" bedeutet immer \"Wochen vor Baubeginn\". Das bedeutet, \"z-3\" heißt\r\n\r\n\"3 Wochen vor Baubeginn\" wird der Zug am Verkehrstag mittels digitaler Baufplo versendet.\r\n\r\nWeitere Informationen finden Sie auf folgender Internetseite:\r\n\r\nhttps://www.dbinfrago.com/web/schienennetz/fahren_und_bauen/annex-vii-richtlinie-2012-34eu-11857512\r\n\r\n1.44 Kann man davon ausgehen, dass es also für jede digitale BauFplo einen Vertragszustand in Path OS (NAE) geben wird? Für alle BKE Kategorien?\r\n\r\nZu jeder BauFplo wird es auch eine NAÄ geben. Dies gilt ebenfalls für verschiedene Kategorien\r\n\r\nder BKE. Allerdings werden BKEn auch bei der Erstellung des Netzfahrplan berücksichtigt.\r\n\r\nDiese bekommen entsprechend keine BauFplo, sondern werden im Rahmen des Netzfahrplanes veröffentlicht.\r\n\r\n1.45 Wie wird sichergestellt dass die aktuellen vorhandenen Trassen Konstruktionsgrenzen ,innerhalb von InfraGO, nicht mehr vorhanden sind?\r\n\r\nDer Arbeitsprozess zur überregionalen Bearbeitung basiert auf der in der Richtlinie 402.0305\r\n\r\n(Umsetzung Annex VII Prozess) enthaltenen Zugsicht der Trasse. Wir stellen die überregionale\r\n\r\nBearbeitung mithilfe geeigneter IT-Unterstützung sicher.\r\n\r\n1.46 Wie wird mit einer kurzfristigen Rücknahme einer Fplo umgegangen, wenn bspw.\r\n\r\neine Baustelle abgesagt wird, aber schon die Fplo veröffentlicht wurde? Wird für diesen\r\n\r\nFall eine neue Tages/Zugscharfe Fplo versendet und was passiert mit ggf. vorhandenen\r\n\r\nFahrzeitverlängerungen?\r\n\r\nGemäß Richtlinie 402.0305 (Umsetzung Annex VII Prozess) ist eine Rücknahme der BauFplo\r\n\r\nkünftig nicht mehr vorgesehen. Ab z-8 Wochen sind Änderungen an der Bautrasse nicht mehr",216,"{\"canonical_url\":null,\"normalized_sha256\":\"964d24cd41f50e75b8bb1d06f76d9cc47af41a110c36b4bb8a20597a3a823500\",\"page\":32,\"source_id\":\"src_49e6bd4a29f18c068815\",\"source_sha256\":\"ad7a22df2cd5529c685aa7d10d878783f41dcf2902c4bb7c1a233c97810359ca\",\"source_version_id\":\"sv_ad7a22df2cd5529c685aa7d1\"}","aea6480d0288afe57779385a6e9de3909f2684b98defc87f0141bb87474eac77"],["chunk_dcf7660777dd94fef02997f9","wiki/sources/fragenkatalog-annex-vii-data.md",63,"Seite 32","möglich. Die FPE-Trasse bleibt bestehen, da die Bautrasse bereits als Regeltrasse geführt wird.\r\n\r\nWeitere Informationen finden Sie auf folgender Internetseite:\r\n\r\nhttps://www.dbinfrago.com/web/schienennetz/fahren_und_bauen/annex-vii-richtlinie-2012-34eu-11857512\r\n\r\nV.IWF 41 Fragenkatalog 32",25,"{\"canonical_url\":null,\"normalized_sha256\":\"964d24cd41f50e75b8bb1d06f76d9cc47af41a110c36b4bb8a20597a3a823500\",\"page\":32,\"source_id\":\"src_49e6bd4a29f18c068815\",\"source_sha256\":\"ad7a22df2cd5529c685aa7d10d878783f41dcf2902c4bb7c1a233c97810359ca\",\"source_version_id\":\"sv_ad7a22df2cd5529c685aa7d1\"}","bf043a5c882dda759651e892a002c05a045eb44b456c957f731307a0d1fe3835"],["chunk_08ea21a82a4d8abb0dd3c0e2","wiki/sources/fragenkatalog-annex-vii-data.md",64,"Seite 33","1.47 Aus nachvollziehbaren Gründen kann es ja vorkommen, dass DB InfragGO an den\r\n\r\nFahrzeiten und/oder Laufweg zwischen FPE/NAÄ und BauFplo Änderungen vornehmen\r\n\r\nmuss oder es aktualisierte Versionen zu einer bestehenden BauFplo gibt. In diesen beiden Fällen müsste das EVU doch auch zusätzlich eine NAÄ bekommen (FPE wahrscheinlich wegen Fristablauf nicht). Nur das EVU kann ja beurteilen, ob mit den vorhandenen\r\n\r\nProduktionsressourcen die geänderte Fahrlage auch produziert werden kann. Bekommen wir in solchen Fällen (entweder Unterschiede zwischen FPE/NAÄ und BauFplo oder\r\n\r\nmit aktualisierten Versionen einer BauFplo) auch parallel immer eine NAÄ?\r\n\r\nZu einer BauFplo gibt es immer das entsprechende NAÄ dazu.\r\n\r\n1.48 Was ist, wenn wir umlaufbedingt die Zugcharakteristik später ändern müssen?\r\n\r\nWird während der Konsultations-Stellungnahmephase zu einem GPE umlaufbedingt eine Anpassung der Zugcharakteristik erforderlich und hierzu Stellungnahme vom ZB abgegeben, wird\r\n\r\nlediglich das GPE bzw. in das GPEnS sowie ggf. das FPE die geänderte Zugcharakteristik aufgenommen, sofern diese umsetzbar ist angepasst. Wird eine berechtigte Änderung nach dem\r\n\r\nVersand des FPE ausgelöst dieser Konsultationsphase notwendig, wird eine neue FPE, NAÄ\r\n\r\nund digitale BauFplo mit der geänderten Zugcharakteristik ausgestellt, sofern umsetzbar. Alternativ kann eine Änderungsbestellung getätigt werden. Es wird auf Abschnitt 10 Abs. 7 der\r\n\r\nRichtlinie 402.0305 verwiesen.\r\n\r\nV.IWF 41 Fragenkatalog 33",200,"{\"canonical_url\":null,\"normalized_sha256\":\"964d24cd41f50e75b8bb1d06f76d9cc47af41a110c36b4bb8a20597a3a823500\",\"page\":33,\"source_id\":\"src_49e6bd4a29f18c068815\",\"source_sha256\":\"ad7a22df2cd5529c685aa7d10d878783f41dcf2902c4bb7c1a233c97810359ca\",\"source_version_id\":\"sv_ad7a22df2cd5529c685aa7d1\"}","6ac942fa11d12b98dba50ea1580339e3b6d29a426816ce39117f787e8dd09c68"],["chunk_202bedc1b09e6d494851c2c9","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-20-05-2026-data.md",0,"Seite 1","EVU-Informationsveranstaltung\r\n\r\nVertiefung Unterjähriger Baufahrplan\r\n\r\n20.05.2026 | Frankfurt am Main",9,"{\"canonical_url\":null,\"normalized_sha256\":\"d0cb958c05947116684430ae0560c742b54db3575d06994e5af0893cc8409a15\",\"page\":1,\"source_id\":\"src_c2cbe5f5c740b62f994d\",\"source_sha256\":\"ae1196f582f00718fd8357b517ce68ba5a5c7922ad24f2e0b3b9e4d0a50af0e2\",\"source_version_id\":\"sv_64747c1009b8c053966a8940\"}","1bd356cf9d4680435b7577a948bfcd7dacbe670d0ede912b1cc8589379ec435a"],["chunk_727596f5ed18ebb7778e5b4d","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-20-05-2026-data.md",1,"Seite 2","Agenda\r\n\r\nBegrüßung & Einleitung Willkommen! 5 min\r\n\r\nUnterjährige Fahrplanprodukte unter Annex VII 5 min\r\n\r\nÜberblick Annex VII\r\n\r\nDigitale BauFplo 15 min\r\n\r\nIhre Fragen und\r\n\r\nBeantwortung Ihrer Fragen 30 min\r\n\r\nHinweise\r\n\r\nAbschluss Nächste Schritte 5 min\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 20.05.2026 2",46,"{\"canonical_url\":null,\"normalized_sha256\":\"d0cb958c05947116684430ae0560c742b54db3575d06994e5af0893cc8409a15\",\"page\":2,\"source_id\":\"src_c2cbe5f5c740b62f994d\",\"source_sha256\":\"ae1196f582f00718fd8357b517ce68ba5a5c7922ad24f2e0b3b9e4d0a50af0e2\",\"source_version_id\":\"sv_64747c1009b8c053966a8940\"}","82cd1f4db1fc8f2b095b3be26dc534ce7ccd2569f067638ecc1d4e38bfd7ed74"],["chunk_be25d971ead0ab0b542d9e93","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-20-05-2026-data.md",2,"Seite 3","Hinweise\r\n\r\nfür den heutigen\r\n\r\nTeams Fragen & Antworten\r\n\r\nTermin\r\n\r\nFragen & Kommentare jederzeit während der Präsentation im Bereich „F&A“ in\r\n\r\nTeams schriftlich stellen\r\n\r\nkurz & auf den Punkt hilft uns beim späteren Beantworten\r\n\r\nVoice-Beiträge (Hand heben)\r\n\r\nWir freuen uns\r\n\r\nIn der Q&A-Phase am Ende des Termins\r\n\r\nüber eine aktive\r\n\r\nWir rufen auf; max. ~1 Minute pro Frage, damit viele zu Wort kommen\r\n\r\nTeilnahme. Ihre\r\n\r\nGedanken und\r\n\r\nWann antworten wir?\r\n\r\nFragen sind\r\n\r\nausdrücklich Am Ende des Termins in einer gebündelten Q&A-Runde\r\n\r\nWir sammeln und priorisieren währenddessen im Hintergrund\r\n\r\nwillkommen!\r\n\r\nZiel:\r\n\r\nMöglichst viele Fragen, möglichst klare Antworten – fair & respektvoll für alle.\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 20.05.2026 3",112,"{\"canonical_url\":null,\"normalized_sha256\":\"d0cb958c05947116684430ae0560c742b54db3575d06994e5af0893cc8409a15\",\"page\":3,\"source_id\":\"src_c2cbe5f5c740b62f994d\",\"source_sha256\":\"ae1196f582f00718fd8357b517ce68ba5a5c7922ad24f2e0b3b9e4d0a50af0e2\",\"source_version_id\":\"sv_64747c1009b8c053966a8940\"}","875373809cb060e3f173120e526f3ccccd3f25bb934c387b0b74248bb1c3459c"]]');
