INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_816bc0ed8b5a7f940bfec6cf","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-25-06-2026-data.md",16,"Seite 17","Fragen und Hinweise\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 25.06.2026 17",14,"{\"canonical_url\":null,\"normalized_sha256\":\"04d45c67744bc2d469d1351ec1a38b5214d8edefbe8062174abea1aebfb3c219\",\"page\":17,\"source_id\":\"src_ddd38c74e487946a0af2\",\"source_sha256\":\"e9e0a2f232ec0d5439cf916bb57c8fe191657c86e3f2dc38ada024bacbe0f342\",\"source_version_id\":\"sv_945698ce989da35cc526b067\"}","fa16b5f20f77a36f3c6126ce1ebc2af5d0d2d0ea83af288e65f1425c671d7569"],["chunk_070f7e63f2785d5fd2eb9915","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-25-06-2026-data.md",17,"Seite 18","Häufig gestellte Fragen – FAQ 1\r\n\r\nThema: Annex VII\r\n\r\nWenn man ein GPE, GPEnS oder FPE ablehnt, erfolgt die netzseitige Stornierung\r\n\r\nF\r\n\r\nder Trasse. Anschließend kann man im Rahmen des GelV eine neue Trasse\r\n\r\nbestellen. Wie ist in diesem Fall der Ablauf des nachgelagerten Prozesses? Wie\r\n\r\nsind die zeitlichen Eckpunkte zur Bearbeitung und späteren Veröffentlichung\r\n\r\ndieser Trasse? Ist die Anmeldung einer neuen Trasse im GelV direkt nach\r\n\r\nAblehnung möglich oder erst ab z-8 vor der relevanten Baumaßnahme? Was ist\r\n\r\nder späteste Zeitpunkt, zu dem eine Bestellung einer neuen Trasse im GelV in\r\n\r\ndiesen Fällen möglich ist?\r\n\r\nA\r\n\r\nGemäß der INB 2027 Ziffer 4.2.2.4 gelten zum Fahrplan 2027 die\r\n\r\nentsprechenden Fristen im Gelegenheitsverkehr. Siehe Abschnitt in\r\n\r\nden genannten INB.\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 25.06.2026 18",129,"{\"canonical_url\":null,\"normalized_sha256\":\"04d45c67744bc2d469d1351ec1a38b5214d8edefbe8062174abea1aebfb3c219\",\"page\":18,\"source_id\":\"src_ddd38c74e487946a0af2\",\"source_sha256\":\"e9e0a2f232ec0d5439cf916bb57c8fe191657c86e3f2dc38ada024bacbe0f342\",\"source_version_id\":\"sv_945698ce989da35cc526b067\"}","2c2f18b5b8957e456c853082c9be2d723fc1646c0645382ac2eca9fdb58a6fbc"],["chunk_f9d534244649a258a426bb41","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-25-06-2026-data.md",18,"Seite 19","Häufig gestellte Fragen – FAQ 2\r\n\r\nThema: Annex\r\n\r\nF\r\n\r\nKann auf eine bereits abgestimmte BKE 7 aus der 1. und 2.\r\n\r\nKonsultationsphase in der 3. Konsultationsphase noch ein BKE 2\r\n\r\nfolgen?\r\n\r\nA\r\n\r\nDer konsultierte Stand der 2.KP geht in den Netzfahrplan und bildet\r\n\r\ndie Grundlage für die Fpl.-Konzepte der 3.KP. D. h., abgestimmte BKE\r\n\r\nder 2.KP können mit BKE der 3.KP in der 3.KP bzw. BKE der 4.KP in\r\n\r\nder 4.KP nochmal zusätzlich koordiniert werden.\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 25.06.2026 19",86,"{\"canonical_url\":null,\"normalized_sha256\":\"04d45c67744bc2d469d1351ec1a38b5214d8edefbe8062174abea1aebfb3c219\",\"page\":19,\"source_id\":\"src_ddd38c74e487946a0af2\",\"source_sha256\":\"e9e0a2f232ec0d5439cf916bb57c8fe191657c86e3f2dc38ada024bacbe0f342\",\"source_version_id\":\"sv_945698ce989da35cc526b067\"}","934ed04a3bfcd101d139489a6a28b3fcced46df27fa2c269fc9c1c0dd405bb94"],["chunk_648f49e39933458cf2055a5e","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-25-06-2026-data.md",19,"Seite 20","Häufig gestellte Fragen – FAQ 3\r\n\r\nThema: IT\r\n\r\nF\r\n\r\nWie erfolgt die Übermittlung des Zeitraumes, wenn durch eine zusätzliche\r\n\r\nBaumaßnahme die Verkehrstage innerhalb eines GPE geteilt werden? Erhalten wir\r\n\r\nfür jede Nachricht einen Gültigkeitszeitraum von 7 Tagen oder ist auch ein\r\n\r\nverkürzter Zeitraum möglich?\r\n\r\nA\r\n\r\nDie Bautrasse des ursprünglichen GPE wird im Folgeprodukt um die\r\n\r\nbaubetroffenen Tage der neuen BKE eingekürzt. Für die\r\n\r\nbaubetroffenen Tage der neuen BKE versenden wir ebenfalls ein\r\n\r\nfristabhängiges Fahrplanprodukt.\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 25.06.2026 20",85,"{\"canonical_url\":null,\"normalized_sha256\":\"04d45c67744bc2d469d1351ec1a38b5214d8edefbe8062174abea1aebfb3c219\",\"page\":20,\"source_id\":\"src_ddd38c74e487946a0af2\",\"source_sha256\":\"e9e0a2f232ec0d5439cf916bb57c8fe191657c86e3f2dc38ada024bacbe0f342\",\"source_version_id\":\"sv_945698ce989da35cc526b067\"}","50e0c4f31c8c995f4756ec03fd1d24ab907450b0706d0334fa2f50b8df378cc6"],["chunk_97346e67b5c8ef15cc5a7362","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-25-06-2026-data.md",20,"Seite 21","Häufig gestellte Fragen – FAQ 4\r\n\r\nThema: Digitale BauFplo\r\n\r\nF\r\n\r\nWas passiert, wenn nach FPE (z-8) die Baumaßnahme abgesagt wird\r\n\r\nund anschließend das EVU über den Regelfahrplan-Prozess eine\r\n\r\nÄnderungsbestellung veranlasst? Werden dann Daten über die\r\n\r\nSchnittstelle der digitalen BauFplo gesendet?\r\n\r\nA\r\n\r\nFür Fahrplanjahr 2027 wird es über die BauFplo-Schnittstelle nur die\r\n\r\nBauFplo Daten geben. Bei einer Änderungsbestellung wird es wie im\r\n\r\naktuellen Fahrplanjahr eine Fplo (Netzfahrplan oder Sonderzug)\r\n\r\ngeben.\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 25.06.2026 21",80,"{\"canonical_url\":null,\"normalized_sha256\":\"04d45c67744bc2d469d1351ec1a38b5214d8edefbe8062174abea1aebfb3c219\",\"page\":21,\"source_id\":\"src_ddd38c74e487946a0af2\",\"source_sha256\":\"e9e0a2f232ec0d5439cf916bb57c8fe191657c86e3f2dc38ada024bacbe0f342\",\"source_version_id\":\"sv_945698ce989da35cc526b067\"}","c689d9f0992cb16b50019a4329d72cbfc7b2b4c671c9dad1a18cb86ce3356b1d"],["chunk_a196f1ace9db4181eff13201","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-25-06-2026-data.md",21,"Seite 22","Häufig gestellte Fragen – FAQ 5\r\n\r\nThema: Digitale BauFplo\r\n\r\nF Im Fahrplanjahr 2026 können laut FAQ eine Fplo entweder mit Baustellen- oder\r\n\r\nZugsicht veröffentlicht werden. Können wir davon ausgehen, dass, sollte im Fpl.\r\n\r\n2027 TTT nicht eingeführt werden, es diese zwei Möglichkeiten auch weiterhin\r\n\r\ngeben wird? Wird in diesem Fall an dem bestehenden Prozess mit ZvF, ÜB und\r\n\r\nFplo mit den heutigen Fristen festgehalten? Wovon ist es abhängig, ob eine\r\n\r\nZugsicht oder eine Baustellensicht verwendet wird, und welchen Einfluss bzw.\r\n\r\nAuswahlmöglichkeiten haben wir als EVU ?\r\n\r\nA\r\n\r\nWährend der Betriebserprobung in Fplj26 wird im direkten\r\n\r\nAustausch mit den ZB entschieden welche Züge in welchem Format\r\n\r\nveröffentlicht werden.\r\n\r\nDas aktuelle System zur Fplo–Erstellung muss aus verschiedenen\r\n\r\nGründen zum Fplj-Wechsel 27 abgeschaltet werden, weshalb es ab\r\n\r\ndiesem Zeitpunkt nur das neue Format der digitalen BauFplo geben\r\n\r\nwird.\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 25.06.2026 22",146,"{\"canonical_url\":null,\"normalized_sha256\":\"04d45c67744bc2d469d1351ec1a38b5214d8edefbe8062174abea1aebfb3c219\",\"page\":22,\"source_id\":\"src_ddd38c74e487946a0af2\",\"source_sha256\":\"e9e0a2f232ec0d5439cf916bb57c8fe191657c86e3f2dc38ada024bacbe0f342\",\"source_version_id\":\"sv_945698ce989da35cc526b067\"}","42d1dd11ce8d6775267145cf71977ec549e2d2f1eea678308df47466d7b3409b"],["chunk_a540abda1b9fecf26461fb00","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-25-06-2026-data.md",22,"Seite 23","Häufig gestellte Fragen – FAQ 6\r\n\r\nThema: Digitale BauFplo\r\n\r\nF\r\n\r\nGibt es feste Zeitpunkte für die Updates an der API für die digitale\r\n\r\nBauFplo? Bzw. wird man ev. sogar über eine E-Mail über anstehende\r\n\r\nÄnderungen informiert?\r\n\r\nA\r\n\r\nAuf unserer Homepage und in den EVU-\r\n\r\nKundeninformationsveranstaltungen informieren wir über\r\n\r\nÄnderungen an der Schnittstelle. Link zur Website: Digitale\r\n\r\nBaufahrplananordnung\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 25.06.2026 23",68,"{\"canonical_url\":null,\"normalized_sha256\":\"04d45c67744bc2d469d1351ec1a38b5214d8edefbe8062174abea1aebfb3c219\",\"page\":23,\"source_id\":\"src_ddd38c74e487946a0af2\",\"source_sha256\":\"e9e0a2f232ec0d5439cf916bb57c8fe191657c86e3f2dc38ada024bacbe0f342\",\"source_version_id\":\"sv_945698ce989da35cc526b067\"}","a57d0237e6ab83432b48c614d8c9da1f00923098915a262920a438d16ef4a8ee"],["chunk_42f19898dfc92070199b7e44","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-25-06-2026-data.md",23,"Seite 24","Zeit für Ihre Fragen\r\n\r\n30 Min.\r\n\r\nBitte stellen Sie ihre Fragen über die\r\n\r\nF&A-Funktion in Teams und voten Sie\r\n\r\ninteressante Fragen nach oben\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 25.06.2026 24",34,"{\"canonical_url\":null,\"normalized_sha256\":\"04d45c67744bc2d469d1351ec1a38b5214d8edefbe8062174abea1aebfb3c219\",\"page\":24,\"source_id\":\"src_ddd38c74e487946a0af2\",\"source_sha256\":\"e9e0a2f232ec0d5439cf916bb57c8fe191657c86e3f2dc38ada024bacbe0f342\",\"source_version_id\":\"sv_945698ce989da35cc526b067\"}","0b6b6341028c5fbb40f40500558e6cf050306c64d01076a03891e1a223323b8c"],["chunk_605a5f4b1c0cf9c62f8b7a4a","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-31-07-2026-data.md",0,"Seite 1","EVU-Informationsveranstaltung\r\n\r\nVertiefung Unterjähriger Baufahrplan\r\n\r\n31.07.2026 | Frankfurt am Main",9,"{\"canonical_url\":null,\"normalized_sha256\":\"eef5a3413f4bd077a678c695bba2facb8ff5c618bd310813e66f0e628dbaa618\",\"page\":1,\"source_id\":\"src_55f12bc0f78e6465ec63\",\"source_sha256\":\"18db5438ce86e06e01d7bc2da721c1ac26dbec8d9c61d8cea98165ac19f27baf\",\"source_version_id\":\"sv_fc73716a3f57a7991ffa7db4\"}","0dbdf70484df6ca52c1d01d9e62e9a6c525b267def739eb8cc56d2cf8c700ef5"],["chunk_1117b472368d1d3aa34bc6d6","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-31-07-2026-data.md",1,"Seite 2","Agenda\r\n\r\nBegrüßung & Einleitung Willkommen! 5 min\r\n\r\nUnterjährige Fahrplanprodukte unter Annex VII 10 min\r\n\r\nÜberblick Annex VII\r\n\r\nDigitale BauFplo 10 min\r\n\r\nIhre Fragen und\r\n\r\nBeantwortung Ihrer Fragen 30 min\r\n\r\nHinweise\r\n\r\nAbschluss Nächste Schritte 5 min\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 31.07.2026 2",46,"{\"canonical_url\":null,\"normalized_sha256\":\"eef5a3413f4bd077a678c695bba2facb8ff5c618bd310813e66f0e628dbaa618\",\"page\":2,\"source_id\":\"src_55f12bc0f78e6465ec63\",\"source_sha256\":\"18db5438ce86e06e01d7bc2da721c1ac26dbec8d9c61d8cea98165ac19f27baf\",\"source_version_id\":\"sv_fc73716a3f57a7991ffa7db4\"}","a637b61a5587ed34df1fa59c251af0e267459d39dc82a17d857ed6b125a4eff1"],["chunk_89c1660b5ede0cfe45f323c8","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-31-07-2026-data.md",2,"Seite 3","Hinweise\r\n\r\nfür den heutigen\r\n\r\nTeams Fragen & Antworten\r\n\r\nTermin\r\n\r\nFragen & Kommentare jederzeit während der Präsentation im Bereich „F&A“ in\r\n\r\nTeams schriftlich stellen\r\n\r\nkurz & auf den Punkt hilft uns beim späteren Beantworten\r\n\r\nVoice-Beiträge (Hand heben)\r\n\r\nWir freuen uns\r\n\r\nIn der Q&A-Phase am Ende des Termins\r\n\r\nüber eine aktive\r\n\r\nWir rufen auf; max. ~1 Minute pro Frage, damit viele zu Wort kommen\r\n\r\nTeilnahme. Ihre\r\n\r\nGedanken und\r\n\r\nWann antworten wir?\r\n\r\nFragen sind\r\n\r\nausdrücklich Am Ende des Termins in einer gebündelten Q&A-Runde\r\n\r\nWir sammeln und priorisieren währenddessen im Hintergrund\r\n\r\nwillkommen!\r\n\r\nZiel:\r\n\r\nMöglichst viele Fragen, möglichst klare Antworten – fair & respektvoll für alle.\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 31.07.2026 3",112,"{\"canonical_url\":null,\"normalized_sha256\":\"eef5a3413f4bd077a678c695bba2facb8ff5c618bd310813e66f0e628dbaa618\",\"page\":3,\"source_id\":\"src_55f12bc0f78e6465ec63\",\"source_sha256\":\"18db5438ce86e06e01d7bc2da721c1ac26dbec8d9c61d8cea98165ac19f27baf\",\"source_version_id\":\"sv_fc73716a3f57a7991ffa7db4\"}","e986dbbe97b3091ed7bc2df5eaa4559ce73f9abdbc0487ac511bae56640817f6"],["chunk_98133948ae4bcefdf0ad15da","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-31-07-2026-data.md",3,"Seite 4","Unterjährige Fahrplanprodukte\r\n\r\nunter Annex VII\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 31.07.2026 4",16,"{\"canonical_url\":null,\"normalized_sha256\":\"eef5a3413f4bd077a678c695bba2facb8ff5c618bd310813e66f0e628dbaa618\",\"page\":4,\"source_id\":\"src_55f12bc0f78e6465ec63\",\"source_sha256\":\"18db5438ce86e06e01d7bc2da721c1ac26dbec8d9c61d8cea98165ac19f27baf\",\"source_version_id\":\"sv_fc73716a3f57a7991ffa7db4\"}","17779eafbc9463be3d8156452acafcac142c9661e53f32d7d76fc5c969b6cf2d"],["chunk_ec26595425f441ada5855a25","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-31-07-2026-data.md",4,"Seite 5","DB InfraGO bietet verschiedene Informationsformate rund um\r\n\r\ndie Einführung von Annex VII und TTT im unterjährigen Bau an\r\n\r\nDie unterschiedlichen Termine haben einen jeweils klaren Fokus und ergänzen sich.\r\n\r\nBedienen Sie sich gerne passend aus unserem Angebot:\r\n\r\nEinweisung 4. KP GPE/FPE ujBau Vertiefung\r\n\r\n(KOMBau)\r\n\r\n• Fokus: neue Prozesse im\r\n\r\n• Fokus: Bedienung des Tools unterjährigen Bau\r\n\r\nKOMBau rund um GPE/FPE\r\n\r\n• nächster Termin vsl.\r\n\r\n21.08.2026\r\n\r\nHeutiger Termin\r\n\r\nSprechstunden zu 4. KP TTT-Dialog\r\n\r\nGPE/FPE\r\n\r\n• Fokus: Gesamtblick über alle\r\n\r\n• Fokus: Beantwortung von Fahrplanphasen,\r\n\r\nFragen zu Bedienung Projektmeilensteine\r\n\r\nKOMBau u. neuem Prozess\r\n\r\n• nächster Termin 27.8.2026\r\n\r\n• seit 9.7.2026, wöchentlich 1h\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 31.07.2026 5",111,"{\"canonical_url\":null,\"normalized_sha256\":\"eef5a3413f4bd077a678c695bba2facb8ff5c618bd310813e66f0e628dbaa618\",\"page\":5,\"source_id\":\"src_55f12bc0f78e6465ec63\",\"source_sha256\":\"18db5438ce86e06e01d7bc2da721c1ac26dbec8d9c61d8cea98165ac19f27baf\",\"source_version_id\":\"sv_fc73716a3f57a7991ffa7db4\"}","5fb674d38203ef7b2fdf5ed7b6306101812a61416da89b67598d157a92f68ec5"],["chunk_c5c5a7f11b808049acdf7463","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-31-07-2026-data.md",5,"Seite 6","Fahrplan zum neuen unterjährigen Baufahrplan:\r\n\r\nVersandzeitpunkte der neuen Produkte rücken näher\r\n\r\nNach Feedback\r\n\r\naus dem Markt:\r\n\r\n31.08.2026 19.10.2026 22.11.2026\r\n\r\nVersand 1. GPE Möglicher Zeitrahmen für\r\n\r\nerfolgt erst zur Versand 1. GPE Frist 1. GPE (z-15) Frist 1. FPE (z-8)3 Frist 1. digitale\r\n\r\nFrist Ende August BauFplo (z-3)\r\n\r\nFrist 1. NAÄ (z-8)\r\n\r\nJun. Jul. Aug. Sep. Okt. Nov. Dez.\r\n\r\nAb Versand des FPE und\r\n\r\n06.07.2026 17.08.2026 14.12.2026\r\n\r\nNAÄ wird die BauFplo im\r\n\r\nVNP1 (TTT-konform) ENP2 (TTT-konform) 1. Montag nach dem\r\n\r\nneuen Format versendet\r\n\r\nFahrplanwechsel\r\n\r\n1 Für die Fahrplandokumente für Sonntag nach Fahrplanwechsel (13.12.2026) gelten folgende Fristen:\r\n\r\nGPE: 24.08.2026, FPE (SPV): 12.10.2026, FPE (SGV) 02.11.2026\r\n\r\n2\r\n\r\nDie Stellungnahmefrist von 3 Wochen auf das GPE bleibt bestehen.\r\n\r\n3\r\n\r\nEs handelt sich jeweils um die spätesten Versandzeitpunkte, insb. die erste digitale BauFplo kann auch früher kommen.\r\n\r\n(1) Vorläufiger Netzplanentwurf (2) Endgültiger Netzfahrplan (3) z-8 gilt für den SPV. Für den SGV gilt die Frist z-5.\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 31.07.2026 6",162,"{\"canonical_url\":null,\"normalized_sha256\":\"eef5a3413f4bd077a678c695bba2facb8ff5c618bd310813e66f0e628dbaa618\",\"page\":6,\"source_id\":\"src_55f12bc0f78e6465ec63\",\"source_sha256\":\"18db5438ce86e06e01d7bc2da721c1ac26dbec8d9c61d8cea98165ac19f27baf\",\"source_version_id\":\"sv_fc73716a3f57a7991ffa7db4\"}","4bbad0ca315510cbdc14e7b7139829aad4a2c48449db4f952935dd22fffc3250"],["chunk_749487b6ff9b732b2252446b","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-31-07-2026-data.md",6,"Seite 7","DB InfraGO entwickelt die KOMBau bis zur ersten GPE-\r\n\r\nKonsultation gezielt weiter und stellt neue Funktionen bereit\r\n\r\nBereits vorhandene Funktionalitäten KOMBau: Funktionserweiterungen bis erste GPE-Konsultation am 24.08.26:\r\n\r\n• Ist seit dem 22.06. für den Nutzer verfügbar • GPE (zukünftig auch GPEnS und FPE) kann mit der Vertragstrasse\r\n\r\n(aber noch keine GPE enthalten) aus dem Netzfahrplan auf der Übersichtsseite und im Laufweg\r\n\r\nverglichen werden\r\n\r\n• Die Anforderungen des Annex VII sind erfüllt\r\n\r\n• Es wird eine erste Version der Mehrfachstellungnahme geben:\r\n\r\n• Es wird im TTT-Format kommuniziert\r\n\r\n• GPE für die Stellungnahme kann selektiert werden\r\n\r\n• GPE, GPEnS, FPE werden kommuniziert\r\n\r\n• Mehrfachstellungnahme kann abgegeben werden\r\n\r\n• Es können Stellungnahmen zu GPE abgegeben\r\n\r\nwerden und GPEnS abgelehnt oder angenommen • Verfristete GPE werden täglich gebündelt um 22:30 versandt\r\n\r\nwerden\r\n\r\n• Alle Prozessschritte von GPE bis FPE sind\r\n\r\nnachvollziehbar\r\n\r\n• Es sind Filterfunktionen in der Übersichtsseite\r\n\r\nFür den Umgang mit diesen neuen Funktionen wird vsl.\r\n\r\nenthalten\r\n\r\nam 21.08.26 ein Einweisungstermin angeboten\r\n\r\n• Sortierfunktionen werden in der Übersichtsseite\r\n\r\nDie zugehörige Kundeninformation wird am 06.08.26\r\n\r\nbereitgestellt verschickt\r\n\r\n• Kontaktdaten können automatisiert befüllt werden\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 31.07.2026 7",190,"{\"canonical_url\":null,\"normalized_sha256\":\"eef5a3413f4bd077a678c695bba2facb8ff5c618bd310813e66f0e628dbaa618\",\"page\":7,\"source_id\":\"src_55f12bc0f78e6465ec63\",\"source_sha256\":\"18db5438ce86e06e01d7bc2da721c1ac26dbec8d9c61d8cea98165ac19f27baf\",\"source_version_id\":\"sv_fc73716a3f57a7991ffa7db4\"}","b42df693ef730f7ba9f6a930016e52f232f74cf8c939ed1dcc18ebe2cf4c46e7"],["chunk_8afeefd3b588851baf2f5096","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-31-07-2026-data.md",7,"Seite 8","Digitale BauFplo\r\n\r\nVorschau Hochlauf in 2026\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 31.07.2026 8",17,"{\"canonical_url\":null,\"normalized_sha256\":\"eef5a3413f4bd077a678c695bba2facb8ff5c618bd310813e66f0e628dbaa618\",\"page\":8,\"source_id\":\"src_55f12bc0f78e6465ec63\",\"source_sha256\":\"18db5438ce86e06e01d7bc2da721c1ac26dbec8d9c61d8cea98165ac19f27baf\",\"source_version_id\":\"sv_fc73716a3f57a7991ffa7db4\"}","bd3408c468d6d5a1cfc3b6082164883747cef883cf14fe8d380fc773ffcc49cf"],["chunk_03e7536a802e5c0b68b829d6","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-31-07-2026-data.md",8,"Seite 9","Anforderungen von TTT / Annex VII für die neuen\r\n\r\nunterjährige Fahrplanprodukte im Regelprozess\r\n\r\nMigrationszeitraum Fplj 2027: Übersicht Fahrplanprodukte und zugehörige Prozesse\r\n\r\nBKE1 GPE2 GPEnS3 FPE4 NAÄ5 BauFplo6\r\n\r\nInfraGO\r\n\r\nz-29 z-24 z-15 z-87 z-8 bis z-3\r\n\r\nWebportal\r\n\r\nWebanwendung KOMBau PDF per Mail\r\n\r\nSysteme pathOS\r\n\r\nCommon Interface pathOS (Schnittstelle zur Trassenmeldung) API (Schnittstelle)\r\n\r\n3 Wochen Stellungnahme, 1 Woche Annahme/ Kostenfreie Stornierung\r\n\r\nEVU Annahme/ Ablehnung innerhalb 3 AT8\r\n\r\nAblehnung möglich\r\n\r\nz-21 z-14 z-8\r\n\r\n(1) Baubedingte Kapazitätseinschränkung (2) Grobplanungsergebnis (3) Grobplanungsergebnis nach Stellungnahme (4) Feinplanungsergebnis (5) Netzausgelöste Änderung\r\n\r\n(6) Baufahrplananordnung (7) Frist FPE im SGV z-5 (8) Arbeitstage\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 31.07.2026 9",105,"{\"canonical_url\":null,\"normalized_sha256\":\"eef5a3413f4bd077a678c695bba2facb8ff5c618bd310813e66f0e628dbaa618\",\"page\":9,\"source_id\":\"src_55f12bc0f78e6465ec63\",\"source_sha256\":\"18db5438ce86e06e01d7bc2da721c1ac26dbec8d9c61d8cea98165ac19f27baf\",\"source_version_id\":\"sv_fc73716a3f57a7991ffa7db4\"}","0d09ae8b9f35f7b6c8e4491dca18943d502a062d2186eff49b64a5ca71ba7c77"],["chunk_25851f7dd39c4f6415401829","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-31-07-2026-data.md",9,"Seite 10","Mit der Einführung von TTT / Annex VII gibt es\r\n\r\nÄnderungen in der Darstellung der BauFplo und an der API\r\n\r\nÄnderungen an der BauFplo API Ausblick: Änderungen an der BauFplo mit TTT / Annex VII\r\n\r\nChangelog BauFplo API EVU\r\n\r\nThema Darstellung unter TTT\r\n\r\n• Änderungsübersicht der\r\n\r\nSchnittstellenbeschreibung der digitalen Zugtrassen mit mehreren Ja\r\n\r\nBauFplo wird fortlaufend gepflegt Abschnitten\r\n\r\n• Dient zur Unterstützung bei Bewertung Zeitliche Inkonsistenz Ja\r\n\r\nmöglicher Auswirkungen auf Ihre\r\n\r\nÜbergänge zu Ja\r\n\r\nSysteme\r\n\r\nFremdnetzanteilen\r\n\r\nAktualisierte Beispieldateien PathID Nein\r\n\r\nBauvorgangsnummer Entfällt\r\n\r\n• Zeigen mögliche Anwendungsfälle in\r\n\r\njeweils drei verschiedenen Formaten Art der Baumaßnahme Entfällt\r\n\r\n(pdf, json, xml)\r\n\r\nOrt der Baumaßnahme Entfällt\r\n\r\nAlle aktuellen Änderungen an der API und Beispiele Auch zukünftig kann es zu Änderungen an der\r\n\r\nsind auf Homepage zur digitalen BauFplo zu finden. BauFplo kommen, über die wir informieren.\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 31.07.2026 10",143,"{\"canonical_url\":null,\"normalized_sha256\":\"eef5a3413f4bd077a678c695bba2facb8ff5c618bd310813e66f0e628dbaa618\",\"page\":10,\"source_id\":\"src_55f12bc0f78e6465ec63\",\"source_sha256\":\"18db5438ce86e06e01d7bc2da721c1ac26dbec8d9c61d8cea98165ac19f27baf\",\"source_version_id\":\"sv_fc73716a3f57a7991ffa7db4\"}","37d24c4c348e780d328f680e1151f13b885c96f20d94b24981d0f74b3eaebb06"],["chunk_ffddabfdc271e4c62d307ed5","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-31-07-2026-data.md",10,"Seite 11","Mit der Betriebserprobung bereiten wir sukzessive die\r\n\r\nEinführung der digitalen BauFplo in 2026 vor\r\n\r\nDie Betriebserprobung in Zahlen\r\n\r\nStand 20.07.2026\r\n\r\n42\r\n\r\n>118\r\n\r\n>910\r\n\r\nEVU mit Kontaktaufnahme\r\n\r\nbeantwortete Fragen &\r\n\r\nveröffentlichte BauFplon\r\n\r\nVeröffentlichung im FAQ2\r\n\r\n28\r\n\r\naktiv beteiligt\r\n\r\n12\r\n\r\nkooperationsinteressiert1\r\n\r\n7 von 7 21\r\n\r\n6\r\n\r\nRegionen sind Teil der Erprobung verprobte Anwendungsfälle\r\n\r\nAnpassungsbedarfe EVU-seitig\r\n\r\nidentifiziert\r\n\r\n(1) EVU in laufender Entscheidungsfindung oder mit noch nicht verprobbaren Anwendungsfällen\r\n\r\n(2) Reduzierte Zahl im Vgl. zu Vormonat durch Aufteilung des FAQ in Annex VII und Digitale BauFplo. Restliche Fragen in Annex VII FAQ aufgegangen\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 31.07.2026 11",100,"{\"canonical_url\":null,\"normalized_sha256\":\"eef5a3413f4bd077a678c695bba2facb8ff5c618bd310813e66f0e628dbaa618\",\"page\":11,\"source_id\":\"src_55f12bc0f78e6465ec63\",\"source_sha256\":\"18db5438ce86e06e01d7bc2da721c1ac26dbec8d9c61d8cea98165ac19f27baf\",\"source_version_id\":\"sv_fc73716a3f57a7991ffa7db4\"}","9bd57cf3ec7fd4c4519eea782808cda2387877bd2269979e7b605151adfb5c69"],["chunk_a3165de196006a01cc1221d8","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-31-07-2026-data.md",11,"Seite 12","21 bereits erprobte Anwendungsfälle decken ca. 95% des\r\n\r\nzukünftigen Aufkommens an digitalen BauFplo ab\r\n\r\n21 Anwendungsfälle bereits erprobt In allen 7 Regionen bereits digitale BauFplo veröffentlicht:\r\n\r\n• Umleitung • Teilausfall hinten - auf Laufweg\r\n\r\n• Umleitung mit Ausfall von • Mittiger Teilausfall (SEV) mit Kumulierte Anzahl BauFplo\r\n\r\nBetriebsstellen baubedingter Neuleistung\r\n\r\n1.000\r\n\r\n• Umleitung mit zus. Betriebsstellen • Einfahrt in Stumpfgleis auf\r\n\r\n800\r\n\r\nLaufweg\r\n\r\n• Umleitung mit Ausfall von\r\n\r\nBetriebsstellen und mit • Zugcharakteristika Anpassung 600 Region Südwest\r\n\r\nzusätzlichen Betriebsstellen Region Ost\r\n\r\n• Halt für Personalwechsel\r\n\r\n400\r\n\r\nRegion Süd\r\n\r\n• Verkehrstagswechsel\r\n\r\n• Zug fährt mit Verfahren ESF Region West\r\n\r\n200\r\n\r\n• Zielendpunkt im Ausland Region Nord\r\n\r\n• Zugfahrt mit Region Südost Region Mitte\r\n\r\n0\r\n\r\n• Hinweis auf den Ersatzfahrplan- Notbremsüberbrückung\r\n\r\nN D J F M A M J J A S O N D J F M A M J J\r\n\r\nheftverweis • Verspätung . v o . z e . n a . b e z r ä . r p i a i n u il u . g u . p e . t k . v o . z e . n a . b e z r ä . r p i a i n u il u\r\n\r\n• Vorplan\r\n\r\n• KV-Profil\r\n\r\n2024 2025 2026\r\n\r\n• Totalausfall\r\n\r\n• Rangierfahrt\r\n\r\n• Einfahrt in Frühhaltanzeiger auf\r\n\r\n• Zeitsprung Legende\r\n\r\nLaufweg\r\n\r\nErste digitale BauFplo zu Trasse in Region x veröffentlicht\r\n\r\nWeitere, auch komplexere Anwendungsfälle können mit uns in der\r\n\r\nNeues EVU nimmt an Betriebserprobung teil\r\n\r\nBetriebserprobung/Hochlauf getestet werden\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 31.07.2026 12",260,"{\"canonical_url\":null,\"normalized_sha256\":\"eef5a3413f4bd077a678c695bba2facb8ff5c618bd310813e66f0e628dbaa618\",\"page\":12,\"source_id\":\"src_55f12bc0f78e6465ec63\",\"source_sha256\":\"18db5438ce86e06e01d7bc2da721c1ac26dbec8d9c61d8cea98165ac19f27baf\",\"source_version_id\":\"sv_fc73716a3f57a7991ffa7db4\"}","c77c6b1ee6d3d3c4322680ba2e14582f7adeb0a0c35872b944fd9534216f8de5"]]');
