INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_1e64b4d3804c890d969d8ada","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-31-07-2026-data.md",12,"Seite 13","Mit dem Readiness-Check für die digitale BauFplo\r\n\r\nkönnen Sie selbständig ihre Prozesse prüfen\r\n\r\nDer BauFplo-Readiness-Check...\r\n\r\n... ist ein kompakter Selbsteinschätzungs-Check zur Prüfung,\r\n\r\nwie gut Sie auf die digitale BauFplo vorbereitet sind\r\n\r\n... bringt Transparenz über den eigenen Reifegrad, von\r\n\r\nEmpfang und Ablage bis zur operativen Nutzung\r\n\r\n... hilft, Prozesslücken zu schließen und sicherzustellen, dass\r\n\r\nBauFplo zuverlässig verarbeitet werden können\r\n\r\n... ist bewusst pragmatisch gehalten und in wenigen Minuten\r\n\r\ndurchführbar\r\n\r\n... ist als Download auf unserer Webseite verfügbar\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 31.07.2026 13",88,"{\"canonical_url\":null,\"normalized_sha256\":\"eef5a3413f4bd077a678c695bba2facb8ff5c618bd310813e66f0e628dbaa618\",\"page\":13,\"source_id\":\"src_55f12bc0f78e6465ec63\",\"source_sha256\":\"18db5438ce86e06e01d7bc2da721c1ac26dbec8d9c61d8cea98165ac19f27baf\",\"source_version_id\":\"sv_fc73716a3f57a7991ffa7db4\"}","8645c64a9f7597bd51373e7549019a1f7bfce5146e3517bf80e3007ed539f4ad"],["chunk_d7cb53957eb66c744f2c3239","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-31-07-2026-data.md",13,"Seite 14","So bleiben Sie mit uns in Kontakt\r\n\r\nAnnex VII KOMBau Digitale BauFplo TAF/TAP TSI\r\n\r\nHier geht‘s zur Website Hier geht‘s zur Website Hier geht‘s zur Website Hier geht‘s zur Website\r\n\r\n• Informationen zum neuen • Informationen zur • Neuerungen auf einen Blick • Tools zur\r\n\r\nProzess Baukommunikation Webanwendung, inkl. Trassenanmeldung (z. B.\r\n\r\n• Beschreibung Testzugang\r\n\r\nDirektlink pathOS)\r\n\r\n• Zusammenhang mit auf BauFplo API\r\n\r\nKOMBau • Bedienungsanleitung • Schnittstellen &\r\n\r\n• Beispieldokumente in xml-\r\n\r\nMeldungsservices\r\n\r\n• FAQ • FAQ und json-Format\r\n\r\n• Informationsangebote\r\n\r\n• FAQ\r\n\r\n(FAQ, Events,\r\n\r\n• Readiness Check\r\n\r\nAnsprechpartner)\r\n\r\nSie erhalten die gezeigte Unterlage im Anschluss an diese Veranstaltung.\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 31.07.2026 14",111,"{\"canonical_url\":null,\"normalized_sha256\":\"eef5a3413f4bd077a678c695bba2facb8ff5c618bd310813e66f0e628dbaa618\",\"page\":14,\"source_id\":\"src_55f12bc0f78e6465ec63\",\"source_sha256\":\"18db5438ce86e06e01d7bc2da721c1ac26dbec8d9c61d8cea98165ac19f27baf\",\"source_version_id\":\"sv_fc73716a3f57a7991ffa7db4\"}","968b9c4e7a72997e5b2445528c5810c05cc5b742b332fc8a1cc6f0487d30294c"],["chunk_bb87b3b805a85899202b9a0a","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-31-07-2026-data.md",14,"Seite 15","Fragen und Hinweise\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 31.07.2026 15",14,"{\"canonical_url\":null,\"normalized_sha256\":\"eef5a3413f4bd077a678c695bba2facb8ff5c618bd310813e66f0e628dbaa618\",\"page\":15,\"source_id\":\"src_55f12bc0f78e6465ec63\",\"source_sha256\":\"18db5438ce86e06e01d7bc2da721c1ac26dbec8d9c61d8cea98165ac19f27baf\",\"source_version_id\":\"sv_fc73716a3f57a7991ffa7db4\"}","6b52de21719d5981b8b77c3ba614f450eaea0222244b6579628db07dd11fe9ee"],["chunk_5b3e355a82160397b07fa87f","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-31-07-2026-data.md",15,"Seite 16","Häufig gestellte Fragen – FAQ 1\r\n\r\nThema: Annex VII\r\n\r\nF\r\n\r\nWird eine Leertrasse den regulären GPE-Prozess durchlaufen oder erfolgt hierfür\r\n\r\neine NAÄ zur Leertrasse?\r\n\r\nA\r\n\r\nAuch Leerzugtrassen können ein GPE erhalten, sofern sie vor Beginn\r\n\r\nder Bearbeitung der Maßnahme bekannt sind.\r\n\r\nIst die Leerzugtrasse indirekt baubetroffen, wird in der\r\n\r\nStellungnahme eine Rückmeldung des EVUs benötigt. Das EVU erhält\r\n\r\nim Anschluss für die indirekt betroffene Leerzugtrasse ein FPE.\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 31.07.2026 16",78,"{\"canonical_url\":null,\"normalized_sha256\":\"eef5a3413f4bd077a678c695bba2facb8ff5c618bd310813e66f0e628dbaa618\",\"page\":16,\"source_id\":\"src_55f12bc0f78e6465ec63\",\"source_sha256\":\"18db5438ce86e06e01d7bc2da721c1ac26dbec8d9c61d8cea98165ac19f27baf\",\"source_version_id\":\"sv_fc73716a3f57a7991ffa7db4\"}","819b16232aff860f049053aebb41bafbf44e275fa795f2140f9d9a74ade94cfe"],["chunk_41063f0bd49c9655a29829bc","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-31-07-2026-data.md",16,"Seite 17","Häufig gestellte Fragen – FAQ 2\r\n\r\nThema: Annex VII\r\n\r\nF\r\n\r\nWie werden kurzfristige Änderungen nach z-24 kommuniziert?\r\n\r\nKönnen EVU auf kurzfristige Kapazitätseinschränkungen nach GPE\r\n\r\nnoch Rückmeldung abgeben?\r\n\r\nA\r\n\r\nINB 2027 Ril. 402.0305 Abschnitt 9 Absatz (3)\r\n\r\nKönnen bestehende Fristen nicht eingehalten werden – etwa, weil\r\n\r\ndie BKE auf einer kurzfristig erforderlichen Baumaßnahme beruht -\r\n\r\nso konsultiert die DB InfraGO AG die ZB und EIU umgehend (sofern\r\n\r\nkeine Gefahr in Verzug). Diese haben einen Arbeitstag Zeit, um eine\r\n\r\nStellungnahme abzugeben.\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 31.07.2026 17",90,"{\"canonical_url\":null,\"normalized_sha256\":\"eef5a3413f4bd077a678c695bba2facb8ff5c618bd310813e66f0e628dbaa618\",\"page\":17,\"source_id\":\"src_55f12bc0f78e6465ec63\",\"source_sha256\":\"18db5438ce86e06e01d7bc2da721c1ac26dbec8d9c61d8cea98165ac19f27baf\",\"source_version_id\":\"sv_fc73716a3f57a7991ffa7db4\"}","2e5a6da9472451c9d98114c0df455acadbf75250f87db9f55b43e561d783a6a2"],["chunk_92698ec85452c507f6d10360","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-31-07-2026-data.md",17,"Seite 18","Häufig gestellte Fragen – FAQ 3\r\n\r\nThema: KOMBau\r\n\r\nF\r\n\r\nWie kann sichergestellt werden, dass Vorgaben vom Aufgabenträger\r\n\r\n(z.B. Anschlussverkehre, Schülerverkehre) berücksichtigt werden,\r\n\r\nsodass diese an bestimmten Betriebsstellen erreicht werden können.\r\n\r\nA\r\n\r\nDie EVU haben die Möglichkeit, an den relevanten Bst.\r\n\r\n(Betriebsstellen), an denen Anschlussverkehre vorhanden sind, eine\r\n\r\nfrüheste oder späteste Zeit anzugeben, inklusive eines Kommentars\r\n\r\nauf der Betriebsstellenebene, warum die Einhaltung wichtig ist. (z.B.\r\n\r\nAnschluss der Bus-Linie X muss erreicht werden)\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 31.07.2026 18",82,"{\"canonical_url\":null,\"normalized_sha256\":\"eef5a3413f4bd077a678c695bba2facb8ff5c618bd310813e66f0e628dbaa618\",\"page\":18,\"source_id\":\"src_55f12bc0f78e6465ec63\",\"source_sha256\":\"18db5438ce86e06e01d7bc2da721c1ac26dbec8d9c61d8cea98165ac19f27baf\",\"source_version_id\":\"sv_fc73716a3f57a7991ffa7db4\"}","1e5e2256234c99e29354f07c49d6158cd2ba0b1e4bab2262a50acba29fa81893"],["chunk_5e1f123589689d5df7576a60","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-31-07-2026-data.md",18,"Seite 19","Häufig gestellte Fragen – FAQ 4\r\n\r\nThema: GPE\r\n\r\nF\r\n\r\nAufgrund der unterschiedlichen Fristen (z-15 vs. z-24) erhalten wir ab September\r\n\r\n10 Wochen lang jede Woche für 2 Planungswochen GPEs, ist das korrekt?\r\n\r\nA\r\n\r\nJa das ist korrekt, es werden für 2 Planungswochen GPEs versendet.\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 31.07.2026 19",55,"{\"canonical_url\":null,\"normalized_sha256\":\"eef5a3413f4bd077a678c695bba2facb8ff5c618bd310813e66f0e628dbaa618\",\"page\":19,\"source_id\":\"src_55f12bc0f78e6465ec63\",\"source_sha256\":\"18db5438ce86e06e01d7bc2da721c1ac26dbec8d9c61d8cea98165ac19f27baf\",\"source_version_id\":\"sv_fc73716a3f57a7991ffa7db4\"}","8ffbfe9400ea8015c4d66fecb0b207c097da1895443f4d28bd3679023aff5225"],["chunk_c83fe24ded06393ed6844dba","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-31-07-2026-data.md",19,"Seite 20","Häufig gestellte Fragen – FAQ 5\r\n\r\nThema: GPE\r\n\r\nF\r\n\r\nWenn zwei Züge (z.B. SGV) an einer bestimmten Betriebsstelle ihren\r\n\r\nWagenaustausch machen und eine gemeinsame Haltezeit von 30 Min.\r\n\r\nbenötigen, jetzt bekommt Zug 1 ein GPE mit einer BKE von 60 Min.\r\n\r\nspäter in dieser Betriebsstelle an.\r\n\r\nBekommt der Zug 2 auch ein GPE ab der gemeinsamen Betriebsstelle\r\n\r\nmit +60 Min. ?\r\n\r\nA\r\n\r\nFür den nicht baubetroffenen Zug erfolgt keine Bauausregelung. Hier\r\n\r\nist eine Änderungsbestellung durch den Kunden notwendig.\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 31.07.2026 20",89,"{\"canonical_url\":null,\"normalized_sha256\":\"eef5a3413f4bd077a678c695bba2facb8ff5c618bd310813e66f0e628dbaa618\",\"page\":20,\"source_id\":\"src_55f12bc0f78e6465ec63\",\"source_sha256\":\"18db5438ce86e06e01d7bc2da721c1ac26dbec8d9c61d8cea98165ac19f27baf\",\"source_version_id\":\"sv_fc73716a3f57a7991ffa7db4\"}","c01309224f57dd91a840e7dc6bc2f8cd3b8c976d830705c54879449d0d147ee0"],["chunk_3ecc4d68ba1d3e30b0482381","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-31-07-2026-data.md",20,"Seite 21","Häufig gestellte Fragen – FAQ 6\r\n\r\nThema: FPE\r\n\r\nF\r\n\r\nEs kommt die Information, dass die Baustelle ausfällt, nach der\r\n\r\nStellungnahme aufs GPE und vor dem FPE. Wie gehen wir damit um?\r\n\r\nBekommen wir eine Information, dass alle Regelungen zurückgezogen\r\n\r\nwerden?\r\n\r\nA\r\n\r\nSollte eine Baumaßnahme vor dem FPE-Versand abgesagt werden\r\n\r\nund ist die Trasse dadurch nicht mehr baubetroffen, wird durch uns\r\n\r\neine Nachricht gesendet, dass der Prozess abgebrochen wurde. Die\r\n\r\nVertragstrasse gilt unverändert, d.h. ohne Baubetroffenheit, fort. Wir\r\n\r\nschicken das letzte Fahrplanprodukt (GPE oder GPEnS) erneut, inkl.\r\n\r\nwithdrawal-message.\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 31.07.2026 21",98,"{\"canonical_url\":null,\"normalized_sha256\":\"eef5a3413f4bd077a678c695bba2facb8ff5c618bd310813e66f0e628dbaa618\",\"page\":21,\"source_id\":\"src_55f12bc0f78e6465ec63\",\"source_sha256\":\"18db5438ce86e06e01d7bc2da721c1ac26dbec8d9c61d8cea98165ac19f27baf\",\"source_version_id\":\"sv_fc73716a3f57a7991ffa7db4\"}","93717e1b2c1e4a22020bf4fb1ee3c4264bc0297776b644f96480183cd4f49112"],["chunk_bb6f2f53ce2ada95e6ca194f","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-31-07-2026-data.md",21,"Seite 22","Häufig gestellte Fragen – FAQ 7\r\n\r\nThema: Baubedingte Zusatzleistungen\r\n\r\nF\r\n\r\nSofern in der 4 KP. bis z-5 noch baubedingte\r\n\r\nLeertrassen/Zusatzleistungen bestellt werden können, bis zu\r\n\r\nwelchem Zeitpunkt muss diese Leertrasse dem EVU spätestens zur\r\n\r\nVerfügung gestellt werden?\r\n\r\nA\r\n\r\nDas muss laut den INB (2026) 4.2.2.4 Fristen für die Bearbeitung\r\n\r\nvon Trassenanmeldungen innerhalb von 5 Arbeitstagen erfolgen.\r\n\r\nInfrastrukturnutzungsbedingungen der DB InfraGO AG (INB) 2026\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 31.07.2026 22",74,"{\"canonical_url\":null,\"normalized_sha256\":\"eef5a3413f4bd077a678c695bba2facb8ff5c618bd310813e66f0e628dbaa618\",\"page\":22,\"source_id\":\"src_55f12bc0f78e6465ec63\",\"source_sha256\":\"18db5438ce86e06e01d7bc2da721c1ac26dbec8d9c61d8cea98165ac19f27baf\",\"source_version_id\":\"sv_fc73716a3f57a7991ffa7db4\"}","e9f81d1b2ea3354455b305205f123a4adc403de6443a337659e2b0d0152a068f"],["chunk_0924605839b78052a3e162d5","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-31-07-2026-data.md",22,"Seite 23","Häufig gestellte Fragen – FAQ 8\r\n\r\nThema: Mittiger Teilausfall\r\n\r\nF\r\n\r\nWelche Fahrplanprodukte erhalten wir bei einem mittigen Teilausfall\r\n\r\nmit SEV und wie ist das in KOMBau einzugeben?\r\n\r\nA\r\n\r\nIm Prozessschritt GPE erhalten Kunden im Fall eines mittigen\r\n\r\nTeilausfalls ein GPE, in dem die ausfallenden Bst. markiert sind. Bei\r\n\r\nBedarf können die Kunden im Freitextfeld auf Nachrichtenebene\r\n\r\nangeben, welcher Zugteil umgenummert werden soll.\r\n\r\nEisenbahnverkehrsunternehmen mit Bauzugnummernkontingent geben\r\n\r\nzusätzlich die zu verwendende Zugnummer an.\r\n\r\nIm weiteren Verlauf wird die Trasse in zwei aufgeteilt und zwei Folgefahrplanprodukte gesendet.\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 31.07.2026 23",96,"{\"canonical_url\":null,\"normalized_sha256\":\"eef5a3413f4bd077a678c695bba2facb8ff5c618bd310813e66f0e628dbaa618\",\"page\":23,\"source_id\":\"src_55f12bc0f78e6465ec63\",\"source_sha256\":\"18db5438ce86e06e01d7bc2da721c1ac26dbec8d9c61d8cea98165ac19f27baf\",\"source_version_id\":\"sv_fc73716a3f57a7991ffa7db4\"}","5aebb6b87b4532f1d5ceed0f715d29fbdc5852f432865dcc56c7295c4118307e"],["chunk_cca255494b4fe1715f2de6c6","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-31-07-2026-data.md",23,"Seite 24","Häufig gestellte Fragen – FAQ 9\r\n\r\nThema: Mittiger Teilausfall\r\n\r\nF\r\n\r\nWie ist der Umgang in der KOMBau mit einem Nachtsprung bei\r\n\r\nmittigem Teilausfall?\r\n\r\nDie komplette Bautrasse wird durch die DB InfraGO in Form einer\r\n\r\nA\r\n\r\nnetzausgelösten Stornierung, kurz NAS storniert. Danach ist die\r\n\r\nBestellung beider Zugteile mit jeweils neuer Zugnummer über den\r\n\r\nGelegenheitsverkehr notwendig. Hierfür gewährleistet die DB\r\n\r\nInfraGO, dass die bisherige Trassenlage für einen Zeitraum von\r\n\r\nsieben Arbeitstagen vorgehalten wird. Erfolgt keine Neubestellung\r\n\r\ndieser Trasse innerhalb von sieben Arbeitstagen, wird die Trasse als\r\n\r\nvollständig ausgefallen im Rahmen der weiteren Bearbeitung\r\n\r\nbetrachtet.\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 31.07.2026 24",103,"{\"canonical_url\":null,\"normalized_sha256\":\"eef5a3413f4bd077a678c695bba2facb8ff5c618bd310813e66f0e628dbaa618\",\"page\":24,\"source_id\":\"src_55f12bc0f78e6465ec63\",\"source_sha256\":\"18db5438ce86e06e01d7bc2da721c1ac26dbec8d9c61d8cea98165ac19f27baf\",\"source_version_id\":\"sv_fc73716a3f57a7991ffa7db4\"}","6ea76f30a0307792ec3cdae111847f5de3d8283804e70b71f6ff13f26b841f59"],["chunk_174fe4f7dcd1266fe3a1ed28","wiki/sources/informationsveranstaltung-vertiefung-ujbau-vom-31-07-2026-data.md",24,"Seite 25","Zeit für Ihre Fragen\r\n\r\n30 Min.\r\n\r\nBitte stellen Sie ihre Fragen über die\r\n\r\nF&A-Funktion in Teams und voten Sie\r\n\r\ninteressante Fragen nach oben\r\n\r\nDB InfraGO AG | EVU-Informationsveranstaltung | Vertiefung uJBau | 31.07.2026 25",34,"{\"canonical_url\":null,\"normalized_sha256\":\"eef5a3413f4bd077a678c695bba2facb8ff5c618bd310813e66f0e628dbaa618\",\"page\":25,\"source_id\":\"src_55f12bc0f78e6465ec63\",\"source_sha256\":\"18db5438ce86e06e01d7bc2da721c1ac26dbec8d9c61d8cea98165ac19f27baf\",\"source_version_id\":\"sv_fc73716a3f57a7991ffa7db4\"}","930422876ab293a242f793cc0dbaaca57dfab5af78ab8e1e4a3082a3df573d55"],["chunk_33278e30c259031be8d689ef","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",0,"Seite 1","15.07.2026 – virtuell\r\n\r\nVersand im Nachgang\r\n\r\nDB InfraGO AG | TTT-Vertiefungstermin Umgang mit großen Verspätungen („20h-Züge“) | 15.07.2026 1",19,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":1,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","3bd414f387d30f3f7bc759d4ffe5fac4c02518589b176887df30be9e101f1e3c"],["chunk_9ca58d0807ea7c1770281934","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",1,"Seite 2","1. Begrüßung\r\n\r\n1. Begrüßung\r\n\r\n2. Neuer Prozess zur Anmeldung von 20h-Zügen\r\n\r\n2. Neuer Prozess zur Anmeldung von 20h-Zügen\r\n\r\n3. Änderungen im Anmeldeformular\r\n\r\n3. Änderungen im Anmeldeformular\r\n\r\n4. Stornierung des Orginalzuges\r\n\r\n4. Stornierung des Orginalzuges\r\n\r\n5. Neubestellung des 20h-Zuges\r\n\r\n5. Neubestellung des 20h-Zuges\r\n\r\n6. Zeit für Ihre Fragen\r\n\r\n6. Zeit für Ihre Fragen\r\n\r\nDB InfraGO AG | TTT-Vertiefungstermin Umgang mit großen Verspätungen („20h-Züge“) | 15.07.2026 2",65,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":2,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","b31840c245309bf6c364715da8a75f1c727f2b42f0e87f39c58802793bc9f166"],["chunk_11dc014a49e2e9c6ff4e9726","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",2,"Seite 3","So können Sie eine Frage platzieren:\r\n\r\nBitte wählen Sie in MS Teams in der Menüleiste\r\n\r\ndas Icon „Chat“ aus und schreiben Ihre Frage\r\n\r\nin das sich öffnende Fenster.\r\n\r\nDB InfraGO AG | TTT-Vertiefungstermin Umgang mit großen Verspätungen („20h-Züge“) | 15.07.2026 3",41,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":3,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","63f05877a2516eebb312442f7a8ff09bf759e26fb916602be8f7bc7008ba3d93"],["chunk_1b063cd3cc2d82130c3950ef","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",3,"Seite 4","DB InfraGO AG | TTT-Vertiefungstermin Umgang mit großen Verspätungen („20h-Züge“) | 15.07.2026 4",13,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":4,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","70307877b52e89b153c6f937e078fe50229deff42a19413b9acc5a4d8b470571"],["chunk_d419e1e5cd3769d1430e4417","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",4,"Seite 5","(1) Anmeldung (4) Storno (6) Bestellung 20h-Zug\r\n\r\nEVU 20h-Zug Originalzug Auswahl 20h-Antrag-ID\r\n\r\nim Nachlassfeld\r\n\r\n20h-Zug-Tool pathOS pathOS\r\n\r\n(2) Prüfung des (3) Vergabe 20h- (5) Storno (7) OTN Vergabe* (8) Zug (9) Prüfung d. (10) Abrechnung*\r\n\r\nDB InfraGO Antrags Antrag-ID* bearbeiten konstruieren Verspätungsangaben\r\n\r\n20h-Zug-Tool 20h-Zug-Tool\r\n\r\n20h-Zug-Tool\r\n\r\nLegende\r\n\r\nProzessschritte Anwendung/Tool * Vollautomatisierte Prozesse\r\n\r\nDB InfraGO AG | Informationsveranstaltung Vertiefung 20h-Zug | 15.07.2026 5",61,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":5,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","3b79de5bea0fb19c548f1bc176f17423b1767e4f9f4506ead0e797db94398198"],["chunk_e502ebe88da113e206e6a403","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",5,"Seite 6","(1) Das EVU meldet den Bedarf einer neuen Zugtrasse aufgrund einer Verspätung von mehr als 20 Stunden gemäß INB\r\n\r\n6.3.3.4.2 im Anmeldeformular unter https://20hzug.dbinfrago.com/ an.\r\n\r\n(2) Die DB InfraGO prüft die sachliche Richtigkeit der Angaben im Formular hinsichtlich Verspätungsort und -ursache.\r\n\r\na. Wenn die Angaben unplausibel sind, wird der Antrag abgelehnt. Das EVU erhält eine E-Mail mit\r\n\r\nentsprechender Begründung. Der Prozess endet an dieser Stelle.\r\n\r\nb. Wenn die Angaben plausibel sind, wird der Antrag bestätigt und (3) eine 20h-Antrag-ID vom System erzeugt.\r\n\r\nDas EVU erhält eine E-Mail mit der 20h-Antrag-ID.\r\n\r\n(4) Das EVU storniert den Originalzug.\r\n\r\nSofern das EVU den Identifier des Originalzugs wieder benutzen möchte, muss auf die Bearbeitung\r\n\r\ndes Stornos gewartet werden. Andernfalls kann (4) und (6) direkt nacheinander erfolgen.\r\n\r\n(5) Die DB InfraGO bearbeitet die Stornierung.\r\n\r\n(6) Das EVU bestellt den 20h-Zug unter Angabe der 20h-Antrag-ID aus (3) im Feld Nachlassnummer.\r\n\r\n(7) Die Neubestellung erhält automatisiert eine Zugnummer (das Konstrukt der 98er Zugnummer entfällt).\r\n\r\n(8) Die DB InfraGO konstruiert den 20h-Zug.\r\n\r\n(9) Die DB InfraGO prüft die Angaben zur Verspätungsursache und korrigiert diese ggf. Das EVU erhält über jede\r\n\r\nÄnderung eine Information per E-Mail.\r\n\r\n(10)Original- und 20h-Zug werden unter Berücksichtigung der Verspätungsursache abgerechnet.\r\n\r\nDB InfraGO AG | TTT-Vertiefungstermin Umgang mit großen Verspätungen („20h-Züge“) | 15.07.2026 6",209,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":6,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","39dc4f59f9bc557f015961ae4de7f76f32b3459bb2232f37b6ee570f81f2c54f"],["chunk_75c9e67c4cd98c59a40be9f5","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",6,"Seite 7","− Durch die eigenständige Stornierung des Originalzuges durch die EVU wird hierfür zunächst immer ein\r\n\r\nStornierungsentgelt berechnet.\r\n\r\n− Nach der finalen Prüfung der Verspätungsursache durch die Netzleitzentrale der DB InfraGO wird das\r\n\r\nStornierungsentgelt zurückgebucht, sofern das EVU nicht an der Verspätung schuld ist.\r\n\r\n− Sollte sich die Prüfung der Verspätungsursache über den Monatswechsel strecken, kann es dazu kommen, dass die\r\n\r\nAusbuchung des Stornierungsentgeltes erst in der darauffolgenden Monatsabrechnung erfolgt.\r\n\r\nDB InfraGO AG | TTT-Vertiefungstermin Umgang mit großen Verspätungen („20h-Züge“) | 15.07.2026 7",82,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":7,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","f5c91f21c92fb3008219df23f01871bcb5a1104e6bb804cc85617e1bc7ed20f1"]]');
