INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_79019bdc86ef8d2eaec54f3d","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",7,"Seite 8","Wie wird die 20h-Antrag-ID vergeben?\r\n\r\n>> Automatisiert durch das System, sofern die Prüfung des Antrags als plausibel bestätigt wurde.\r\n\r\nWelches Format hat die 20h-Antrag-ID?\r\n\r\n>> [Z][Jahr der Anmeldung][fünfstellige Nummer]\r\n\r\nBeispiel: Z202612345\r\n\r\nWird es INB-Änderungen geben?\r\n\r\n>> Nein, die INB selbst werden nicht geändert.\r\n\r\nFindet eine Anpassung der SST-Beschreibung statt?\r\n\r\n>> SST-Doku wurde ergänzt (Aufnahme Ausprägung 20h-Zug bei VerkehrsArtKundeZusatz). Die Veröffentlichung Anlage 1\r\n\r\nam 11.6. als Version 4.6.3.1 wurde als KI am 11.6. sowie im TTT-Dialog am 24.6. kommuniziert.\r\n\r\nDB InfraGO AG | TTT-Vertiefungstermin Umgang mit großen Verspätungen („20h-Züge“) | 15.07.2026 8",91,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":8,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","f0a976457f45733c937205d5524f5682ecc78b46ba16c72b3fbf5f38a06f1356"],["chunk_46e6e12885a62dd113545d95","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",8,"Seite 9","DB InfraGO AG | TTT-Vertiefungstermin Umgang mit großen Verspätungen („20h-Züge“) | 15.07.2026 9",13,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":9,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","1a1427be8f5b3c1fc5e4166d23d83eff0f9148fb4121195daba492d643929bc4"],["chunk_3d7b1e07023c7b88d7902f56","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",9,"Seite 10","LINK LOGIN\r\n\r\n‒ Heutiger Direktlink ‒ Login-Daten des Infraportals\r\n\r\n(https://20hzug.dbinfrago.com/) ‒ Neue Rolle „Rechnungsbahnhof – Anmeldung 20hfunktioniert weiterhin Züge“\r\n\r\n‒ Zusätzlicher Direktlink im Infraportal führt ‒ Die Freischaltung der E-Mail-Adressen durch die\r\n\r\nautomatisch in den Rechnungsbahnhof Kundenberatung entfällt damit zukünftig.\r\n\r\n‒ Hier steht zusätzlich neu auch eine Übersicht\r\n\r\naller 20h-Zug-Anmeldungen zur Verfügung\r\n\r\nDB InfraGO AG | TTT-Vertiefungstermin Umgang mit großen Verspätungen („20h-Züge“) | 15.07.2026 10",65,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":10,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","624946709c74a43578fac2d9689a96e2d1da429acd522031cc7ad5258b2757cd"],["chunk_ddb27af43f64e4e87ecbd654","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",10,"Seite 11","ReferenceTrainID*\r\n\r\nPostfach (erhält zusätzlich die E-Mails mit der Eingangsbestätigung und der 20h-Antrag-ID)\r\n\r\nWird vorbefüllt\r\n\r\nCheckbox mit Bestätigung: 20h-Zug darf in Konfiguration nicht geändert werden.\r\n\r\nDB InfraGO AG | TTT-Vertiefungstermin Umgang mit großen Verspätungen („20h-Züge“) | 15.07.2026 11",37,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":11,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","68b038c1c5c135ed9a95e6d5ff6a4820469154a60bb9ca5489cc31bbbcb45089"],["chunk_7d5bb8ad4b2cb4d900947e6c","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",11,"Seite 12","DB InfraGO AG | TTT-Vertiefungstermin Umgang mit großen Verspätungen („20h-Züge“) | 15.07.2026 12",13,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":12,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","84c2110d16f118467222b60a0f902683df0d7ca11f5bf895c0d16e07deab4115"],["chunk_6a219ad4d7f5ed4ebecfd1d2","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",12,"Seite 13","DB InfraGO AG | TTT-Vertiefungstermin Umgang mit großen Verspätungen („20h-Züge“) | 15.07.2026 13",13,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":13,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","df7d668c388c8af01eb67a1a89f2916fccbef7bf59f6d77573cd4db46ded074e"],["chunk_339389186e9416a3f278e45b","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",13,"Seite 14","DB InfraGO AG | TTT-Vertiefungstermin Umgang mit großen Verspätungen („20h-Züge“) | 15.07.2026 14",13,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":14,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","50ee6eee0c429590f1361154a7d76d3711361e4fb1daf3244af27f8fe8ee8cc5"],["chunk_7cc2f29452b4a495d9746465","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",14,"Seite 15","DB InfraGO AG | TTT-Vertiefungstermin Umgang mit großen Verspätungen („20h-Züge“) | 15.07.2026 15",13,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":15,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","a0409d0daa25f8479c16b5eec03dab3a75e5dd41a1bd4627f6fd249b8da8af72"],["chunk_4ddd4bb72b7249f454a04326","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",15,"Seite 16","Bitte stornieren Sie den Zug ab\r\n\r\nder verfügbaren Betriebsstelle,\r\n\r\ndie zuletzt durchfahren wurde.\r\n\r\nDB InfraGO AG | TTT-Vertiefungstermin Umgang mit großen Verspätungen („20h-Züge“) | 15.07.2026 16",26,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":16,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","658e9727d0bf6d7c70b33ac76d9de5fc476f58c8842078e1aa5126d54ba2d668"],["chunk_354f36920c42ddcf4ca68793","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",16,"Seite 17","Bitte geben Sie in dem Feld\r\n\r\nStornierungsgrund an, bis zu\r\n\r\nwelcher Betriebsstelle genau der\r\n\r\nOriginalzug tatsächlich gefahren\r\n\r\nist.\r\n\r\nDB InfraGO AG | TTT-Vertiefungstermin Umgang mit großen Verspätungen („20h-Züge“) | 15.07.2026 17",31,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":17,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","1b4ff9227edad01a93e51d43729fe1b7d29d617b134448a2478d3d2a1376a1e2"],["chunk_d2b3103e241dd344e86e89c7","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",17,"Seite 18","DB InfraGO AG | TTT-Vertiefungstermin Umgang mit großen Verspätungen („20h-Züge“) | 15.07.2026 18",13,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":18,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","27e674d77bc4492e39dcd0e950eb901a75354c495d29fb85296c4065dddc5bd4"],["chunk_a6663ac5dd03761b6fe1133f","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",18,"Seite 19","Bitte geben Sie in dem „Freetextfield“ an, bis zu welcher Betriebsstelle der Originalzug tatsächlich gefahren ist.\r\n\r\nDB InfraGO AG | TTT-Vertiefungstermin Umgang mit großen Verspätungen („20h-Züge“) | 15.07.2026 19",29,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":19,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","2fc7af895ecc2521ccf4d5ea9b6ea64ec4091932c5926459e375efb552c38474"],["chunk_78511445743d4a054a9453f7","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",19,"Seite 20","Sind in einer PDM ALLE Laufwegpunkte enthalten, so dass eine 20h-Teilstornierung wirklich ab jedem LWP\r\n\r\ntechnisch möglich ist? Heutzutage sind in einem TPN-Datensatz ja nicht alle LWP enthalten, so dass Teilstornos nur\r\n\r\neingeschränkt möglich sind.\r\n\r\n>> Nein, es sind nicht alle Laufwegspunkte enthalten.\r\n\r\nBitte wählen Sie bei der Stornierung jene verfügbare Betriebsstelle aus, die zuletzt durchfahren wurde und\r\n\r\ngeben Sie in dem Stornierungsgrund die zuletzt gefahrene Betriebsstelle an.\r\n\r\nKann auch eine Änderungsbestellung anstatt einer Stornierung eingereicht werden?\r\n\r\n>> Nein, Änderungsbestellungen in die Vergangenheit sind nicht erlaubt.\r\n\r\nEine Änderungsbestellung würde zu einer Splittung der PathDetailsMessage führen, da wir keine Änderung der OTN\r\n\r\ninnerhalb einer PDM durchführen dürften.\r\n\r\nDB InfraGO AG | TTT-Vertiefungstermin Umgang mit großen Verspätungen („20h-Züge“) | 15.07.2026 20",119,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":20,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","30031501f373206e35eae311fb9d72dc3c578f59bf9cb0841216a8e3e395339b"],["chunk_ad4c792bf9c56e0715a08fc9","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",20,"Seite 21","DB InfraGO AG | TTT-Vertiefungstermin Umgang mit großen Verspätungen („20h-Züge“) | 15.07.2026 21",13,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":21,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","60ad5d613598534cffb26df64be1916fa56c6782aced182e3f061af6036a205f"],["chunk_877934ddbd2998026f87fe24","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",21,"Seite 22","‒ Auswählen von VerkehrsArtKundeZusatz „20h-Zug“\r\n\r\nschaltet das Feld Nachlassnummer frei.\r\n\r\n‒ Angabe der Antrags-ID im Feld Nachlassnummer\r\n\r\n(Produktausprägungen/Sonstige Angaben) ist\r\n\r\nzwingend\r\n\r\n‒ Jede ID ist nur einmalig verwendbar\r\n\r\n‒ Berücksichtigung in der Abrechnung kann nur\r\n\r\ngewährleistet werden, wenn beide Merkmale korrekt\r\n\r\nbefüllt sind\r\n\r\nDB InfraGO AG | TTT-Vertiefungstermin Umgang mit großen Verspätungen („20h-Züge“) | 15.07.2026 22",56,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":22,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","cfe039742c5f425930f009ca48c721e4b4b3e237f7ec44b6e2323bbf7d025aa3"],["chunk_0ee9c9ec23b18b92b9691325","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",22,"Seite 23","‒ Es muss eine Trassenerstbestellung aus dem GelV über die SST ausgelöst werden\r\n\r\n‒ Das Feld rabattNr darf nur dann mit einer 20h-Antrag-ID befüllt werden, wenn in\r\n\r\nverkehrsArtKundeZusatz „20h-Zug“ ausgewählt wurde\r\n\r\n‒ verkehrsArtKundeZusatz „20h-Zug“ ohne Angabe einer 20h-Antrag-ID führt zur Abrechnung\r\n\r\neiner Regeltrasse\r\n\r\nDB InfraGO AG | TTT-Vertiefungstermin Umgang mit großen Verspätungen („20h-Züge“) | 15.07.2026 23",56,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":23,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","574161ed41d2bd2fe9473c8d15faad7d7ee6a9f07ebf652d3eb9d4020404981f"],["chunk_28da99700be1799106aea269","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",23,"Seite 24","Wo muss die 20h-Antrag-ID hinterlegt werden?\r\n\r\n>> Bestellportal: Feld „Nachlassnummer“\r\n\r\nSchnittstelle: NSP „rabattNr“\r\n\r\nWelche Felder müssen zur Kennung als 20h-Zug mitgegeben werden?\r\n\r\n> verkehrsArtKundeZusatz > Auswahl „20h-Zug“\r\n\r\nDB InfraGO AG | TTT-Vertiefungstermin Umgang mit großen Verspätungen („20h-Züge“) | 15.07.2026 24",40,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":24,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","f4fc615fff02035720ce039b7c4a58cc53f3a8403862bfbc38a99861eea3b15c"],["chunk_22e6247e8a6428d1f6189b73","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",24,"Seite 25","DB InfraGO AG | TTT-Vertiefungstermin Umgang mit großen Verspätungen („20h-Züge“) | 15.07.2026 25",13,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":25,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","7328c5702038142f2da77575c58fc47dc7534df33fc2c551e68058df701daac9"],["chunk_ff7bfb99712c3197155c0d82","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",25,"Seite 26","Zeit für Ihre Fragen!\r\n\r\nGerne beantworten wir Ihnen\r\n\r\nIhre Fragen direkt im Termin.\r\n\r\nDB InfraGO AG | TTT-Vertiefungstermin Umgang mit großen Verspätungen („20h-Züge“) | 15.07.2026 26",26,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":26,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","4fb2a9f4f066a2fad92fff074a6a971b196cf4953800f42ed7b3a0c84c8b44a0"],["chunk_1e3223cb616ea35ad438e4ea","wiki/sources/infoveranstaltung-vertiefung-20h-zug-15-juli-2026-terminunterlage-data.md",26,"Seite 27","Ab welcher Betriebsstelle soll die Neubestellung angelegt werden?\r\n\r\n>> Bitte bestellen Sie den neuen Zug ab der Betriebsstelle, an welcher der Originalzug tatsächlich stehengeblieben ist.\r\n\r\nWarum muss Neubestellung und Stornierung durch das EVU erfolgen?\r\n\r\n>> Die Stornierung muss erfolgen, damit die für den Tag verwendete ReferenceTrainID für die Wiederverwendung des\r\n\r\nstehengebliebenen Zuges freigegeben werden kann. Die Neubestellung muss erfolgen, da sich durch die veränderte Zeit\r\n\r\nauch die EVU-eigenen Rahmenbedingungen verändert haben können, die wir als Infrastrukturbetreiber nicht wissen\r\n\r\nkönnen. Bsp: Was ist die neue gewünschte Abfahrt? Benötigen Sie unterwegs noch Halte für einen Tf-Wechsel oder\r\n\r\nähnliches? Darüber hinaus müssen Sie sicherstellen, dass die in der Bestellung verwendete ReferenceTrainID für den Tag\r\n\r\nfrei ist.\r\n\r\nZusätzlich gab es Feedback aus dem Markt, dass die Lösung sicher stellen muss, dass die IT-Systeme der EVU aktuell\r\n\r\ngehalten werden sollen. Dem trägt die aktuelle Lösung ebenfalls Rechnung.\r\n\r\nDB InfraGO AG | TTT-Vertiefungstermin Umgang mit großen Verspätungen („20h-Züge“) | 15.07.2026 27",155,"{\"canonical_url\":null,\"normalized_sha256\":\"0f6928e4a459d201fd1f23fa366e755f76468bf60a08dabaf10e26be37ea7aa8\",\"page\":27,\"source_id\":\"src_b1dc4ddce9e5b5a345e6\",\"source_sha256\":\"20848958c0b6e9f3ebfd74418fcaa3031f0095f16c8e9c4ee2900eca13bf4971\",\"source_version_id\":\"sv_20848958c0b6e9f3ebfd7441\"}","dea7182f610db36bbe6c5c8553c3628f79b676dfed0adca23ad06f2b59fc0ce7"]]');
