INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_e0b9e02b716fe489169b0327","wiki/sources/taf-tap-tsi-dialog-21-mai-2026-terminunterlage-data.md",3,"Seite 4","2. Status TTT Einführung\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 21.05.2026 4",13,"{\"canonical_url\":null,\"normalized_sha256\":\"ae6fb1592120714ce20618e6d58b112f1d0c662a71dda57469141b3f82e7068e\",\"page\":4,\"source_id\":\"src_1f6c2d00fd116ecf0611\",\"source_sha256\":\"12227c0c6672e3e4736d2c8bd72098d8868235b0b8e150df5a2295ae171901e3\",\"source_version_id\":\"sv_12227c0c6672e3e4736d2c8b\"}","deef74fd570cfd53ddce30965e3370bbd3de490b23849bdbf34f084bb2a3d891"],["chunk_8fe290687c7734d00249262e","wiki/sources/taf-tap-tsi-dialog-21-mai-2026-terminunterlage-data.md",4,"Seite 5","Status TTT\r\n\r\nErgebnisse seit letztem TTT-Dialog\r\n\r\n✓ Lieferung GelV Funktionalitäten vollständig im Markttest (letzte Lieferung ergänzte u.a.\r\n\r\nAnmeldung mit Annahmeverzicht = Anmeldung mit Annahmeerklärung)\r\n\r\n✓ Mittiger Teilausfall im Markttest mit Testeinschränkung zum Versand NAÄ\r\n\r\n✓ Informationsveranstaltungen zu unterjährigem Bau mit Fokus auf Digitale Bau Fplo (20.5.)\r\n\r\n✓ Stammdaten für Trassenbestellung aktualisiert und als Ordnungsrahmen Jahresfahrplan 2027.3\r\n\r\nbereitgestellt: Es wurden ausländische Betriebsstellen ergänzt und die Strecke 6814 korrigiert\r\n\r\n▪ Netzfahrplanerstellung läuft\r\n\r\nNächste Schritte\r\n\r\n• Markttests für Trassenanmeldung/ujBau und Defect-Behebung kontinuierlich fortsetzen\r\n\r\n• Markttest TTT mit Identifiern im Betrieb fortsetzen;\r\n\r\nweiterer Testzeitraum für EVU, die aktuell noch nicht testfähig sind, wird geplant\r\n\r\n• Maßnahmen basierend auf Feedback zu KOMBau Kundentests, Schulungsmaterial und Planung\r\n\r\ndefinieren und umsetzen\r\n\r\n• Nächster TTT-Dialog am 24.06.2026\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 21.05.2026 5",128,"{\"canonical_url\":null,\"normalized_sha256\":\"ae6fb1592120714ce20618e6d58b112f1d0c662a71dda57469141b3f82e7068e\",\"page\":5,\"source_id\":\"src_1f6c2d00fd116ecf0611\",\"source_sha256\":\"12227c0c6672e3e4736d2c8bd72098d8868235b0b8e150df5a2295ae171901e3\",\"source_version_id\":\"sv_12227c0c6672e3e4736d2c8b\"}","2056033145202678b8f772cfb98f33574dbc51b136c7089eb59d719e9e94e1bc"],["chunk_7ac64c2e8b77eb91d4809b27","wiki/sources/taf-tap-tsi-dialog-21-mai-2026-terminunterlage-data.md",5,"Seite 6","3. Update pathOS\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 21.05.2026 6",12,"{\"canonical_url\":null,\"normalized_sha256\":\"ae6fb1592120714ce20618e6d58b112f1d0c662a71dda57469141b3f82e7068e\",\"page\":6,\"source_id\":\"src_1f6c2d00fd116ecf0611\",\"source_sha256\":\"12227c0c6672e3e4736d2c8bd72098d8868235b0b8e150df5a2295ae171901e3\",\"source_version_id\":\"sv_12227c0c6672e3e4736d2c8b\"}","f811958e0cd33721fabdb3e587569f836843e2332fb4366bfb55f2206f7a01c8"],["chunk_7aa9176e4f00b52461de1e48","wiki/sources/taf-tap-tsi-dialog-21-mai-2026-terminunterlage-data.md",6,"Seite 7","Weiterhin Schulungen und Sprechstunden\r\n\r\nInformationen & Schulungen Sprechstunden\r\n\r\n• Web-based-Trainings (WBT) • Für die Einführungsphase GelV sind wieder\r\n\r\nSprechstunden geplant\r\n\r\n• Erklärvideos zur Vertiefung einzelner\r\n\r\nWissen teilen. • Die Frequenz der Sprechstunden wird durch die\r\n\r\nAnwendungsfälle\r\n\r\nFragen klären.\r\n\r\nTeilnahme gesteuert\r\n\r\n• Handbuch mit umfangreichem Detailwissen Erfolg\r\n\r\ngemeinsam\r\n\r\n• Vertiefungsworkshops\r\n\r\ngestalten.\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 21.05.2026 7",59,"{\"canonical_url\":null,\"normalized_sha256\":\"ae6fb1592120714ce20618e6d58b112f1d0c662a71dda57469141b3f82e7068e\",\"page\":7,\"source_id\":\"src_1f6c2d00fd116ecf0611\",\"source_sha256\":\"12227c0c6672e3e4736d2c8bd72098d8868235b0b8e150df5a2295ae171901e3\",\"source_version_id\":\"sv_12227c0c6672e3e4736d2c8b\"}","0b0815f16722571af31907d9485972a62d319a42d816272a7372c18c2b316f22"],["chunk_303ee321dc9ebc8b34c3af06","wiki/sources/taf-tap-tsi-dialog-21-mai-2026-terminunterlage-data.md",7,"Seite 8","Supportkanäle und Hinweis zu VNP\r\n\r\nE-Mail Kontaktformular Telefon Fragen zu einem\r\n\r\nkonkreten Angebot?\r\n\r\n[E-Mail-Adresse entfernt] Kontaktformular pathOS [Telefonnummer entfernt] Bitte nutzen Sie direkt die im\r\n\r\njeweiligen Angebot\r\n\r\nHomepage DB InfraGO\r\n\r\nhinterlegten Kontaktdaten.\r\n\r\nSupport\r\n\r\n→ Aktuelle Informationen zur Anwendung sind im Infraportal unter Aktuelles zu den Tools zu finden.\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 21.05.2026 8",57,"{\"canonical_url\":null,\"normalized_sha256\":\"ae6fb1592120714ce20618e6d58b112f1d0c662a71dda57469141b3f82e7068e\",\"page\":8,\"source_id\":\"src_1f6c2d00fd116ecf0611\",\"source_sha256\":\"12227c0c6672e3e4736d2c8bd72098d8868235b0b8e150df5a2295ae171901e3\",\"source_version_id\":\"sv_12227c0c6672e3e4736d2c8b\"}","2f789156851af42cf2651c094e5883d5a1924a61f39a8e1f4a6b85912f638e31"],["chunk_b7f0078da45caab814473408","wiki/sources/taf-tap-tsi-dialog-21-mai-2026-terminunterlage-data.md",8,"Seite 9","Onboarding dauert im Mittel 5 Wochen! Sehr viele unterschiedliche\r\n\r\n(Minimum 2 Wochen, Maximum 12 Wochen) Herausforderungen bei den\r\n\r\nKundensystemen\r\n\r\nWenn Sie planen per IT-Schnittstelle (Common Interface – CI) zu bestellen, d.h. eine\r\n\r\neigene Software zur Bestellung zu nutzen und noch nicht ongeboardet sind,\r\n\r\nkommen Sie möglichst bald auf uns zu.\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 21.05.2026 9",59,"{\"canonical_url\":null,\"normalized_sha256\":\"ae6fb1592120714ce20618e6d58b112f1d0c662a71dda57469141b3f82e7068e\",\"page\":9,\"source_id\":\"src_1f6c2d00fd116ecf0611\",\"source_sha256\":\"12227c0c6672e3e4736d2c8bd72098d8868235b0b8e150df5a2295ae171901e3\",\"source_version_id\":\"sv_12227c0c6672e3e4736d2c8b\"}","f84837ea1ec3bacb61697c855a0b2a34913c4b87f9c2451fc8da6491c8bfaf7c"],["chunk_ddcea4bd4b0c74e95c08fa87","wiki/sources/taf-tap-tsi-dialog-21-mai-2026-terminunterlage-data.md",9,"Seite 10","4. Click & Ride mit TTT\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 21.05.2026 10",15,"{\"canonical_url\":null,\"normalized_sha256\":\"ae6fb1592120714ce20618e6d58b112f1d0c662a71dda57469141b3f82e7068e\",\"page\":10,\"source_id\":\"src_1f6c2d00fd116ecf0611\",\"source_sha256\":\"12227c0c6672e3e4736d2c8bd72098d8868235b0b8e150df5a2295ae171901e3\",\"source_version_id\":\"sv_12227c0c6672e3e4736d2c8b\"}","fe0c4113cf37bba8b4ade8fb61a5e8a4a4b89342833aa907b5beaea3f8878609"],["chunk_eff9f1254d1334b3d6563d11","wiki/sources/taf-tap-tsi-dialog-21-mai-2026-terminunterlage-data.md",10,"Seite 11","Was ändert sich in Click & Ride mit TTT?\r\n\r\n• Click&Ride unterstützt ab Fahrplanjahr 2027 TTT\r\n\r\n• TTT-Identifier sind eingebbar (siehe Screenshot)\r\n\r\n• Erfolgt keine Vergabe durch das bestellende EVU,\r\n\r\nvergibt DB InfraGO im Namen des EVU hilfsweise\r\n\r\ndie Identifier\r\n\r\n• Stornierung und Änderung von Trassen erfolgen in\r\n\r\npathOS\r\n\r\n• Nach Buchung zeigt Click&Ride die TTT-Identifier in der\r\n\r\nOberfläche und in der Bestätigungs-E-Mail\r\n\r\n• Eingabeoptionen ansonsten weitgehend unverändert\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 21.05.2026 11",77,"{\"canonical_url\":null,\"normalized_sha256\":\"ae6fb1592120714ce20618e6d58b112f1d0c662a71dda57469141b3f82e7068e\",\"page\":11,\"source_id\":\"src_1f6c2d00fd116ecf0611\",\"source_sha256\":\"12227c0c6672e3e4736d2c8bd72098d8868235b0b8e150df5a2295ae171901e3\",\"source_version_id\":\"sv_12227c0c6672e3e4736d2c8b\"}","6bff70482db90664ab4803b2d22e7268bc4dd79dc13e5972542daa15d18a98fe"],["chunk_bbe2e01e7e6eba2fc1ef664f","wiki/sources/taf-tap-tsi-dialog-21-mai-2026-terminunterlage-data.md",11,"Seite 12","5. Fragen & Antworten\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 21.05.2026 12",13,"{\"canonical_url\":null,\"normalized_sha256\":\"ae6fb1592120714ce20618e6d58b112f1d0c662a71dda57469141b3f82e7068e\",\"page\":12,\"source_id\":\"src_1f6c2d00fd116ecf0611\",\"source_sha256\":\"12227c0c6672e3e4736d2c8bd72098d8868235b0b8e150df5a2295ae171901e3\",\"source_version_id\":\"sv_12227c0c6672e3e4736d2c8b\"}","90fff194be71a14c006697261f07774ce6a92f0e5694fd3ed8c1f55133b87273"],["chunk_f9f4fd9cdc4db19aca7b8684","wiki/sources/taf-tap-tsi-dialog-21-mai-2026-terminunterlage-data.md",12,"Seite 13","Information „Kanalzwang“ (GPE/FPE vs. Trassenanmeldung)\r\n\r\nProzess Prozessbeginn Prozessende Mögliche Kanäle Kanalzwang Hinweise\r\n\r\n(ja/nein)\r\n\r\nTrassenerst- Abgabe der Trassen- Bestätigung einer neuen Web-Oberfläche Jede Trasse wird\r\n\r\nbestellungen bestellung bei InfraGO Trasse, Nichtkonstruier- pathOS oder separat behandelt\r\n\r\nJa\r\n\r\nbarkeit oder Abbruch Click&Ride\r\n\r\ndurch Kunden\r\n\r\nKunden- IT & Ja\r\n\r\nCommon Interface\r\n\r\nTrassen- Abgabe der Änderung Geänderte Trasse, Web-Oberfläche Ja Jede Trasse wird\r\n\r\nänderungen* bei InfraGO Nichtkonstruierbarkeit pathOS separat behandelt\r\n\r\ndurch Besteller /Erhalt Bestand,\r\n\r\nAbbruch durch Kunden\r\n\r\nKunden- IT & Ja\r\n\r\nCommon Interface\r\n\r\nTrassen- Bereitstellung der Geänderte Trasse, Web-Oberfläche siehe Hinweise Kanalzwang entsteht\r\n\r\nänderungen* Änderung Nichtkonstruierbarkeit pathOS durch Wahl des\r\n\r\nInfraGO /Erhalt Bestand, Kanals durch den\r\n\r\nKunden-IT &\r\n\r\nAbbruch durch Kunden Kunden\r\n\r\nCommon Interface\r\n\r\nujBau Bereitstellung GPE Bereitstellung FPE KOMBau nein\r\n\r\nKunden- IT & nein\r\n\r\nCommon Interface\r\n\r\n* Subsummiert Änderungen und Stornierungen inkl. Folgeaktivitäten aus ujBau\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 21.05.2026 13",140,"{\"canonical_url\":null,\"normalized_sha256\":\"ae6fb1592120714ce20618e6d58b112f1d0c662a71dda57469141b3f82e7068e\",\"page\":13,\"source_id\":\"src_1f6c2d00fd116ecf0611\",\"source_sha256\":\"12227c0c6672e3e4736d2c8bd72098d8868235b0b8e150df5a2295ae171901e3\",\"source_version_id\":\"sv_12227c0c6672e3e4736d2c8b\"}","cc397bc1e7ba176fff1bdeb4cd301aef5f35f74fd4df8c74c0ad470e8138d4e3"],["chunk_75a2934a28de0d61de751406","wiki/sources/taf-tap-tsi-dialog-21-mai-2026-terminunterlage-data.md",13,"Seite 14","Information zur Trassenkommunikation 2026: VNP, GPE und\r\n\r\nNAÄ/NAS\r\n\r\nVorläufiger Netzfahrplan (VNP):\r\n\r\n• Hinweis: Technisch wird der VNP nicht „auf einmal“ versendet, sondern der Versand wird durch\r\n\r\ndie Konstrukteure durch entsprechende Auswahl von Trassen ausgelöst. Daher wird der Empfang\r\n\r\nnicht auf genau einem Zeitpunkt liegen sondern etwas verteilt sein.\r\n\r\nVersand GPE:\r\n\r\n• Es wird prozessual sichergestellt, dass das GPE erst nach dem VNP versandt wird. Der VNP ist\r\n\r\nBasis der ersten GPE, damit kann das GPE nicht vor dem VNP verschickt werden.\r\n\r\nStart Versand Netzausgelöste Änderung & Stornierung (NAÄ & NAS):\r\n\r\n• Es liegt aktuell eine Testeinschränkung vor, weil die automatische Annahme des NAÄ noch nicht\r\n\r\nvollständig korrekt implementiert ist. ​\r\n\r\n• Die Lieferung in den Kundentest ist für spätestens 29. Juli geplant.\r\n\r\n• DB InfraGO AG wird diese Lücke vor der Versendung der ersten NAÄ schließen. Es ist nicht\r\n\r\nnotwendig sich auf Seiten der EVU auf alternative Prozesse einzustellen.\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 21.05.2026 14",158,"{\"canonical_url\":null,\"normalized_sha256\":\"ae6fb1592120714ce20618e6d58b112f1d0c662a71dda57469141b3f82e7068e\",\"page\":14,\"source_id\":\"src_1f6c2d00fd116ecf0611\",\"source_sha256\":\"12227c0c6672e3e4736d2c8bd72098d8868235b0b8e150df5a2295ae171901e3\",\"source_version_id\":\"sv_12227c0c6672e3e4736d2c8b\"}","8537158d3b0f6af751a512f4521ce180839796fbbb27b7c8043c43b85973f81d"],["chunk_fd00e6ac3d281acc4f531fd2","wiki/sources/taf-tap-tsi-dialog-21-mai-2026-terminunterlage-data.md",14,"Seite 15","Änderungen an Rechnungsinhalten im Kontext TTT\r\n\r\nAuswirkungen von TTT auf Rechnungsinhalte\r\n\r\nDB InfraGO wird im August 2026 die genauen Rechnungsinhalte mit TTT\r\n\r\nveröffentlichen. Eine Ergänzung der Rechnungsdokumente mit TTT-Attributen\r\n\r\nist geplant. Die Rechnung wird weiterhin die OTN enthalten.\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 21.05.2026 15",47,"{\"canonical_url\":null,\"normalized_sha256\":\"ae6fb1592120714ce20618e6d58b112f1d0c662a71dda57469141b3f82e7068e\",\"page\":15,\"source_id\":\"src_1f6c2d00fd116ecf0611\",\"source_sha256\":\"12227c0c6672e3e4736d2c8bd72098d8868235b0b8e150df5a2295ae171901e3\",\"source_version_id\":\"sv_12227c0c6672e3e4736d2c8b\"}","b8ff650a82f0e6ea6d474d48b3c36cef8d719a28c8dcce3a755dd3dc52edcac6"],["chunk_f9399215acf627857057bfe1","wiki/sources/taf-tap-tsi-dialog-21-mai-2026-terminunterlage-data.md",15,"Seite 16","Prozess zur baubedingten Zusatzleistung im Kontext TTT\r\n\r\nAblauf und Kennzeichnung baubedingter Zusatzleistungen\r\n\r\nBei der Bestellung wird ein Verweis des EVUs auf die PathID der Bautrasse\r\n\r\nerforderlich sein. Dieser wird als „RelatedPlannedTransportID“ angegeben.\r\n\r\nZusätzlich muss beim NSP* „verkehrsArtKundeZusatz“ die Ausprägung\r\n\r\n„BaubedingteZusatzleistung“ angegeben werden.\r\n\r\n* NSP: network specific parameter\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 21.05.2026 16",56,"{\"canonical_url\":null,\"normalized_sha256\":\"ae6fb1592120714ce20618e6d58b112f1d0c662a71dda57469141b3f82e7068e\",\"page\":16,\"source_id\":\"src_1f6c2d00fd116ecf0611\",\"source_sha256\":\"12227c0c6672e3e4736d2c8bd72098d8868235b0b8e150df5a2295ae171901e3\",\"source_version_id\":\"sv_12227c0c6672e3e4736d2c8b\"}","00b0aad3d1825ab772caca93f1c1de77a2d960f009e3cab603a2813e2580940d"],["chunk_8c481ab6871d37df29241fd8","wiki/sources/taf-tap-tsi-dialog-21-mai-2026-terminunterlage-data.md",16,"Seite 17","Zeit für Ihre Fragen!\r\n\r\nGerne beantworten wir Ihnen\r\n\r\nIhre Fragen direkt im Termin.\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 21.05.2026 17",22,"{\"canonical_url\":null,\"normalized_sha256\":\"ae6fb1592120714ce20618e6d58b112f1d0c662a71dda57469141b3f82e7068e\",\"page\":17,\"source_id\":\"src_1f6c2d00fd116ecf0611\",\"source_sha256\":\"12227c0c6672e3e4736d2c8bd72098d8868235b0b8e150df5a2295ae171901e3\",\"source_version_id\":\"sv_12227c0c6672e3e4736d2c8b\"}","d05be6edc486c9469a182d166ec9634c04ab4c4a531ffb858f715d445aae9e47"],["chunk_5c68f1f22f29a23159955753","wiki/sources/taf-tap-tsi-dialog-21-mai-2026-terminunterlage-data.md",17,"Seite 18","6. Zum Nachlesen:\r\n\r\nNächste Termine\r\n\r\nAlle Informationen immer aktuell unter:\r\n\r\nwww.dbinfrago.com/taf-tap-tsi\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 21.05.2026 18",20,"{\"canonical_url\":null,\"normalized_sha256\":\"ae6fb1592120714ce20618e6d58b112f1d0c662a71dda57469141b3f82e7068e\",\"page\":18,\"source_id\":\"src_1f6c2d00fd116ecf0611\",\"source_sha256\":\"12227c0c6672e3e4736d2c8bd72098d8868235b0b8e150df5a2295ae171901e3\",\"source_version_id\":\"sv_12227c0c6672e3e4736d2c8b\"}","aaa8cb94e9a7f380a02ce8acfc35ad844a139e4deb40754a914b93023d80368d"],["chunk_12930f8f00cbf6d9c1654863","wiki/sources/taf-tap-tsi-dialog-21-mai-2026-terminunterlage-data.md",18,"Seite 19","Nächster TTT-Dialog: 24.06., 12:30-14:30 Uhr\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 21.05.2026 19",14,"{\"canonical_url\":null,\"normalized_sha256\":\"ae6fb1592120714ce20618e6d58b112f1d0c662a71dda57469141b3f82e7068e\",\"page\":19,\"source_id\":\"src_1f6c2d00fd116ecf0611\",\"source_sha256\":\"12227c0c6672e3e4736d2c8bd72098d8868235b0b8e150df5a2295ae171901e3\",\"source_version_id\":\"sv_12227c0c6672e3e4736d2c8b\"}","5f0d482887dbcd5097ad3d479bbf521ed0ab59dffb1543dce0daddd78b4e53e0"],["chunk_3365d44be991b837d6c8b4fd","wiki/sources/taf-tap-tsi-dialog-21-mai-2026-terminunterlage-data.md",19,"Seite 20","Übersicht TAF/TAP TSI-Kommunikation\r\n\r\nArbeitsweise (A)/Turnus (T)\r\n\r\nTeilnehmer: Management & Experten aller EVU u. deren IT-Partner A: online\r\n\r\nTAF/TAP TSI\r\n\r\n1 Ziel: Überblick für GF-Ebene, allg. Infos (Betrieb + Fahrplan), zzgl. Vertiefung T: ca. monatlich\r\n\r\n-Dialog\r\n\r\naktueller Fokusthemen in Entwicklung/Testing Nächster Termin: 24.06.\r\n\r\nTAF/TAP TSI –\r\n\r\n2 Teilnehmer: Schnittstellenpartner Fahrplan, die bereits mit uns testen A: online\r\n\r\nSchnittstellen-\r\n\r\nZiel: Aktuelle Informationen/Entwicklungen; Sprechstunde, Updates T: nach Bedarf\r\n\r\npartner Fahrplan\r\n\r\nTeilnehmer: Alle künftigen Anwendenden von pathOS A: online\r\n\r\npathOS -\r\n\r\n3 Ziel: Erklärung der Grundlagen und wesentlichen Inhalte von pathOS in einzelnen T: seit 23.10.2025 – Termine auf\r\n\r\nSchulungen\r\n\r\nTerminen pathOS-Homepage (unter Kapitel 2.4)\r\n\r\nTAF/TAP TSI - Teilnehmer: Gesamtmarkt inkl. EIU A: online / in Präsenz\r\n\r\ne 4\r\n\r\ng Sektormeeting Ziel: nationale Spiegelgruppe TTT (Infos zu TTT, Verordnungen, ...) T: 4x jährlich, Nächster Termin: 11.06.\r\n\r\no\r\n\r\nla\r\n\r\ni\r\n\r\nD A: in Präsenz\r\n\r\nRunder Tisch Bau Teilnehmer: 35 Mitglieder aus SPNV, SPV, SGV, BNetzA, Verbände, AT\r\n\r\n5 T: 4x p.a.\r\n\r\n(RTB) AG 3 Ziel: Beratung DB InfraGO bei Erarbeitung und Entwicklung für ujBau\r\n\r\nNächster Termin: 01.09.\r\n\r\nEVU-Informations- Teilnehmer: Gesamtmarkt\r\n\r\nA: online\r\n\r\n6 veranstaltung unter- Ziel: Information zum neuen unterjährigen Baufahrplanprozess mit neuen\r\n\r\nT: nach Bedarf\r\n\r\njähriger Bau Fahrplanprodukten und der digitalen BauFplo\r\n\r\nTeilnehmer: Geschäftspartner mit G-INV A: online\r\n\r\n7 BDV\r\n\r\nZiel: Informationen, To-Dos vermitteln Nächster Termin: in Planung\r\n\r\no Homepage + Teilnehmer: für alle zugängliches Format, KI an Verteiler (inkl. IT-Partner, nicht alle EVU) A: Homepage",232,"{\"canonical_url\":null,\"normalized_sha256\":\"ae6fb1592120714ce20618e6d58b112f1d0c662a71dda57469141b3f82e7068e\",\"page\":20,\"source_id\":\"src_1f6c2d00fd116ecf0611\",\"source_sha256\":\"12227c0c6672e3e4736d2c8bd72098d8868235b0b8e150df5a2295ae171901e3\",\"source_version_id\":\"sv_12227c0c6672e3e4736d2c8b\"}","2787912e244c9df507710d4a24a96ac96567cfb12a86e9099d827421627ec8fa"],["chunk_4a7484f76e1c8c4f8af4413f","wiki/sources/taf-tap-tsi-dialog-21-mai-2026-terminunterlage-data.md",20,"Seite 20","f n 8 Newsletter (KI) Ziel: aktuelle Informationen zum Nachlesen: Testing-Zugang, Ansprechpartner, Updates T: kontinuierlich\r\n\r\nI\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 21.05.2026 20",25,"{\"canonical_url\":null,\"normalized_sha256\":\"ae6fb1592120714ce20618e6d58b112f1d0c662a71dda57469141b3f82e7068e\",\"page\":20,\"source_id\":\"src_1f6c2d00fd116ecf0611\",\"source_sha256\":\"12227c0c6672e3e4736d2c8bd72098d8868235b0b8e150df5a2295ae171901e3\",\"source_version_id\":\"sv_12227c0c6672e3e4736d2c8b\"}","4c3e5351320ee4f54827d35b9d2fc1e74b1b1aa8e038dc9851568f4fec23ada5"],["chunk_e6ea23ffe2112ef421590776","wiki/sources/taf-tap-tsi-dialog-21-mai-2026-terminunterlage-data.md",21,"Seite 21","Übersicht KOMBau-Kommunikation\r\n\r\nArbeitsweise (A)/Turnus (T)\r\n\r\nEinweisungstermin Teilnehmer: Gesamtmarkt inkl. EIU\r\n\r\nA: online\r\n\r\n1 4. Konsultationsphase Ziel: Teilnehmenden die Funktionen, Prozesse und Anwendungsmöglichkeiten der KOMBau\r\n\r\nT: 29.04.2026 + 07.05.2026\r\n\r\n(KP) Thema BKE/BAE in der 4. KP anschaulich zu vermitteln\r\n\r\nKundentesttage\r\n\r\nA: online*\r\n\r\nFrontend 4. Teilnehmer: Fachexperten und Anwender der EVU, Verkehrsarten repräsentativ abgedeckt\r\n\r\n2 T: 11.05.2026, 13.05.2026 +\r\n\r\nKonsultationsphase Ziel: Verproben des Workflows 4. KP GPE bis FPE und Feedback\r\n\r\n18.05.2026\r\n\r\n(GPE bis FPE)\r\n\r\nEinweisungstermin\r\n\r\nTeilnehmer: Gesamtmarkt A: online*\r\n\r\n4. Konsultationsphase\r\n\r\n3 Ziel: Teilnehmenden die Funktionen, Prozesse und Anwendungsmöglichkeiten der KOMBau T: 12.06.2026, 19.06.2026 +\r\n\r\n(KP) Thema GPE/\r\n\r\nin der 4. KP anschaulich zu vermitteln 26.06.2026\r\n\r\nGPEnS/FPE\r\n\r\n*Kund:inneninformationen und Einladungen werden in den kommenden Wochen versendet\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 21.05.2026 21",124,"{\"canonical_url\":null,\"normalized_sha256\":\"ae6fb1592120714ce20618e6d58b112f1d0c662a71dda57469141b3f82e7068e\",\"page\":21,\"source_id\":\"src_1f6c2d00fd116ecf0611\",\"source_sha256\":\"12227c0c6672e3e4736d2c8bd72098d8868235b0b8e150df5a2295ae171901e3\",\"source_version_id\":\"sv_12227c0c6672e3e4736d2c8b\"}","108a3c2ce79d9206563c95e504ffc8aada8631d2c46cd2ba0f0a6693d6e128a4"],["chunk_88b72f48231ad531d58302e7","wiki/sources/taf-tap-tsi-dialog-22-april-2026-antworten-und-offene-punkte-data.md",0,"Seite 1","14. TAF/TAP TSI-Dialog der DB InfraGO\r\n\r\nFollow-up: Ausgewählte Antworten aus dem Termin\r\n\r\n22.04.2026 Versand im\r\n\r\nNachgang",16,"{\"canonical_url\":null,\"normalized_sha256\":\"0629a1f4df3af0861459be12aad8be05d74e88666f80dab4353848fabc5e63e7\",\"page\":1,\"source_id\":\"src_8b2e5ffa1f464bee18cf\",\"source_sha256\":\"abacab26d0837e86a436bb01429fc0431caffc556ac17a01fa1a0bd5ac1a0703\",\"source_version_id\":\"sv_abacab26d0837e86a436bb01\"}","a7b1617c3b716deb5196d815c3ba791cbbb691a35e76fb7bfc455accabdabbfe"]]');
