INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_d1cc1bcc58ca6ac0393f762f","wiki/sources/taf-tap-tsi-dialog-22-april-2026-antworten-und-offene-punkte-data.md",1,"Seite 2","Offene Punkte und Antworten (1/5)\r\n\r\nFrage Antwort DB InfraGO\r\n\r\nIst für die Nutzung der Schnittstelle zur Nein. EVU, die das Onboarding für NEP bereits erfolgreich absolviert haben, sind auf Produktion\r\n\r\nTrassenanmeldung im GelV ein angebunden und müssen kein weiteres Onboarding für GelV durchlaufen.\r\n\r\nerneutes Onboarding erforderlich,\r\n\r\nwenn das Onboarding für NEP bereits\r\n\r\nerfolgt ist?\r\n\r\nOb und wann werden die TTT- Click&Ride wird für die Nutzung um Fahrplan 2027 mit TAF/TAF ertüchtigt. Die zugehörige\r\n\r\nKomponenten / ID''s bei Click and Ride Entwicklung ist bereits in Vorbereitung. Die zugehörigen Meilensteine mit Fokus auf Schulungen und\r\n\r\nimplementiert. Gibt es hierzu auch Testmöglichkeiten werden im nächsten TTT-Dialog vorgestellt.\r\n\r\nSchulungsunterlagen/ Möglichkeiten\r\n\r\noder eine Testplattform?\r\n\r\nRückfrage zur genannten Frist für Eine NAÄ gilt nach Versand direkt als angenommen. Für ZB besteht jedoch die Möglichkeit, die\r\n\r\nkostenlose Stornierung nach NAÄ: Sind Trasse innerhalb von drei Arbeitstagen (Montag bis Freitag, ausgenommen bundeseinheitliche\r\n\r\n3 Arbeitstage oder 3 Werktage hier Feiertage) kostenfrei zu stornieren.\r\n\r\ngemeint?\r\n\r\nWenn wir die NAÄ bzw. Trassenvertrag Die DB InfraGO AG stellt sicher, dass eine Stornierung binnen der Frist von 3 Arbeitstagen nach Erhalt\r\n\r\nablehnen, dann sorgt DB InfraGO für einer netzausgelösten Änderung für den Kunden kostenlos bleibt.\r\n\r\nKostenlose Stornierung. Wird die Bautrassen, die innerhalb von drei Tagen storniert werden, zählen nicht in die Stornoquote.\r\n\r\nwird auch aus Stornierungsquote\r\n\r\nrausgenommen.\r\n\r\nDB InfraGO AG | Follow-up: TAF/TAP TSI-Dialog am 22.04.2026 ​ 2",225,"{\"canonical_url\":null,\"normalized_sha256\":\"0629a1f4df3af0861459be12aad8be05d74e88666f80dab4353848fabc5e63e7\",\"page\":2,\"source_id\":\"src_8b2e5ffa1f464bee18cf\",\"source_sha256\":\"abacab26d0837e86a436bb01429fc0431caffc556ac17a01fa1a0bd5ac1a0703\",\"source_version_id\":\"sv_abacab26d0837e86a436bb01\"}","486bb799fe9f8e4bb7963b4fd96156cb99e86e821fafd8d672c9637fab723fe9"],["chunk_4c9b3f73c970920cdf0872a0","wiki/sources/taf-tap-tsi-dialog-22-april-2026-antworten-und-offene-punkte-data.md",2,"Seite 3","Offene Punkte und Antworten (2/5)\r\n\r\nFrage Antwort DB InfraGO\r\n\r\nMuss man fest entscheiden, ob Stellungnahmen zu GPE können sowohl über die KOMBau als auch das Common Interface abgegeben\r\n\r\nStellungnahmen zum GPE über werden, jedoch wird nur die zuletzt abgegebene Stellungnahme verwendet.\r\n\r\nKOMBau oder CI erfolgen, oder kann Das GPE selbst sowie GPEnS, FPE und NAÄ werden sowohl in der KOMBau angezeigt als auch über\r\n\r\nman das auch parallel nutzen? das Common Interface bereitgestellt.\r\n\r\nVerhält sich dies anders als pathOS und Beim Trassenmanagement (Bestellung, Änderung, Stornierung) muss jeder einzelne Vorgang in dem\r\n\r\ndas CI bei der Trassenanmeldung? gewählten Kanal – via Common Interface CI oder pathOS Webportal – bis zum Abschluss des\r\n\r\nProzesses bearbeitet werden. D.h. die Reaktion auf ein Angebot muss im gleichen Kanal erfolgen wie\r\n\r\ndie Trassenanmeldung.\r\n\r\nDas ist ein anderes Verhalten als die Abgabe von Stellungnahmen zum GPE.\r\n\r\nGerne kommen wir dem Wunsch aus dem Termin nach und bringen dieses Thema im nächsten TTT-\r\n\r\nDialog nochmals im Detail mit.\r\n\r\nDB InfraGO AG | Follow-up: TAF/TAP TSI-Dialog am 22.04.2026 ​ 3",172,"{\"canonical_url\":null,\"normalized_sha256\":\"0629a1f4df3af0861459be12aad8be05d74e88666f80dab4353848fabc5e63e7\",\"page\":3,\"source_id\":\"src_8b2e5ffa1f464bee18cf\",\"source_sha256\":\"abacab26d0837e86a436bb01429fc0431caffc556ac17a01fa1a0bd5ac1a0703\",\"source_version_id\":\"sv_abacab26d0837e86a436bb01\"}","dcc3ca2110e320b3eaf093de744ec29c23bc192d9f7adfed2d418f3c7271ad9e"],["chunk_1f8265c94c9d927544c6aa02","wiki/sources/taf-tap-tsi-dialog-22-april-2026-antworten-und-offene-punkte-data.md",3,"Seite 4","Offene Punkte und Antworten (3/5)\r\n\r\nFrage Antwort DB InfraGO\r\n\r\nWenn aufgrund einer NAÄ nicht nur die Ziffer 5.6.4 der INB:\r\n\r\ndirekt betroffene Trasse storniert wird \"Einschränkungen, die aus der Sphäre des Infrastrukturbetreibers stammen, erfolgt abweichend von\r\n\r\nsondern auch eine abhängige Trasse, den folgenden Regelungen keine Bepreisung der dadurch verursachten Stornierung sowie keine\r\n\r\nweil z.B. der Umlauf nicht mehr Bepreisung der Stornierung eines davon betroffenen Umlaufs.\"\r\n\r\nmöglich ist, ist dann diese Stornierung\r\n\r\nebenfalls kostenfrei?\r\n\r\nVorhin gab es eine Frage zu Ziffer 5.6.2.2 der INB:\r\n\r\nStornierungen von nicht Für Zugtrassen, die aufgrund nicht im ENV berücksichtigter Baumaßnahmen zusätzlich notwendig\r\n\r\nbaubetroffenen Trassen, die werden, ist kein Trassenentgelt zu entrichten. Zu diesen Zugtrassen zählen u. a. Zu- und\r\n\r\nerforderlich werden, wenn Umläufe Abführungsfahrten zu einem Schienenersatzverkehr, Drehfahrten aufgrund baubedingter\r\n\r\naufgrund von FPE/NAÄ, die nicht zu Einschränkungen, Zu- und Abführungsfahrten zu einer anderen als der gewöhnlichen Abstell- oder\r\n\r\nden Stellungnahmen der EVU passen, Tankanlage, Zu- und Abführungsfahrten von Triebfahrzeugen oder zusätzliche Verkehre aufgrund\r\n\r\nnicht mehr aufgehen. Folge solcher einer Änderung der Zugcharakteristik (z. B. Ablasten aufgrund geringerer Grenzlast einer\r\n\r\nAbweichungen könnten aber auch Umleitungsstrecke). Die genauen Voraussetzungen entnehmen Sie bitte der Ziffer 5.6.2.2 der INB.\r\n\r\nBestellungen weiterer Trassen sein.\r\n\r\nWie wird hier sichergestellt, dass dies\r\n\r\nfür EVUs kostenneutral erfolgt?\r\n\r\nDB InfraGO AG | Follow-up: TAF/TAP TSI-Dialog am 22.04.2026 ​ 4",215,"{\"canonical_url\":null,\"normalized_sha256\":\"0629a1f4df3af0861459be12aad8be05d74e88666f80dab4353848fabc5e63e7\",\"page\":4,\"source_id\":\"src_8b2e5ffa1f464bee18cf\",\"source_sha256\":\"abacab26d0837e86a436bb01429fc0431caffc556ac17a01fa1a0bd5ac1a0703\",\"source_version_id\":\"sv_abacab26d0837e86a436bb01\"}","3452740402d995e8000f3e3f2dd4c08a4a379a264fb03f3755d05ce5779b6d59"],["chunk_23b4b5551b060378f8164c02","wiki/sources/taf-tap-tsi-dialog-22-april-2026-antworten-und-offene-punkte-data.md",4,"Seite 5","Offene Punkte und Antworten (4/5)\r\n\r\nFrage Antwort DB InfraGO\r\n\r\nDer Prozess zum NAÄ ist aktuell – und Es liegt aktuell eine Testeinschränkung vor, weil die automatische Annahme des NAÄ noch nicht\r\n\r\nseit längerem – nicht vollständig korrekt implementiert ist.\r\n\r\ntestbar, da die automatische Annahme Die Lieferung in den Kundentest ist für 29. Juli vorgesehen.\r\n\r\nnicht funktioniert.\r\n\r\nDB InfraGO wird diese Lücke vor der Versendung der ersten NAÄ schließen. Es ist nicht notwendig\r\n\r\nBis wann wird der blockierende Fehler sich auf Seiten der EVU auf alternative Prozesse einzustellen.\r\n\r\nbehoben und wie stabil ist die Planung?\r\n\r\nDB InfraGO AG | Follow-up: TAF/TAP TSI-Dialog am 22.04.2026 ​ 5",105,"{\"canonical_url\":null,\"normalized_sha256\":\"0629a1f4df3af0861459be12aad8be05d74e88666f80dab4353848fabc5e63e7\",\"page\":5,\"source_id\":\"src_8b2e5ffa1f464bee18cf\",\"source_sha256\":\"abacab26d0837e86a436bb01429fc0431caffc556ac17a01fa1a0bd5ac1a0703\",\"source_version_id\":\"sv_abacab26d0837e86a436bb01\"}","ba47d7624d49b021a9c5be2693592cde15e29ebef1feb427f218927ec51fbb75"],["chunk_dee7a47548a07192f9047619","wiki/sources/taf-tap-tsi-dialog-22-april-2026-antworten-und-offene-punkte-data.md",5,"Seite 6","Offene Punkte und Antworten (5/5)\r\n\r\nFrage Antwort DB InfraGO\r\n\r\nOh, das ist ein guter Punkt, der Zug Im Fall eines mittigen Teilausfalls (Schienenersatzverkehr) muss das EVU eine Änderungsbestellung\r\n\r\nwürde ja ggf. im Planungssystem des vornehmen, um dem zweiten Trassenteil eine neue ReferenceTrainID zu geben. Dabei dürfen keine\r\n\r\nEVU bereits geändert sein! Dann anderen Änderungen vorgenommen werden.\r\n\r\nwerden zwangsweise neue Daten\r\n\r\nübertragen. Muss man sich den also Umgang mit geändertem Fremdinfrastrukturanteil:\r\n\r\n\"wegspeichern\" unverändert? Und was Geänderte/vertragsgeschlossene Anteile auf Fremdnetzen dürfen „korrekt“ angegeben werden. Diese\r\n\r\nist mit Änderungen auf haben auf unsere Konstruktion und die Durchführung der Änderungsbestellung keine Auswirkung und\r\n\r\nFremdinfrastruktur, die halt auch in der sind genauso in unserem Angebot enthalten. Etwaige Änderungen an diesen Anteilen in der\r\n\r\nTrasse liegen? Zwischenzeit werden nicht berücksichtigt.\r\n\r\nDB InfraGO AG | Follow-up: TAF/TAP TSI-Dialog am 22.04.2026 ​ 6",135,"{\"canonical_url\":null,\"normalized_sha256\":\"0629a1f4df3af0861459be12aad8be05d74e88666f80dab4353848fabc5e63e7\",\"page\":6,\"source_id\":\"src_8b2e5ffa1f464bee18cf\",\"source_sha256\":\"abacab26d0837e86a436bb01429fc0431caffc556ac17a01fa1a0bd5ac1a0703\",\"source_version_id\":\"sv_abacab26d0837e86a436bb01\"}","406421042db260046663daa5894c31ab20341d04f03f73fbbf471615826cfd48"],["chunk_373c26018d8d417f28f509b2","wiki/sources/taf-tap-tsi-dialog-22-april-2026-terminunterlage-data.md",0,"Seite 1","14. TAF/TAP TSI-Dialog der DB InfraGO\r\n\r\nAustausch mit dem Markt\r\n\r\n22.04.2026 – virtuell",13,"{\"canonical_url\":null,\"normalized_sha256\":\"c50ac369395895c1a036e9126326a664c342f6e4f62c0a31cd4c5283b1dedba8\",\"page\":1,\"source_id\":\"src_ea6d92cb2a3f2e4138ef\",\"source_sha256\":\"0c0b08c0adcc9c32c1dcad55bd94be9808b743faa7245e80d1509de084e82df1\",\"source_version_id\":\"sv_0c0b08c0adcc9c32c1dcad55\"}","3f18cdd8c27b451c9a1afd0a9cbafe58e6e9c8506e3b15ce57ea69a3b7a48947"],["chunk_da4750a857a179d89ded1de7","wiki/sources/taf-tap-tsi-dialog-22-april-2026-terminunterlage-data.md",1,"Seite 2","Agenda\r\n\r\n1. Begrüßung\r\n\r\n2. Status TTT Einführung\r\n\r\n3. Update KOMBau zur 4. Konsultationsphase\r\n\r\n4. Umgang mit mittigem Teilausfall (SEV)\r\n\r\n5. Fragen & Antworten\r\n\r\n6. Zum Nachlesen: Nächste Termine\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 22.04.2026 2",37,"{\"canonical_url\":null,\"normalized_sha256\":\"c50ac369395895c1a036e9126326a664c342f6e4f62c0a31cd4c5283b1dedba8\",\"page\":2,\"source_id\":\"src_ea6d92cb2a3f2e4138ef\",\"source_sha256\":\"0c0b08c0adcc9c32c1dcad55bd94be9808b743faa7245e80d1509de084e82df1\",\"source_version_id\":\"sv_0c0b08c0adcc9c32c1dcad55\"}","05cd2001e2f63ee9ee9698f19ee96a13215f1f71e523dc627489d444e5c0b0a2"],["chunk_70062a409f557c42fbecba66","wiki/sources/taf-tap-tsi-dialog-22-april-2026-terminunterlage-data.md",2,"Seite 3","Wir wollen mit Ihnen in den Dialog treten – Welche Fragen\r\n\r\nhaben Sie? Schreiben Sie diese bitte in den Chat\r\n\r\nSo können Sie eine Frage platzieren:\r\n\r\nBitte wählen Sie in MS Teams in der Menüleiste\r\n\r\ndas Icon „Chat“ aus und schreiben Ihre Frage\r\n\r\nin das sich öffnende Fenster.\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 22.04.2026 3",57,"{\"canonical_url\":null,\"normalized_sha256\":\"c50ac369395895c1a036e9126326a664c342f6e4f62c0a31cd4c5283b1dedba8\",\"page\":3,\"source_id\":\"src_ea6d92cb2a3f2e4138ef\",\"source_sha256\":\"0c0b08c0adcc9c32c1dcad55bd94be9808b743faa7245e80d1509de084e82df1\",\"source_version_id\":\"sv_0c0b08c0adcc9c32c1dcad55\"}","223e12fd99596d11548e278e4a5c34207a9ed7bdd9f71058351019167a891bba"],["chunk_5fc4363f6793361d6f98f153","wiki/sources/taf-tap-tsi-dialog-22-april-2026-terminunterlage-data.md",3,"Seite 4","2. Status TTT Einführung\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 22.04.2026 4",13,"{\"canonical_url\":null,\"normalized_sha256\":\"c50ac369395895c1a036e9126326a664c342f6e4f62c0a31cd4c5283b1dedba8\",\"page\":4,\"source_id\":\"src_ea6d92cb2a3f2e4138ef\",\"source_sha256\":\"0c0b08c0adcc9c32c1dcad55bd94be9808b743faa7245e80d1509de084e82df1\",\"source_version_id\":\"sv_0c0b08c0adcc9c32c1dcad55\"}","4f657387be5ada7391840584d28bee027e025375bcbb7e7f89f160a3af3b979a"],["chunk_9bc8c9cb2e6e89d590a44bc6","wiki/sources/taf-tap-tsi-dialog-22-april-2026-terminunterlage-data.md",4,"Seite 5","Zentraler Meilenstein für TAF/TAP TSI Einführung erreicht:\r\n\r\nErfolgreicher Abschluss der Trassenanmeldung für NEP1\r\n\r\n✓ Alle EVU, die im NEP 1 Trassen anmelden wollten, haben das auch getan1\r\n\r\nVorbereitungen auf Seiten der EVU und Bereitstellung auf Seiten der IT-Dienstleister war\r\n\r\nerfolgreich und der anspruchsvolle Zeitplan wurde von den Beteiligten mit umgesetzt.\r\n\r\n✓ 96.923 Trassenanmeldungen wurden erfolgreich über pathOS Webportal und CI\r\n\r\ndurchgeführt.\r\n\r\n✓ Anmeldung von 500 zusätzlichen internationalen Trassen über PCS (noch ohne PAP-\r\n\r\nTrassen).\r\n\r\n✓ Rückmeldungen von 4 EVU zu wenigen unvollständigen Trassenbestellungen sind großteils\r\n\r\nbereits geklärt und korrigiert.\r\n\r\n(1) Nach Stand der Information an DB InfraGO vom 20.04.2026.\r\n\r\n(2) In der technischen Auswertung werden Änderungsbestellungen vor Anmeldeschluss und die zugehörige Erstanmeldung jeweils einmal gezählt.\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 22.04.2026 5",124,"{\"canonical_url\":null,\"normalized_sha256\":\"c50ac369395895c1a036e9126326a664c342f6e4f62c0a31cd4c5283b1dedba8\",\"page\":5,\"source_id\":\"src_ea6d92cb2a3f2e4138ef\",\"source_sha256\":\"0c0b08c0adcc9c32c1dcad55bd94be9808b743faa7245e80d1509de084e82df1\",\"source_version_id\":\"sv_0c0b08c0adcc9c32c1dcad55\"}","9d2379edd714aaf84b66519e9dee7c22658c009ee61fac13199610f6ef436fa9"],["chunk_fcce9c53362f2fd3ac401f1d","wiki/sources/taf-tap-tsi-dialog-22-april-2026-terminunterlage-data.md",5,"Seite 6","In den nächsten Wochen rückt der Kundentest für die späteren\r\n\r\nFahrplanphasen verstärkt in den Fokus\r\n\r\nWeitere Ergebnisse seit letztem TTT-Dialog\r\n\r\n✓ Markttest TTT mit Identifiern im Betrieb zum 14.04. gestartet\r\n\r\n✓ Plausibilisierung der Trassenanmeldungen für NEP 1 gestartet\r\n\r\n✓ Netzfahrplanerstellung gestartet\r\n\r\nNächste Schritte\r\n\r\n• Markttests Trassenanmeldung und Defect-Behebung kontinuierlich fortsetzen\r\n\r\n• 04.05.2026: Lieferung GelV 2 in den Markttest (u.a. Anmeldung mit Annahmeverzicht)\r\n\r\n• 15.05.2026: Lieferung ujBau 3 in den Markttest (Erweiterung Netzausgelöste Änderungen inkl.\r\n\r\nmittiger Teilausfall\r\n\r\n• 20.05.2026: EVU-Informationsveranstaltung unterjähriger Bau\r\n\r\n• 21.05.2026: 15. TTT-Dialog\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 22.04.2026 6",94,"{\"canonical_url\":null,\"normalized_sha256\":\"c50ac369395895c1a036e9126326a664c342f6e4f62c0a31cd4c5283b1dedba8\",\"page\":6,\"source_id\":\"src_ea6d92cb2a3f2e4138ef\",\"source_sha256\":\"0c0b08c0adcc9c32c1dcad55bd94be9808b743faa7245e80d1509de084e82df1\",\"source_version_id\":\"sv_0c0b08c0adcc9c32c1dcad55\"}","2fc3aa4eee712bcf8abfa8f222dbe50fdeef35672f4e55287cc0c87899dd648e"],["chunk_07d560fc6e96a1f91ce5733a","wiki/sources/taf-tap-tsi-dialog-22-april-2026-terminunterlage-data.md",6,"Seite 7","Für die Trassenanmeldung im Gelegenheitsverkehr können die\r\n\r\nEVU die Vorbereitung nach ihrem Bedarf starten\r\n\r\nInformationen & Schulungen Onboarding Schnittstelle zur\r\n\r\nTrassenanmeldung\r\n\r\n• Web-based-Trainings (WBT) für Grundlagen zur • Das Onboarding für die Nutzung der Schnittstelle\r\n\r\nBedienung von pathOS sowie 2 komplexen zur Trassenanmeldung (Common Interface) für\r\n\r\nEmpfehlung:\r\n\r\nAnwendungsfällen (SGV und SPV) den GelV wird von DB InfraGO bereits unterstützt.\r\n\r\nStarten Sie\r\n\r\nfrühzeitig, um auf\r\n\r\n• EVU können das Onboarding mittels der\r\n\r\n• Erklärvideos zur Vertiefung einzelner\r\n\r\nunerwartete\r\n\r\nbekannten Formulare starten.\r\n\r\nAnwendungsfälle\r\n\r\nHindernisse\r\n\r\n• Die Anmeldung muss 4 Wochen vor der\r\n\r\n• Handbuch mit umfangreichem Detailwissen reagieren zu\r\n\r\nangestrebten produktiven Nutzung der\r\n\r\nkönnen.\r\n\r\n• Vertiefungsworkshops: Durchgehen von Schnittstelle erfolgen.\r\n\r\nAnwendungsbeispielen gemeinsam mit → Die Erfahrung zeigt, dass häufig noch Hürden\r\n\r\nExperten, für den gesamten Jahresverlauf überwunden werden müssen z.B. Firewallgeplante 3-stündige Vertiefungsworkshop Freischaltungen.\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 22.04.2026 7",141,"{\"canonical_url\":null,\"normalized_sha256\":\"c50ac369395895c1a036e9126326a664c342f6e4f62c0a31cd4c5283b1dedba8\",\"page\":7,\"source_id\":\"src_ea6d92cb2a3f2e4138ef\",\"source_sha256\":\"0c0b08c0adcc9c32c1dcad55bd94be9808b743faa7245e80d1509de084e82df1\",\"source_version_id\":\"sv_0c0b08c0adcc9c32c1dcad55\"}","dbb5feccb25014f445136f04a2385b628a66acad323cd1e860327dfbbfa3bea2"],["chunk_e82452433dec1e62e9cf78b6","wiki/sources/taf-tap-tsi-dialog-22-april-2026-terminunterlage-data.md",7,"Seite 8","3. Update KOMBau zur 4.\r\n\r\nKonsultationsphase\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 22.04.2026 8",15,"{\"canonical_url\":null,\"normalized_sha256\":\"c50ac369395895c1a036e9126326a664c342f6e4f62c0a31cd4c5283b1dedba8\",\"page\":8,\"source_id\":\"src_ea6d92cb2a3f2e4138ef\",\"source_sha256\":\"0c0b08c0adcc9c32c1dcad55bd94be9808b743faa7245e80d1509de084e82df1\",\"source_version_id\":\"sv_0c0b08c0adcc9c32c1dcad55\"}","93d252fddc8a9a8907b1573c5f75a7657eb5e8de0d8d4f2ef12e6be445efb6a7"],["chunk_338ec7df395468d963a31035","wiki/sources/taf-tap-tsi-dialog-22-april-2026-terminunterlage-data.md",8,"Seite 9","Updates zu Exporten, Kundentests und Massenverarbeitung\r\n\r\nExporte der Planungsergebnisse der 4. Konsultationsphase:\r\n\r\n• Zusätzlich zu den Exporten über die TTT-Schnittstelle soll ein möglichst einfacher aber\r\n\r\nlesbarer Export der Planungsergebnisse (GPE, GPEnS und FPE) zu baubedingt geänderten\r\n\r\nTrassen ermöglicht werden, damit die EVU diese für ihre Zwecke weiterverwenden können.\r\n\r\n→ wir ermöglichen den Export der PE aus der jeweiligen Detailansicht\r\n\r\n→ geplanter Umsetzungszeitpunkt: bis 30. September 2026\r\n\r\nKundentesttage für die KOMBau Frontend 4. Konsultationsphase (GPE-FPE):\r\n\r\n• Termine am 11., 13., und 18.05.2026\r\n\r\n• Die verfügbaren Termine und Teilnehmerplätze sind limitiert, daher erfolgt die Vergabe\r\n\r\ngrundsätzlich nach dem Prinzip „first come, first served“. Wir achten aber darauf, dass die\r\n\r\neinzelnen Verkehrsarten repräsentativ abgedeckt sind.\r\n\r\n• Die Kundeninformation mit den Anmeldeinformationen wird zeitnah erfolgen\r\n\r\nGPE – Grobplanungsergebnis; GPEnS – Grobplanungsergebnis nach Stellungnahme: FPE – Feinplanungsergebnis gemäß Annex VII\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 22.04.2026 9",144,"{\"canonical_url\":null,\"normalized_sha256\":\"c50ac369395895c1a036e9126326a664c342f6e4f62c0a31cd4c5283b1dedba8\",\"page\":9,\"source_id\":\"src_ea6d92cb2a3f2e4138ef\",\"source_sha256\":\"0c0b08c0adcc9c32c1dcad55bd94be9808b743faa7245e80d1509de084e82df1\",\"source_version_id\":\"sv_0c0b08c0adcc9c32c1dcad55\"}","0a7baa96c2de788b7f30c46a7706e6071bd9e75ac0b89ab91428072bb4b5230b"],["chunk_614a746bd7fbba5cf20b3419","wiki/sources/taf-tap-tsi-dialog-22-april-2026-terminunterlage-data.md",9,"Seite 10","Updates zu Exporten, Kundentests und Massenverarbeitung\r\n\r\nMassenverarbeitung – Mehrfachstellungnahmen:\r\n\r\n• Das Konzept zur Mehrfachstellungnahme wurde finalisiert und mit den Teilnehmern der\r\n\r\nMasterClass am 17.04.26 validiert\r\n\r\n• Die Entwicklung der Funktionalität wird nach dem\r\n\r\naktuellen Planungsstand im Juni starten\r\n\r\n→ genauere Infos zur Umsetzung können wir zum Konzept\r\n\r\nnächsten TTT-Dialog liefern\r\n\r\n→ Das Bild zeigt ein Beispiel aus dem Konzept:\r\n\r\n- Auswahl der GPE, auf welche eine vorhandene\r\n\r\nStellungnahme übertragen werden soll\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 22.04.2026 10",80,"{\"canonical_url\":null,\"normalized_sha256\":\"c50ac369395895c1a036e9126326a664c342f6e4f62c0a31cd4c5283b1dedba8\",\"page\":10,\"source_id\":\"src_ea6d92cb2a3f2e4138ef\",\"source_sha256\":\"0c0b08c0adcc9c32c1dcad55bd94be9808b743faa7245e80d1509de084e82df1\",\"source_version_id\":\"sv_0c0b08c0adcc9c32c1dcad55\"}","ef257b2cc626f0b57a66574e04d16ab58a13d73312c356268ac44d8068d35d2b"],["chunk_d208decbb7c65abfd099ff04","wiki/sources/taf-tap-tsi-dialog-22-april-2026-terminunterlage-data.md",10,"Seite 11","Update zur Bedienungsanleitung\r\n\r\n• Die Bedienungsanleitung der KOMBau für die 1.-3. Konsultationsphase wurde überarbeitet und ist auf der\r\n\r\nKOMBau-Seite verfügbar.\r\n\r\n• Der aktuell in der Bedienungsanleitung enthaltene Ausblick auf die Inhalte für die 4. Konsultationsphase wird\r\n\r\nfür die Inbetriebnahme und Nutzung der neuen Funktionen kontinuierlich ergänzt.\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 22.04.2026 11",55,"{\"canonical_url\":null,\"normalized_sha256\":\"c50ac369395895c1a036e9126326a664c342f6e4f62c0a31cd4c5283b1dedba8\",\"page\":11,\"source_id\":\"src_ea6d92cb2a3f2e4138ef\",\"source_sha256\":\"0c0b08c0adcc9c32c1dcad55bd94be9808b743faa7245e80d1509de084e82df1\",\"source_version_id\":\"sv_0c0b08c0adcc9c32c1dcad55\"}","13582e3af790273f07e3d87e61d79a6ca38e0e62c6b90c77b8ed10d30be18407"],["chunk_0c3633ffb0d954e73373b74f","wiki/sources/taf-tap-tsi-dialog-22-april-2026-terminunterlage-data.md",11,"Seite 12","4. Umgang mit mittigem Teilausfall (SEV)\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 22.04.2026 12",15,"{\"canonical_url\":null,\"normalized_sha256\":\"c50ac369395895c1a036e9126326a664c342f6e4f62c0a31cd4c5283b1dedba8\",\"page\":12,\"source_id\":\"src_ea6d92cb2a3f2e4138ef\",\"source_sha256\":\"0c0b08c0adcc9c32c1dcad55bd94be9808b743faa7245e80d1509de084e82df1\",\"source_version_id\":\"sv_0c0b08c0adcc9c32c1dcad55\"}","62d479b6b8c740b2c0e20cbaa37cc85109790a8cb65dcf7e6533cdb55158f46a"],["chunk_f3bde48ceee481763efcd43d","wiki/sources/taf-tap-tsi-dialog-22-april-2026-terminunterlage-data.md",12,"Seite 13","Automatische Zustimmung zu NAÄ - Prozesserläuterung\r\n\r\n• Ablauf des fachlichen Prozesses\r\n\r\n• Alle NAÄ gehen ohne Möglichkeit zur expliziten Annahme/Ablehnung in einen\r\n\r\nVertragsgeschlossenen Zustand über (0s Annahmefrist). Der restliche Ablauf bleibt wie gehabt.\r\n\r\n• Diese Angebote sind bereits mit den Bestellern abgestimmt und entsprechen inhaltlich dem\r\n\r\nFeinplanungsergebnis (FPE)\r\n\r\n• Alle NAÄ können innerhalb von drei Tagen kostenfrei storniert werden– dies gilt bis zum\r\n\r\nvollständigen Abschluss des Prozesses. Für nachfolgende Vorgänge beginnt der Prozess erneut;\r\n\r\nder initiale Kanal bestimmt dabei den konkreten Ablauf.\r\n\r\n• Was heißt das für den Kanalzwang?\r\n\r\n• Der Fachprozess geht vom Versand der NAÄ bis zum Vertragsschluss. Da eine automatische\r\n\r\nAnnahme vorgenommen wird, ist der Vertragsschluss automatisch ohne Einfluss der\r\n\r\nZugangsberechtigten.\r\n\r\nWenn der Organisation Code des Responsible Applicant im CI konfiguriert ist, sendet pathOS die\r\n\r\nNAÄ und die nachfolgenden Nachrichten an das CI und stellt den neuen Vertrag im Portal dar.\r\n\r\nOb der Kunde auf die Nachrichten im CI mit einer RCM reagiert prüfen wir nicht.\r\n\r\n• Sofern der Kunde, nachdem wir ihm einen neuen Vertrag erzeugt haben, diesen ändern/stornieren\r\n\r\nwill, handelt es sich um einen neuen Prozess. Der Kunde kann daher entscheiden, ob er diesen im\r\n\r\npathOS Webportal oder über das CI initiieren möchte, ist danach aber an diesen Kanal gebunden\r\n\r\nbis erneut ein Vertrag geschlossen ist.\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 22.04.2026 13",220,"{\"canonical_url\":null,\"normalized_sha256\":\"c50ac369395895c1a036e9126326a664c342f6e4f62c0a31cd4c5283b1dedba8\",\"page\":13,\"source_id\":\"src_ea6d92cb2a3f2e4138ef\",\"source_sha256\":\"0c0b08c0adcc9c32c1dcad55bd94be9808b743faa7245e80d1509de084e82df1\",\"source_version_id\":\"sv_0c0b08c0adcc9c32c1dcad55\"}","f470653fe30322d70ebdf2e0bfe1ef1d67095b1e848577a8520a1dd0a052d9c2"],["chunk_2f1701e5582f5946c3cc8b0f","wiki/sources/taf-tap-tsi-dialog-22-april-2026-terminunterlage-data.md",13,"Seite 14","Update zum mittigen Teilausfall\r\n\r\n• Folgeaktivität vom TTT-Dialog vom 09.03.2026\r\n\r\n• Nach Erhalt der Angebote ist durch den Kunden eine Folgeaktivität\r\n\r\nauszuführen:\r\n\r\n− Änderungsbestellung unter Verwendung des RoR-Codes 1011\r\n\r\n− Hinweis: Im Fahrplan 2027 ist die alternative Verwendung der\r\n\r\nUpdateLinkMessage nicht möglich\r\n\r\nVorgehen bei der Änderungsbestellung\r\n\r\n• Es wird empfohlen, bei der Trasse die RefTrainID zu ändern, die die neue OTN (Zugnummer) erhalten hat\r\n\r\n• Bei der Änderung sind in den PlannedTransportID die neue RefTrainID und eine neue PRID zu verwenden\r\n\r\n• Die Angabe der aktuell verwendeten RefTrainID und PathID ist in den RelatedTransportID unter Mitführung des\r\n\r\nROR-Codes 1011 anzugeben\r\n\r\n• Darüber hinaus dürfen keinerlei Änderungen an der Trasse vorgenommen werden\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 22.04.2026 14",120,"{\"canonical_url\":null,\"normalized_sha256\":\"c50ac369395895c1a036e9126326a664c342f6e4f62c0a31cd4c5283b1dedba8\",\"page\":14,\"source_id\":\"src_ea6d92cb2a3f2e4138ef\",\"source_sha256\":\"0c0b08c0adcc9c32c1dcad55bd94be9808b743faa7245e80d1509de084e82df1\",\"source_version_id\":\"sv_0c0b08c0adcc9c32c1dcad55\"}","a05673bb53dc944d539f4494141fb66e0773c08299d340ab94920d136f29e074"],["chunk_6f15a8569091a12ba33ebe36","wiki/sources/taf-tap-tsi-dialog-22-april-2026-terminunterlage-data.md",14,"Seite 15","5. Fragen & Antworten\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 22.04.2026 15",13,"{\"canonical_url\":null,\"normalized_sha256\":\"c50ac369395895c1a036e9126326a664c342f6e4f62c0a31cd4c5283b1dedba8\",\"page\":15,\"source_id\":\"src_ea6d92cb2a3f2e4138ef\",\"source_sha256\":\"0c0b08c0adcc9c32c1dcad55bd94be9808b743faa7245e80d1509de084e82df1\",\"source_version_id\":\"sv_0c0b08c0adcc9c32c1dcad55\"}","3b55da57c01262bcdea0144f1f2ef429448da6e01c94daf478f3f350d64edc0e"]]');
