INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_1c99621d0af4b004b5cb9016","wiki/sources/taf-tap-tsi-dialog-22-april-2026-terminunterlage-data.md",15,"Seite 16","Zeit für Ihre Fragen!\r\n\r\nGerne beantworten wir Ihnen\r\n\r\nIhre Fragen direkt im Termin.\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 22.04.2026 16",22,"{\"canonical_url\":null,\"normalized_sha256\":\"c50ac369395895c1a036e9126326a664c342f6e4f62c0a31cd4c5283b1dedba8\",\"page\":16,\"source_id\":\"src_ea6d92cb2a3f2e4138ef\",\"source_sha256\":\"0c0b08c0adcc9c32c1dcad55bd94be9808b743faa7245e80d1509de084e82df1\",\"source_version_id\":\"sv_0c0b08c0adcc9c32c1dcad55\"}","1c0432d405b3ec34df5897ef47f3aaa6c3bbe32bbc552d6fbbc5f22672aa8b28"],["chunk_4798964ddf0a15a67b042294","wiki/sources/taf-tap-tsi-dialog-22-april-2026-terminunterlage-data.md",16,"Seite 17","6. Zum Nachlesen:\r\n\r\nNächste Termine\r\n\r\nAlle Informationen immer aktuell unter:\r\n\r\nwww.dbinfrago.com/taf-tap-tsi\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 22.04.2026 17",20,"{\"canonical_url\":null,\"normalized_sha256\":\"c50ac369395895c1a036e9126326a664c342f6e4f62c0a31cd4c5283b1dedba8\",\"page\":17,\"source_id\":\"src_ea6d92cb2a3f2e4138ef\",\"source_sha256\":\"0c0b08c0adcc9c32c1dcad55bd94be9808b743faa7245e80d1509de084e82df1\",\"source_version_id\":\"sv_0c0b08c0adcc9c32c1dcad55\"}","295d2804dd7343d98395ae3a7c4da8c40e3b737ebf92f0023304052b844af3ce"],["chunk_cc80022f624ed1fcca047ab3","wiki/sources/taf-tap-tsi-dialog-22-april-2026-terminunterlage-data.md",17,"Seite 18","Übersicht TAF/TAP TSI-Kommunikation\r\n\r\nArbeitsweise (A)/Turnus (T)\r\n\r\nTeilnehmer: Management & Experten aller EVU u. deren IT-Partner A: online\r\n\r\nTAF/TAP TSI\r\n\r\n1 Ziel: Überblick für GF-Ebene, allg. Infos (Betrieb + Fahrplan), zzgl. Vertiefung T: ca. monatlich\r\n\r\n-Dialog\r\n\r\naktueller Fokusthemen in Entwicklung/Testing Nächster Termin: 21.05.\r\n\r\nSprechstunde Teilnehmer: Alle künftigen Schnittstellenpartner (EVU, ZB) A: online\r\n\r\n2 Onboarding für Ziel: Informationen und Sprechstunde zum Onboarding der SST-Partner inkl. T: mittwochs - Details auf pathOS-\r\n\r\nSchnittstellenpartner Vorbereitung und Begleitung der Tests und Anbindung an die SST Homepage (unter Kapitel 3)\r\n\r\nTAF/TAP TSI –\r\n\r\nTeilnehmer: Schnittstellenpartner Fahrplan, die bereits mit uns testen A: online\r\n\r\n3 Schnittstellen-\r\n\r\nZiel: Aktuelle Informationen/Entwicklungen; Sprechstunde, Updates T: nach Bedarf\r\n\r\npartner Fahrplan\r\n\r\nTeilnehmer: Alle künftigen Anwendenden von pathOS A: online\r\n\r\npathOS -\r\n\r\n4 Ziel: Erklärung der Grundlagen und wesentlichen Inhalte von pathOS in einzelnen T: seit 23.10.2025 – Termine auf\r\n\r\nSchulungen\r\n\r\ne\r\n\r\ng Terminen. Regelmäßige Sprechstunde gestartet am 22.01.2026 pathOS-Homepage (unter Kapitel 2.4)\r\n\r\no\r\n\r\nla\r\n\r\ni D TAF/TAP TSI - Teilnehmer: Gesamtmarkt inkl. EIU A: online / in Präsenz\r\n\r\n5\r\n\r\nSektormeeting Ziel: nationale Spiegelgruppe TTT (Infos zu TTT, Verordnungen, ...) T: 4x jährlich, Nächster Termin: 11.06.\r\n\r\nA: in Präsenz\r\n\r\nRunder Tisch Bau Teilnehmer: 35 Mitglieder aus SPNV, SPV, SGV, BNetzA, Verbände, AT\r\n\r\n6 T: 4x p.a.\r\n\r\n(RTB) AG 3 Ziel: Beratung DB InfraGO bei Erarbeitung und Entwicklung für ujBau\r\n\r\nNächster Termin: 19.05.\r\n\r\nEVU-Informations- Teilnehmer: Gesamtmarkt\r\n\r\nA: online\r\n\r\n7 veranstaltung unter- Ziel: Information zum neuen unterjährigen Baufahrplanprozess mit neuen\r\n\r\nT: nach Bedarf, Nächster Termin: 20.05.",241,"{\"canonical_url\":null,\"normalized_sha256\":\"c50ac369395895c1a036e9126326a664c342f6e4f62c0a31cd4c5283b1dedba8\",\"page\":18,\"source_id\":\"src_ea6d92cb2a3f2e4138ef\",\"source_sha256\":\"0c0b08c0adcc9c32c1dcad55bd94be9808b743faa7245e80d1509de084e82df1\",\"source_version_id\":\"sv_0c0b08c0adcc9c32c1dcad55\"}","4e385ca2b42398365cc33e6743a6dfcb47710c66fe1abe446ce0a3e1e459e941"],["chunk_eb3f21aa949611eadd0ed344","wiki/sources/taf-tap-tsi-dialog-22-april-2026-terminunterlage-data.md",18,"Seite 18","jähriger Bau Fahrplanprodukten und der digitalen BauFplo\r\n\r\nTeilnehmer: Geschäftspartner mit G-INV A: online\r\n\r\n8 BDV\r\n\r\nZiel: Informationen, To-Dos vermitteln Nächster Termin: in Planung\r\n\r\no Homepage + Teilnehmer: für alle zugängliches Format, KI an Verteiler (inkl. IT-Partner, nicht alle EVU) A: Homepage\r\n\r\nf 9\r\n\r\nn Newsletter (KI) Ziel: aktuelle Informationen zum Nachlesen: Testing-Zugang, Ansprechpartner, Updates T: kontinuierlich\r\n\r\nI\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 22.04.2026 18",66,"{\"canonical_url\":null,\"normalized_sha256\":\"c50ac369395895c1a036e9126326a664c342f6e4f62c0a31cd4c5283b1dedba8\",\"page\":18,\"source_id\":\"src_ea6d92cb2a3f2e4138ef\",\"source_sha256\":\"0c0b08c0adcc9c32c1dcad55bd94be9808b743faa7245e80d1509de084e82df1\",\"source_version_id\":\"sv_0c0b08c0adcc9c32c1dcad55\"}","137f1645c2ac9010bb0a9d401724f3595e75316f62146318053b65cfaba470b4"],["chunk_4dd4dc3b9182e30900c89d18","wiki/sources/taf-tap-tsi-dialog-22-april-2026-terminunterlage-data.md",19,"Seite 19","Übersicht KOMBau-Kommunikation\r\n\r\nArbeitsweise (A)/Turnus (T)\r\n\r\nEinweisungstermin Teilnehmer: Gesamtmarkt inkl. EIU\r\n\r\nA: online\r\n\r\n1 4. Konsultationsphase Ziel: Teilnehmenden die Funktionen, Prozesse und Anwendungsmöglichkeiten der KOMBau\r\n\r\nT: 29.04.2026 + 07.05.2026\r\n\r\n(KP) Thema BKE/BAE in der 4. KP anschaulich zu vermitteln\r\n\r\nKundentesttage\r\n\r\nA: online*\r\n\r\nFrontend 4. Teilnehmer: Fachexperten und Anwender der EVU, Verkehrsarten repräsentativ abgedeckt\r\n\r\n2 T: 11.05.2026, 13.05.2026 +\r\n\r\nKonsultationsphase Ziel: Verproben des Workflows 4. KP GPE bis FPE und Feedback\r\n\r\n18.05.2026\r\n\r\n(GPE bis FPE)\r\n\r\nEinweisungstermin\r\n\r\nTeilnehmer: Gesamtmarkt A: online*\r\n\r\n4. Konsultationsphase\r\n\r\n3 Ziel: Teilnehmenden die Funktionen, Prozesse und Anwendungsmöglichkeiten der KOMBau T: 12.06.2026, 19.06.2026 +\r\n\r\n(KP) Thema GPE/\r\n\r\nin der 4. KP anschaulich zu vermitteln 26.06.2026\r\n\r\nGPEnS/FPE\r\n\r\n*Kund:inneninformationen und Einladungen werden in den kommenden Wochen versendet\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 22.04.2026 19",124,"{\"canonical_url\":null,\"normalized_sha256\":\"c50ac369395895c1a036e9126326a664c342f6e4f62c0a31cd4c5283b1dedba8\",\"page\":19,\"source_id\":\"src_ea6d92cb2a3f2e4138ef\",\"source_sha256\":\"0c0b08c0adcc9c32c1dcad55bd94be9808b743faa7245e80d1509de084e82df1\",\"source_version_id\":\"sv_0c0b08c0adcc9c32c1dcad55\"}","bce6934b81902ea7f9f3edc2bed548f44dcc041e3d5908f58b9b2c1b8a03d19f"],["chunk_284f726df854530f89639fdb","wiki/sources/taf-tap-tsi-dialog-24-juni-2026-antworten-und-offene-punkte-data.md",0,"Seite 1","Follow-up 16. TAF/TAP TSI-Dialog\r\n\r\nFragen und Antworten\r\n\r\nVersand im Nachgang\r\n\r\nDB InfraGO AG | Follow-up: TAF/TAP TSI-Dialog am 24.06.2026 ​ 1",21,"{\"canonical_url\":null,\"normalized_sha256\":\"bfceeb86fd85f2d56d54a4b09f7f4dfc7f1f8c0c096a927d009985bfe5c7c741\",\"page\":1,\"source_id\":\"src_fdf7048d9eb0f98e0a93\",\"source_sha256\":\"0194b5a78c0a2db74d1b0421bbf0f4070d7b1420f7d8f1d5f83ccf3fd16c8360\",\"source_version_id\":\"sv_0194b5a78c0a2db74d1b0421\"}","07b1e3931d2d281e5463f23d009cda4a0f3583902aa13065b0dedb8349b9a6cc"],["chunk_9653ccfc6b6ded8fd5046734","wiki/sources/taf-tap-tsi-dialog-24-juni-2026-antworten-und-offene-punkte-data.md",1,"Seite 2","Agenda\r\n\r\n1. Digitale Fahrplanmedien: ZLB-Einschränkung\r\n\r\n1. Digitale Fahrplanmedien: ZLB-Einschränkung\r\n\r\n2. Ersatzabstellung\r\n\r\n2. Ersatzabstellung\r\n\r\n3. Detaillierung 20h-Zug\r\n\r\n3. Detaillierung 20h-Zug\r\n\r\n4. Baubedingte Zusatzleistung\r\n\r\n4. Baubedingte Zusatzleistung\r\n\r\n5. Indirekt betroffene Züge bei Totalausfall\r\n\r\n5. Indirekt betroffene Züge bei Totalausfall\r\n\r\n6. NAÄ nicht aus unterjährigem Bau\r\n\r\n6. NAÄ nicht aus unterjährigem Bau\r\n\r\nDB InfraGO AG | Follow-up: TAF/TAP TSI-Dialog am 24.06.2026 ​ 2",60,"{\"canonical_url\":null,\"normalized_sha256\":\"bfceeb86fd85f2d56d54a4b09f7f4dfc7f1f8c0c096a927d009985bfe5c7c741\",\"page\":2,\"source_id\":\"src_fdf7048d9eb0f98e0a93\",\"source_sha256\":\"0194b5a78c0a2db74d1b0421bbf0f4070d7b1420f7d8f1d5f83ccf3fd16c8360\",\"source_version_id\":\"sv_0194b5a78c0a2db74d1b0421\"}","a91d2c620c5c28add5a7e978b3fd319433c9efd28ac3790399bd5ec8fdef3828"],["chunk_b37a10ecfebc3654e3eaf9ac","wiki/sources/taf-tap-tsi-dialog-24-juni-2026-antworten-und-offene-punkte-data.md",2,"Seite 3","1. Digitale Fahrplanmedien: ZLB-Einschränkung\r\n\r\nFrage Antwort DB InfraGO\r\n\r\nWarum erhalten einige EVU bei Bestellungen auf ZLB- Mit TTT gibt es kein separates Feld „EbuLa\" mehr. Die EbuLa-Ausrüstung wird über\r\n\r\nStrecken die Rückmeldung, dass ihre Trassen die Ausprägung „EFA\" (Wert 14) unter TrainCC_System (Zugsicherungssysteme)\r\n\r\nfälschlich mit EbuLa bestellt wurden? abgebildet.\r\n\r\nEinige EVU haben in ihrem Bestellsystem das Merkmal „EFA\" ausgewählt, weil ihre\r\n\r\nFahrzeuge über diese Eigenschaft verfügen – ohne zu erkennen, dass damit die\r\n\r\nEbuLa-Eigenschaft codiert wird. Auf ZLB-Strecken ist EbuLa nicht zulässig, weshalb\r\n\r\ndie Fahrplaner eine Beanstandung zurückmelden.\r\n\r\nDie Zuordnung von EbuLa zu „EFA\" unter den Zugsicherungssystemen ist eine\r\n\r\nnationale Festlegung von DB InfraGO, da die europäische TTT-Spezifikation keine\r\n\r\neigene Kategorie dafür vorsieht. EVU müssen bei Bestellungen auf ZLB-Strecken\r\n\r\nsicherstellen, dass „EFA\" nicht gesetzt wird.\r\n\r\nDB InfraGO AG | Follow-up: TAF/TAP TSI-Dialog am 24.06.2026 ​ 3",136,"{\"canonical_url\":null,\"normalized_sha256\":\"bfceeb86fd85f2d56d54a4b09f7f4dfc7f1f8c0c096a927d009985bfe5c7c741\",\"page\":3,\"source_id\":\"src_fdf7048d9eb0f98e0a93\",\"source_sha256\":\"0194b5a78c0a2db74d1b0421bbf0f4070d7b1420f7d8f1d5f83ccf3fd16c8360\",\"source_version_id\":\"sv_0194b5a78c0a2db74d1b0421\"}","7b2b1c8f76cfa7a27c6c74b297219a2ff46ccf1576f5939ff4415d4704e91930"],["chunk_0c3f0035a7160b5dca659a11","wiki/sources/taf-tap-tsi-dialog-24-juni-2026-antworten-und-offene-punkte-data.md",3,"Seite 4","2. Ersatzabstellung (1/2)\r\n\r\nFrage Antwort DB InfraGO AG\r\n\r\nWas mache ich, wenn ich keine Rückmeldung zu einer • Eine Verlängerung der Stellungnahmefrist ist nicht möglich. Sofern die\r\n\r\nErsatzabstellung bekomme und davon die Voraussetzungen für die Bereitstellung einer Ersatzabstellung erfüllt sind,\r\n\r\nStellungnahme auf ein GPE (Stichwort Abschnitt eines erhalten Sie in der Regel eine rechtzeitige Rückmeldung.\r\n\r\nTeilausfalls) abhängt? Bekomme ich eine • Voraussetzung hierfür ist, dass Sie über einen gültigen Einzelnutzungsvertrag\r\n\r\nVerlängerung der Stellungnahmefrist, wenn eine (ENV-SE) oder Mehrjahresvertrag (MV) für eine Serviceeinrichtung der DB\r\n\r\nStellungnahme aufgrund von ausstehenden Antworten InfraGO AG verfügen.\r\n\r\nder InfraGO nicht möglich ist?\r\n\r\nDie Verfügbarkeit von Ersatzabstellungen ist oftmals • Die Verfügbarkeit von Ersatzabstellungsmöglichkeiten ist abhängig vom\r\n\r\nentscheidend für ein Gesamtkonzept, hat also jeweiligen Standort und kann daher eingeschränkt sein. Aus diesem Grund\r\n\r\nunmittelbar Einfluss auf die Stellungnahme auf ein informieren wir Sie frühzeitig über baubedingte Kapazitäts- und\r\n\r\nGPE: Wie stellen sie sich die Abstimmung derartiger Anlageneinschränkungen, damit Sie diese bereits bei der Bestellung der\r\n\r\nWenn-Dann-Fälle im zukünftigen Prozess vor? Serviceeinrichtungs Gleise (SE Gleise) berücksichtigen können.\r\n\r\n• Sofern Infrastrukturmaßnahmen nicht rechtzeitig vor dem SE Bestellzeitraum\r\n\r\nkommuniziert werden konnten, haben Sie die Möglichkeit, im Rahmen Ihrer\r\n\r\nStellungnahme zum Fahrplanprodukt (z. B. GPE) oder zu den SE\r\n\r\nEinschränkungen Hinweise zu Ihrem Bedarf zu geben. Bitte geben Sie dabei an,\r\n\r\nob Ersatzabstellungskapazitäten benötigt werden oder ob Anpassungsbedarf bei\r\n\r\nbereits bestellten Serviceeinrichtungen besteht.",223,"{\"canonical_url\":null,\"normalized_sha256\":\"bfceeb86fd85f2d56d54a4b09f7f4dfc7f1f8c0c096a927d009985bfe5c7c741\",\"page\":4,\"source_id\":\"src_fdf7048d9eb0f98e0a93\",\"source_sha256\":\"0194b5a78c0a2db74d1b0421bbf0f4070d7b1420f7d8f1d5f83ccf3fd16c8360\",\"source_version_id\":\"sv_0194b5a78c0a2db74d1b0421\"}","e4da1c0718690c34dbd46da7e3817a4f173bb2ececde998273bf1b640e238dc3"],["chunk_f5b3415d18eb9263e8ab6420","wiki/sources/taf-tap-tsi-dialog-24-juni-2026-antworten-und-offene-punkte-data.md",4,"Seite 4","DB InfraGO AG | Follow-up: TAF/TAP TSI-Dialog am 24.06.2026 ​ 4",11,"{\"canonical_url\":null,\"normalized_sha256\":\"bfceeb86fd85f2d56d54a4b09f7f4dfc7f1f8c0c096a927d009985bfe5c7c741\",\"page\":4,\"source_id\":\"src_fdf7048d9eb0f98e0a93\",\"source_sha256\":\"0194b5a78c0a2db74d1b0421bbf0f4070d7b1420f7d8f1d5f83ccf3fd16c8360\",\"source_version_id\":\"sv_0194b5a78c0a2db74d1b0421\"}","314dfed117b5c49713958f1666f32bc6e2e97e92921e0c41f01d6ca2e23f5b1f"],["chunk_1d525f8635eaccb7094bbe89","wiki/sources/taf-tap-tsi-dialog-24-juni-2026-antworten-und-offene-punkte-data.md",5,"Seite 5","2. Ersatzabstellung (2/2)\r\n\r\nFrage Antwort DB InfraGO AG\r\n\r\nDer Regelprozess zu (Ersatz)Abstellungen korreliert • Die Verfügbarkeit von Ersatzabstellungsmöglichkeiten ist abhängig vom\r\n\r\nterminlich an keiner Stelle mit dem neuen ujBau jeweiligen Standort und kann daher eingeschränkt sein. Aus diesem Grund\r\n\r\nProzess und der dortigen Terminkette. Es ist daher in informieren wir Sie frühzeitig über baubedingte Kapazitäts- und\r\n\r\nvielen Fällen schlichtweg für die EVU unmöglich, Anlageneinschränkungen, damit Sie diese bereits bei der Bestellung der\r\n\r\nrechtzeitig zum GPE ein Konzept abzugeben. Wie Serviceeinrichtungs Gleise (SE Gleise) berücksichtigen können.\r\n\r\nstellt sich InfraGO die Lösung dieses Problems vor? • Sofern Infrastrukturmaßnahmen nicht rechtzeitig vor dem SE Bestellzeitraum\r\n\r\nkommuniziert werden konnten, haben Sie die Möglichkeit, im Rahmen Ihrer\r\n\r\nStellungnahme zum Fahrplanprodukt (z. B. GPE) oder zu den SE\r\n\r\nEinschränkungen Hinweise zu Ihrem Bedarf zu geben. Bitte geben Sie dabei an,\r\n\r\nob Ersatzabstellungskapazitäten benötigt werden oder ob Anpassungsbedarf bei\r\n\r\nbereits bestellten Serviceeinrichtungen besteht.\r\n\r\nDB InfraGO AG | Follow-up: TAF/TAP TSI-Dialog am 24.06.2026 ​ 5",157,"{\"canonical_url\":null,\"normalized_sha256\":\"bfceeb86fd85f2d56d54a4b09f7f4dfc7f1f8c0c096a927d009985bfe5c7c741\",\"page\":5,\"source_id\":\"src_fdf7048d9eb0f98e0a93\",\"source_sha256\":\"0194b5a78c0a2db74d1b0421bbf0f4070d7b1420f7d8f1d5f83ccf3fd16c8360\",\"source_version_id\":\"sv_0194b5a78c0a2db74d1b0421\"}","023a5db871ae6105ea4d193202ecc388d31e6c2036e22a5b12c75fb2e320d816"],["chunk_9ac7c9278ac831c24d6c25da","wiki/sources/taf-tap-tsi-dialog-24-juni-2026-antworten-und-offene-punkte-data.md",6,"Seite 6","3. Detaillierung zum 20h-Zug (1/3)\r\n\r\nFrage Antwort DB InfraGO AG\r\n\r\nWie bestellt man • Auswählen von VerkehrsArtKundeZusatz „20h-Zug“\r\n\r\neinen 20h-Zug im schaltet das Feld Nachlassnummer frei\r\n\r\npathOS Portal?\r\n\r\n• Angabe der Antrags-ID im Feld Nachlassnummer\r\n\r\n(Produktausprägungen/Sonstige Angaben)\r\n\r\n• Jede ID ist nur einmalig verwendbar\r\n\r\n• Berücksichtigung in der Abrechnung kann nur\r\n\r\ngewährleistet werden, wenn beide Merkmale korrekt\r\n\r\nbefüllt sind\r\n\r\nDB InfraGO AG | Follow-up: TAF/TAP TSI-Dialog am 24.06.2026 ​ 6",70,"{\"canonical_url\":null,\"normalized_sha256\":\"bfceeb86fd85f2d56d54a4b09f7f4dfc7f1f8c0c096a927d009985bfe5c7c741\",\"page\":6,\"source_id\":\"src_fdf7048d9eb0f98e0a93\",\"source_sha256\":\"0194b5a78c0a2db74d1b0421bbf0f4070d7b1420f7d8f1d5f83ccf3fd16c8360\",\"source_version_id\":\"sv_0194b5a78c0a2db74d1b0421\"}","f577faa5339aa0d3a5395a32745a889f2f425ef15139007ccc147b3e97fca700"],["chunk_cf46b99a717b0e249e708e67","wiki/sources/taf-tap-tsi-dialog-24-juni-2026-antworten-und-offene-punkte-data.md",7,"Seite 7","3. Detaillierung zum 20h-Zug (2/3)\r\n\r\nFrage Antwort DB InfraGO AG\r\n\r\nWie bestellt man einen 20h-Zug über die • Es muss eine Trassenerstbestellung aus dem GelV über die SST ausgelöst\r\n\r\nSchnittstelle? werden.\r\n\r\n• Das Feld rabattNr darf nur dann mit einer 20h-Antrag-ID befüllt werden, wenn\r\n\r\nin verkehrsArtKundeZusatz „20h-Zug“ ausgewählt wurde\r\n\r\n• verkehrsArtKundeZusatz „20h-Zug“ ohne Angabe einer 20h-Antrag-ID führt zur\r\n\r\nAbrechnung als Regeltrasse\r\n\r\nWie wird die 20h-Antrag-ID vergeben? • Automatisiert durch das 20h-Zug-Tool, sofern die Prüfung des Antrags als\r\n\r\nplausibel bestätigt wurde.\r\n\r\nWelches Format hat die 20h-Antrag-ID? • [Z][Jahr der Anmeldung][fünfstellige Nummer] → Beispiel: Z202612345\r\n\r\nWo muss die 20h-Antrag-ID hinterlegt werden? • Antrags-ID:\r\n\r\nWelche Felder müssen zur Kennung als 20h-Zug • pathOS: Feld „Nachlassnummer“\r\n\r\nmitgegeben werden? • Schnittstelle: NSP „rabattNr“\r\n\r\n• Kennung:\r\n\r\n• verkehrsArtKundeZusatz > Auswahl „20h-Zug“\r\n\r\n→ Beide Angaben sind erforderlich.\r\n\r\nDB InfraGO AG | Follow-up: TAF/TAP TSI-Dialog am 24.06.2026 ​ 7",141,"{\"canonical_url\":null,\"normalized_sha256\":\"bfceeb86fd85f2d56d54a4b09f7f4dfc7f1f8c0c096a927d009985bfe5c7c741\",\"page\":7,\"source_id\":\"src_fdf7048d9eb0f98e0a93\",\"source_sha256\":\"0194b5a78c0a2db74d1b0421bbf0f4070d7b1420f7d8f1d5f83ccf3fd16c8360\",\"source_version_id\":\"sv_0194b5a78c0a2db74d1b0421\"}","a0677ddb15be7d4ae14cf4864869ca49873845a8e8ac7ea758486e88f13a09fc"],["chunk_f85ec75f0e14eca65b7eb602","wiki/sources/taf-tap-tsi-dialog-24-juni-2026-antworten-und-offene-punkte-data.md",8,"Seite 8","3. Detaillierung zum 20h-Zug (3/3)\r\n\r\nFrage Antwort DB InfraGO AG\r\n\r\nWird es INB-Änderungen geben? • Nein, die INB selbst werden nicht geändert.\r\n\r\nKann auch eine Änderungsbestellung anstatt einer • Nein, Änderungsbestellungen in die Vergangenheit sind nicht erlaubt.\r\n\r\nStornierung eingereicht werden? Eine Änderungsbestellung würde zu einer Splittung der PathDetailsMessage\r\n\r\nführen, da wir keine Änderung der OTN innerhalb einer PDM durchführen\r\n\r\ndürften.\r\n\r\nSind in einer PDM alle Laufwegpunkte enthalten, so • Nein, es sind nicht alle Laufwegspunkte enthalten.\r\n\r\ndass eine 20h-Teilstorno wirklich ab jedem LWP Bitte wählen Sie bei der Stornierung jene verfügbare Betriebsstelle aus, die\r\n\r\ntechnisch möglich ist? Heutzutage sind in einem TPN- zuletzt durchfahren wurde und geben Sie in dem Stornierungsgrund die zuletzt\r\n\r\nDatensatz ja nicht alle LWP enthalten, so dass gefahrene Betriebsstelle an.\r\n\r\nTeilstornos nur eingeschränkt möglich sind.\r\n\r\nFindet eine Anpassung der SST-Beschreibung statt? • SST-Doku wurde ergänzt (Aufnahme Ausprägung 20h-Zug bei\r\n\r\nVerkehrsArtKundeZusatz). Die Veröffentlichung Anlage 1 am 11.6. als Version\r\n\r\n4.6.3.1 wurde als KI am 11.6. sowie im TTT-Dialog am 24.6. kommuniziert.\r\n\r\nDB InfraGO AG | Follow-up: TAF/TAP TSI-Dialog am 24.06.2026 ​ 8",175,"{\"canonical_url\":null,\"normalized_sha256\":\"bfceeb86fd85f2d56d54a4b09f7f4dfc7f1f8c0c096a927d009985bfe5c7c741\",\"page\":8,\"source_id\":\"src_fdf7048d9eb0f98e0a93\",\"source_sha256\":\"0194b5a78c0a2db74d1b0421bbf0f4070d7b1420f7d8f1d5f83ccf3fd16c8360\",\"source_version_id\":\"sv_0194b5a78c0a2db74d1b0421\"}","c7509b0e12e943360b707ab260df3c819c5164cf1cdb8f2c43b0d490b69b0536"],["chunk_52bb56f016463ffd9dd78c6f","wiki/sources/taf-tap-tsi-dialog-24-juni-2026-antworten-und-offene-punkte-data.md",9,"Seite 9","Weitere Fragen zum Thema 20h-Züge beantworten wir Ihnen gerne\r\n\r\nim Vertiefungstermin am 15. Juli\r\n\r\nDB InfraGO AG | Follow-up: TAF/TAP TSI-Dialog am 24.06.2026 ​ 9",25,"{\"canonical_url\":null,\"normalized_sha256\":\"bfceeb86fd85f2d56d54a4b09f7f4dfc7f1f8c0c096a927d009985bfe5c7c741\",\"page\":9,\"source_id\":\"src_fdf7048d9eb0f98e0a93\",\"source_sha256\":\"0194b5a78c0a2db74d1b0421bbf0f4070d7b1420f7d8f1d5f83ccf3fd16c8360\",\"source_version_id\":\"sv_0194b5a78c0a2db74d1b0421\"}","5ec897ff85e23161dc36c44d0f860dc6d476c5496584c9ad6c52ce5e76f9b5e0"],["chunk_c2553ab004c6fdcd309e1bd1","wiki/sources/taf-tap-tsi-dialog-24-juni-2026-antworten-und-offene-punkte-data.md",10,"Seite 10","4. Baubedingte Zusatzleistung\r\n\r\nFrage Antwort DB InfraGO AG\r\n\r\nIst eine kostenlose Änderungsbestellung mit einer Die Angabe „baubedingte Zusatzleistung“ ist bei einer Änderungsbestellung nicht\r\n\r\nbaubedingten Zusatzleistung möglich? vorgesehen. Siehe Ril 402.0305, §11, Absatz 2:\r\n\r\n„Hierunter fallen insbesondere zusätzliche baubedingte Anmeldungen für\r\n\r\n- Zu- und Abführungsfahrten zu einem Schienen ersatzverkehr,\r\n\r\n- Drehfahrten,\r\n\r\n- Zu- und Abführungsfahrten zu einer anderen als der gewöhnlichen Abstell- oder\r\n\r\nTankanlage,\r\n\r\n- Zu- und Abführungsfahrten von Triebfahrzeugen oder\r\n\r\n- zusätzliche Verkehre auf Grund einer Änderung der Zugcharakteristik (z.B.\r\n\r\nAblasten auf Grund geringerer Grenzlast einer Umleitungsstrecke).“\r\n\r\nDB InfraGO AG | Follow-up: TAF/TAP TSI-Dialog am 24.06.2026 ​ 10",98,"{\"canonical_url\":null,\"normalized_sha256\":\"bfceeb86fd85f2d56d54a4b09f7f4dfc7f1f8c0c096a927d009985bfe5c7c741\",\"page\":10,\"source_id\":\"src_fdf7048d9eb0f98e0a93\",\"source_sha256\":\"0194b5a78c0a2db74d1b0421bbf0f4070d7b1420f7d8f1d5f83ccf3fd16c8360\",\"source_version_id\":\"sv_0194b5a78c0a2db74d1b0421\"}","fa6576187d2a9d46c719ecfb4d4d91ebbc114204e8cb28e9e54c96d43172424f"],["chunk_eecaa0b029dade94e5634fdc","wiki/sources/taf-tap-tsi-dialog-24-juni-2026-antworten-und-offene-punkte-data.md",11,"Seite 11","5. Indirekt betroffene Züge bei Totalausfall\r\n\r\nFrage Antwort DB InfraGO AG\r\n\r\nWie soll bei einem Totalausfall der andere betroffene Sollte das GPE als Ausfall gesendet werden, ist für die Angabe eines indirekt\r\n\r\nZug angegeben werden? Es gibt ja keine Laufpunkte baubetroffenen Zuges eine Stellungnahme notwendig.\r\n\r\nzu Referenz\r\n\r\nDiese Angabe muss, wie unten beschrieben, erfolgen:\r\n\r\n1. Hinweis im Freitextfeld auf Nachrichtenebene, dass Ausfall akzeptiert wird,\r\n\r\njedoch eine Angabe zu einem indirekt baubetroffenen Zug notwendig ist.\r\n\r\n2. Angabe der ersten und letzten Betriebsstelle\r\n\r\n3. Angabe der Betriebsstelle, an der der Zug verknüpft ist, sowie der gewünschte\r\n\r\nUmgang mit diesem Zug.\r\n\r\nDB InfraGO AG | Follow-up: TAF/TAP TSI-Dialog am 24.06.2026 ​ 11",109,"{\"canonical_url\":null,\"normalized_sha256\":\"bfceeb86fd85f2d56d54a4b09f7f4dfc7f1f8c0c096a927d009985bfe5c7c741\",\"page\":11,\"source_id\":\"src_fdf7048d9eb0f98e0a93\",\"source_sha256\":\"0194b5a78c0a2db74d1b0421bbf0f4070d7b1420f7d8f1d5f83ccf3fd16c8360\",\"source_version_id\":\"sv_0194b5a78c0a2db74d1b0421\"}","3442c249ceda9a048850dfcaca1c9257e79ae3e13e2efe7de55632eb9e678f46"],["chunk_aae057aaac4cdb208c6105d2","wiki/sources/taf-tap-tsi-dialog-24-juni-2026-antworten-und-offene-punkte-data.md",12,"Seite 12","5. Prozess indirekt betroffene Züge\r\n\r\nAngabe des TrainActivityCodes beim Totalausfall im GPE\r\n\r\nHinweis im Freitextfeld auf\r\n\r\nNachrichtenebene\r\n\r\n• Ausfall wird angenommen\r\n\r\n• Stellungnahme aufgrund der\r\n\r\nVerknüpfung zu anderem Zug\r\n\r\nAngabe der\r\n\r\n• ersten und letzten Betriebsstelle der\r\n\r\nRegeltrasse\r\n\r\n• Betriebsstelle, an der die\r\n\r\nZugverknüpfung besteht + TAC + alle\r\n\r\nrelevanten Angaben\r\n\r\nDB InfraGO AG | Follow-up: TAF/TAP TSI-Dialog am 24.06.2026 ​ 12",62,"{\"canonical_url\":null,\"normalized_sha256\":\"bfceeb86fd85f2d56d54a4b09f7f4dfc7f1f8c0c096a927d009985bfe5c7c741\",\"page\":12,\"source_id\":\"src_fdf7048d9eb0f98e0a93\",\"source_sha256\":\"0194b5a78c0a2db74d1b0421bbf0f4070d7b1420f7d8f1d5f83ccf3fd16c8360\",\"source_version_id\":\"sv_0194b5a78c0a2db74d1b0421\"}","040c58d4163c59b84772962cd5567d12134161232a8bec4e080230c588a26161"],["chunk_0a31c7b736f638402c8cce59","wiki/sources/taf-tap-tsi-dialog-24-juni-2026-antworten-und-offene-punkte-data.md",13,"Seite 13","6. NAÄ nicht aus unterjährigem Bau\r\n\r\nFrage Antwort DB InfraGO\r\n\r\nAußerdem bitten wir um Übermittlung der DBInfraGo- • Hier ist keine Fristsetzung möglich. Als Beispiel dient hier der kurzfristige\r\n\r\nseitigen Frist für die Auslösung einer NAÄ im Gelegenheitsverkehr, bei denen eine versendete Trasse so nicht mehr bzw. nie\r\n\r\nNetzfahrplan ohne Baubezug, wenn z-8 nur für NAÄ in fahrbar gewesen wäre. In diesen Fällen haben wir im Rahmen der\r\n\r\nujBau gilt. Unmöglichkeit, die Notwendigkeit zur Anpassung der Trasse.\r\n\r\nDB InfraGO AG | Follow-up: TAF/TAP TSI-Dialog am 24.06.2026 ​ 13",88,"{\"canonical_url\":null,\"normalized_sha256\":\"bfceeb86fd85f2d56d54a4b09f7f4dfc7f1f8c0c096a927d009985bfe5c7c741\",\"page\":13,\"source_id\":\"src_fdf7048d9eb0f98e0a93\",\"source_sha256\":\"0194b5a78c0a2db74d1b0421bbf0f4070d7b1420f7d8f1d5f83ccf3fd16c8360\",\"source_version_id\":\"sv_0194b5a78c0a2db74d1b0421\"}","3e7263b0404a9186b1ea6c4efa91182f03ea9a34eba928513562ccfa67daf7b1"],["chunk_8a658f41b63399a489938fb2","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-antworten-und-offene-punkte-data.md",0,"Seite 1","13. TAF/TAP TSI-Dialog der DB InfraGO\r\n\r\nFollow-up: Ausgewählte Antworten aus dem Termin\r\n\r\n26.03.2026 Versand im\r\n\r\nNachgang",16,"{\"canonical_url\":null,\"normalized_sha256\":\"365107c16438b2f929141ebdcbc04b749cee0b52baa3fdfe2875ac99103e286f\",\"page\":1,\"source_id\":\"src_19a7b48948c766db65df\",\"source_sha256\":\"edb2bc1e9f24d50e73b6b8c5392b5a4059bcf8d2bb5c26d06b979c3c6784db41\",\"source_version_id\":\"sv_edb2bc1e9f24d50e73b6b8c5\"}","262291183d897eb37638d2f4ef4018f97982bb16837df515932429fe69f6f6dd"]]');
