fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","1ec25b6aeb1b790d6ce5c115355299023d199d7662273e167647452dc9d999b0"],["chunk_7b6a055ca5b5570a793fac6e","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",3,"Seite 4","2. Status TTT Einführung\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 4",13,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":4,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","4ab38c00e9d04ca909e34e82c274d41ecf2e033fdb22ce46c264946987e475c0"],["chunk_fbd19492ad7ab6dcdfda1037","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",4,"Seite 5","Trassenanmeldung ist am 13.03.2026 erfolgreich gestartet\r\n\r\n25.03.2026\r\n\r\n(16:00 Uhr)\r\n\r\nCI Bestellungen Portalbestellungen\r\n\r\n25000 1800\r\n\r\n23144\r\n\r\n1547\r\n\r\n1600\r\n\r\n20000\r\n\r\n1400\r\n\r\n1200\r\n\r\n15000\r\n\r\n1000\r\n\r\n800\r\n\r\n10000\r\n\r\n600\r\n\r\n400 310\r\n\r\n5000\r\n\r\n200\r\n\r\n1273 652\r\n\r\n29\r\n\r\n0 0\r\n\r\nFehlerhaft Valide Abbestellt Fehlerhaft Valide Abbestellt\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 5",49,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":5,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","eff3cee65be1885f69ee906fcb1f00ab619db08a65d11ccf3ed4286275373af7"],["chunk_8e8d3c2cd183e40fa0e4fac7","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",5,"Seite 6","Mit erfolgreichem Start der Trassenanmeldung am 13.3.2026\r\n\r\ngeht der Fokus auf die nachfolgenden Phasen über\r\n\r\nErgebnisse seit letztem TTT-Dialog\r\n\r\n✓ Trassenanmeldungen für die erste Phase der Netzfahrplanerstellung sind am 13. März erfolgreich\r\n\r\ngestartet\r\n\r\n✓ Release für pathOS ist am 11. März erfolgt: angekündigte zusätzliche Funktionen im pathOS\r\n\r\nBestellportal wurden bereitgestellt\r\n\r\n✓ Veröffentlichung beantworteter Fragen aus dem TTT-Dialog vom 09.03.2026 am 12.03.2026\r\n\r\nNächste Schritte\r\n\r\n• Onboarding der Schnittstellenpartner noch nicht für alle abgeschlossen\r\n\r\n→ Aufruf an alle EVU, deren Onboarding noch nicht abgeschlossen ist: Onboarding abschließen und\r\n\r\nparallel Trassenanmeldung via pathOS vorbereiten. Da mit dem noch verbleibenden Vorlauf das\r\n\r\nRisiko für technische Herausforderungen hoch ist.\r\n\r\nDB InfraGO hält Ressourcen vor, um das Onboarding abzuschließen.\r\n\r\n• Markttests Trassenanmeldung und Defect-Behebung kontinuierlich fortsetzen → Fokus geht hier\r\n\r\nauf ujBau, NEP2 und GelV über\r\n\r\n• Vorbereitung Markttest TTT mit Identifiern im Betrieb (Start 14.4.)\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 6",149,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":6,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","9f7efab8c593ed979a55082052bcf7fe826122259e3695f013cd136367d47879"],["chunk_f097e2befed00a9edd09643c","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",6,"Seite 7","3. Zentraler Eingangskanal: Support\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 7",13,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":7,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","4fec33ee9d48416e9f967a5672ce2891cfc9df25984bd2b3e1b9656a1b512d68"],["chunk_029dbcca56229f6a31e7a37f","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",7,"Seite 8","Zentrale Anlaufstelle für Anfragen zur Trassenanmeldung:\r\n\r\nSupport\r\n\r\nBitte alle Anfragen zur Trassenanmeldung ausschließlich über den\r\n\r\nSupport einreichen – keine Direktansprache einzelner Personen, um eine\r\n\r\nstrukturierte Bearbeitung und schnelle Rückmeldung sicherzustellen.\r\n\r\nWas gehört in den Support?\r\n\r\nDer Support übernimmt sämtliche Anliegen zur Trassenanmeldung, inkl.:\r\n\r\n• Fragen zu Schulungsmaterialien/-inhalten\r\n\r\n• Rückfragen aus Sprechstunden\r\n\r\nHinweis: Bitte bei konkreten Vorgängen Kundennummer und Request-ID mit\r\n\r\nangeben – Details siehe nächste Folie.\r\n\r\nKontakt zum Support:\r\n\r\n• E-Mail: [E-Mail-Adresse entfernt]\r\n\r\n• Webformular (DB InfraGO Homepage)\r\n\r\n• Sprechstunden\r\n\r\n• Mehr dazu auf der nächsten Folie\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 8",96,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":8,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","3071e7666816b59064f473c1b2bcddacb7997cd95a26874729e358cb797ac49b"],["chunk_2ea015b6377d4418a5ac73b5","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",8,"Seite 9","Seit dem 13.03. gehen alle Anfragen, egal ob pathOS oder TPN,\r\n\r\nan die folgenden Adressen\r\n\r\nE-Mail Kontaktformular Telefon Sprechstunde\r\n\r\n(nur pathOS)\r\n\r\n[E-Mail-Adresse entfernt] Kontaktformular pathOS [Telefonnummer entfernt] bis 06.03.2026:\r\n\r\nDonnerstags, 15-16 Uhr\r\n\r\nHomepage DB InfraGO\r\n\r\n10.03.2026 bis 24.04.2026:\r\n\r\nTäglich, Mo. bis Fr., 10-11 Uhr\r\n\r\n(keine Sprechstunden an\r\n\r\nFeiertagen!)\r\n\r\nSupport\r\n\r\n→ Aktuelle Informationen zur Anwendung sind im Infraportal unter Aktuelles zu den Tools zu finden.\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 9",73,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":9,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","d11c3b4f1cd9185315e7ddec97e24702db24fda3a258a58327ebaa127a4ff4df"],["chunk_d56b0ce510a570b05c2dce20","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",9,"Seite 10","4. Updates zu pathOS\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 10",13,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":10,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","88e3b9912a146d650bc3e9ebbd78fca917c972ac669054621a07f932555103fc"],["chunk_62cc7858576f329515472838","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",10,"Seite 11","Tipps und Tricks zur Bedienung von pathOS, bekannte Fehler und\r\n\r\nWorkarounds – Stand: 23.03.2026\r\n\r\n- TPN Importe + Fallstricke und Tricks\r\n\r\n- Bitte achten Sie darauf, dass unter Zugcharakteristik „PZB90“ ausgewählt ist\r\n\r\n- Baukorridor: Wenn Sie aus einem Entwurf den Regelzug erstellt und abgeschickt haben, erstellen Sie aus dem offenen Vorgang die\r\n\r\nBauzeitscheibe. Dann können Sie dort den Baukorridor eingeben.\r\n\r\n- Arbeiten mit Entwürfen und Speichern, Bezeichnungen etc.\r\n\r\n- Entwürfe, die fortgesetzt werden, bleiben nach Abschicken unter alter Bezeichnung im Reiter Entwürfe gespeichert. Wenn man die\r\n\r\nBezeichnung ändert und erneut als Entwurf speichert, verdoppelt sich der Entwurf. In beiden Fällen kann der Entwurf manuell\r\n\r\ngelöscht werden.\r\n\r\n- Ein neuer Entwurf, der unter einer bereits benutzten Vorgangsbezeichnung gespeichert wird, überschreibt ungefragt den bisherigen\r\n\r\nVorgang. Wenn der alte Entwurf beibehalten werden soll, vergeben Sie bitte eine neue Vorgangsbezeichnung\r\n\r\n- Im Kalender wird zuerst das aktuelle Fahrplanjahr (2026) angezeigt – dieses muss manuell mit Klick auf den Pfeil rechts auf 2027\r\n\r\nangepasst werden (sowohl Trassenanmeldung als auch Case Reference Objekt)\r\n\r\n- Im Kalender Verkehrszeitraum per Maus auswählen\r\n\r\n- Aktuell haben wir Einzelfälle, bei denen Entwürfe nicht gespeichert werden können – wenn Sie das haben, gerne eine Information\r\n\r\ndazu mit Screenshot und Details, wir sind hier noch in der Fehleranalyse (und es können mehrere Ursachen sein)\r\n\r\n- Verbesserungsvorschläge werden aufgenommen\r\n\r\n- Verbesserung der Filterlogik, z.B. Ausblenden von Vorgängen mit dem Status Zurückweisung, Speichern der Filtereinstellungen\r\n\r\n- Spaltenbreite ändern\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 11",243,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":11,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","33ea852cc97cd78e56d5a20b95f06d5c828dffdb8cd966568779e4fc3d494d20"],["chunk_89d73cfe694d9803f75da3cb","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",11,"Seite 12","Informationen zur Vorbereitung auf die Bestellung im\r\n\r\nGelegenheitsverkehr in pathOS\r\n\r\nBedienung von pathOS & Fachlichkeit\r\n\r\n• Auch wenn aktuell noch im Netzfahrplan bestellt wird, gab es den Wunsch, auch das Thema GelV bereits zu adressieren.\r\n\r\nGenerell unterscheidet sich die Bedienung von pathOS im GelV NICHT vom Netzfahrplan, das Webportal erkennt\r\n\r\nautomatisch, dass es eine Bestellung im GelV ist. Alle Funktionalitäten wie z.B. Eingabe von Produktausprägungen, Laufweg,\r\n\r\nZugcharakteristik, Identifikatoren und Verkehrszeitraum sind gleich\r\n\r\n• Es müssen insbesondere dieselben Angaben getätigt werden, die auch im Netzfahrplan nötig sind, zusätzliche Felder gibt es\r\n\r\nim GelV nicht\r\n\r\nSchulungen\r\n\r\n• Im Kern sind alle Schulungsmaterialien für den GelV ebenfalls zu verwenden (und schon so aufgebaut worden)\r\n\r\n• Selbstverständlich wird es auch in Begleitung des GelV weitere Schulungstermine geben: Die Vertiefungsworkshops sind\r\n\r\nbereits veröffentlicht (Juli, September, Dezember), weitere individuelle Termine werden sukzessive angeboten\r\n\r\n• Zusätzlich werden für einzelne neue und GelV-spezielle Themen dann bei Bedarf neue Erklärvideos erstellt und die Themen\r\n\r\nim Handbuch aufgenommen\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 12",167,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":12,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","8f20b3e7a4d54bdd964057a3ebfd3dc8c14c4bb6f7e49a7eb461a365aa49ee0f"],["chunk_31aaa3ecf37660fb34dafdce","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",12,"Seite 13","Schulungsmaterial aktualisiert und umfangreich online: zu\r\n\r\nverwenden für GelV und Netzfahrplananmeldephase\r\n\r\nWeb-based-Trainings (WBT): Der ideale Einstieg\r\n\r\n• 9 Grundlagen WBT in den Lerneinheiten 1-4 – Basics zur Bedienung der neuen Oberfläche\r\n\r\n• 2 komplexe WBT mit Anwendungsfällen im SGV und SPV und vielen Sonderfällen – Beide sehr empfehlenswert!\r\n\r\nErklärvideos: Vertiefung einzelner Anwendungsfälle\r\n\r\n• Mittlerweile knapp 60 Videos veröffentlicht – aufgeteilt in Anwendung in pathOS (Grundlagen und Vertiefung) sowie\r\n\r\nTAF/TAP TSI (Grundlagen und Vertiefung)\r\n\r\n• Bei Bedarf Ergänzung zusätzliche Themen, ganz aktuell hinzugefügt: „Durchführendes EVU“, „Mehrfachtraktionen“\r\n\r\nHandbuch: Umfangreiches Detailwissen und Nachschlagewerk\r\n\r\n• Handbuch aktuell in Version 1.01 mit Stand 13.03.26 veröffentlicht – Überarbeitung bei Bedarf kurzfristig möglich,\r\n\r\nÄnderungshistorie im Dokument verfügbar\r\n\r\nVertiefungsworkshops: Anwendungsbeispiele gemeinsam mit Experten durchgehen\r\n\r\n• Zusätzlich auch für den weiteren Jahresverlauf schon terminiert sind 3stündige Vertiefungsworkshop unseres\r\n\r\nTrainingsdienstleisters – Termine bis April buchbar, weitere Termine für Juli, September veröffentlicht (Termine für\r\n\r\nden Fahrplanwechsel folgen für Dezember)\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 13",157,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":13,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","fb3e3c0e3c4cd86b9926da34e57b424477a2de6b4320e8f9f879235dfdd5ce5a"],["chunk_e3984cb67e9883ef7b5dd9e1","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",13,"Seite 14","Trassenanmeldung in PCS\r\n\r\nHinweise zur Trassenanmeldung im Netzfahrplan 2027\r\n\r\nExkurs während des\r\n\r\n13. TTT-Dialog\r\n\r\n14",15,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":14,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","be57c43701360f3fc23bd374646162751c1e100b250a436c52e073cb4ff60862"],["chunk_24b4f67f066deb7f1b4b92f7","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",14,"Seite 15","Zielsetzung & Inhalt\r\n\r\nHäufig gestellte Fragen: Antworten zu Umgang mit Wechsel des\r\n\r\n1\r\n\r\nhäufig auftretenden Fragen zu PCS durchführenden EVU\r\n\r\nBestellungen zusammenstellen\r\n\r\n2 Angabe Handoverpoints\r\n\r\nKonkrete Beispiele: Handlungssicherheit\r\n\r\nfür die Trassenanmeldung geben durch Umgang mit neuen Network\r\n\r\n3\r\n\r\nkonkrete Beispiele Specific Parameter in PCS\r\n\r\nUmgang mit Fehlern bei\r\n\r\n4 automatisierter Übernahme von\r\n\r\nBestellungen aus PCS\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 15",64,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":15,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","40b39856c80c22e389e38177f6d744e6e6eb0523caeda34b647309772fbeeaca"],["chunk_6622078ccb48a9cfe9e5ee5a","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",15,"Seite 16","1 Umgang mit Wechsel des durchführenden EVU\r\n\r\nAngabe zum durchführenden EVU im Freitextfeld in PCS (1/2)\r\n\r\n▪ TAF/TAP-TSI unterscheidet zwischen bestellendem EVU (Responsible Applicant) und\r\n\r\ndurchführendem EVU (Responsible RU)\r\n\r\n▪ Es ist seitens DB InfraGO vorgesehen, dass das durchführende EVU (Responsible RU) innerhalb\r\n\r\neiner Trassenanmeldung wechseln kann (z.B. an Landesgrenzen).\r\n\r\n▪ In PCS resultiert der Wechsel des Responsible RU (RRU) in einer zusätzlichen Trassenanmeldung für\r\n\r\nden gleichen Verkehrstag, was gemäß den OTN-Vergaberegeln der Schnittstellendokumentation der\r\n\r\nDB InfraGO unter gleicher OTN verboten ist.\r\n\r\nEine systemische Angabe des RRU im vorgesehenen Feld in der Trassenanmeldung in PCS selbst führt\r\n\r\ndaher zu einer technischen Zurückweisung durch DB InfraGO. Diese technische Zurückweisung ist für\r\n\r\nden Besteller in PCS nicht erkennbar.\r\n\r\n▪ Für die Trassenanmeldungen für Fahrplan 2027 im Netzfahrplan ist es deshalb erforderlich, die\r\n\r\nWechsel zwischen RRU innerhalb einer Trassenanmeldung für DB InfraGO ausschließlich im\r\n\r\nKommentarfeld anzugeben (siehe nächste Folie).\r\n\r\n▪ Diese Regelung gilt explizit ausschließlich für Trassenanmeldungen via PCS!\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 16",165,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":16,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","8df77ca2e9fcde88b7c5340234cf834b3c9967b263a0a6807ac9187162430879"],["chunk_5d8836d3f02585f9b474860a","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",16,"Seite 17","1 Umgang mit Wechsel des durchführenden EVU\r\n\r\nAngabe zum durchführenden EVU im Freitextfeld in PCS (2/2)\r\n\r\n• Für die Angabe im Kommentarfeld soll folgendes Format genutzt werden:\r\n\r\n„Von <Betriebsstelle (PLC, ggf. Ril100)> bis <Betriebsstelle (PLC, ggf. Ril100)>\r\n\r\nist für die Durchführung der Zugfahrt das EVU <CompanyCode> mit der\r\n\r\nKundennummer <Kunden-Nr.> zuständig.“\r\n\r\n• Beispiel für den Grenzübergang Forbach mit dem Zielbahnhof Kaiserslautern:\r\n\r\nVon Forbach(XFFB),PLC FR1185 bis Saarbrücken Grenze(SXSD), PLC DE19152 ist für die\r\n\r\nDurchführung der Zugfahrt das EVU 9999 mit der Kundennummer KABCD zuständig. Ab\r\n\r\nSaarbrücken Grenze(SXSD), PLC DE19152 bis Kaiserslautern(SKL), PLC DE15333 ist für die\r\n\r\nDurchführung der Zugfahrt das EVU 9999 mit der Kundennummer KABCD zuständig\r\n\r\n• Die Angabe des Kommentarfeld muss an der Gesamtbestellung, nicht am Laufpunkt erfolgen.\r\n\r\n• Bei mehreren Wechseln darf sich die Angabe im Kommentarfeld wiederholen.\r\n\r\n• Eine systemische Angabe des RRU im vorgesehenen Feld in der Trassenanmeldung in PCS selbst führt\r\n\r\nzu einer technischen Zurückweisung durch DB InfraGO.\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 17",162,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":17,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","b297d6d81beae13c0aee02ce02596e22e972a1596fcc6b7f4f6a5c98a59cba83"],["chunk_5bce400acecc883c3632346c","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",17,"Seite 18","2 Angabe Handoverpoints\r\n\r\nNutzung Handoverpoints wie ...\r\n\r\n• Mit TAF/TAP-TSI ist bei internationalen Trassenanmeldungen die Angabe von Planning Handovers\r\n\r\nerforderlich.\r\n\r\n• Für Trassenanmeldungen, die über mindestens eine internationale Grenze verkehren, sind die\r\n\r\nHinweise entsprechend nationaler Vorgaben der DB InfraGO auch für PCS-Anmeldungen zu\r\n\r\nberücksichtigen.\r\n\r\n• DB InfraGO hat auf der Webseite unter Fahrplan: EVU-Schnittstelle für alle relevanten Grenzpunkte\r\n\r\ndie notwendigen Angaben veröffentlicht.\r\n\r\n• Konkrete Beispiele zur Anwendung dieser Angaben sind auf den nächsten Folien dargestellt.\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 18",84,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":18,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","77e7a526ffab72cbb0f2e586b458998666b74e198e8572a275c47e4821254fa0"],["chunk_645688793b6f8cc92f826b81","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",18,"Seite 19","2 Angabe Handoverpoints\r\n\r\nHandoverpoint Beispiele (1/5):\r\n\r\nEmmerich einbrechend: Emmerich ausbrechend:\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 19",19,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":19,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","e301fa9ab6c6da1c60e28006c54e8b9afa7ea24584289663ca48f40dc9bed9a4"],["chunk_7cb459e58300ab116bdd3c3e","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",19,"Seite 20","2 Angabe Handoverpoints\r\n\r\nHandoverpoint Beispiele (2/5):\r\n\r\nAachen West einbrechend: Aachen West ausbrechend:\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 20",21,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":20,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","3dfa67a5908178c952da20cb628de20b60bc0437b1b32bb470f1def0314ba202"],["chunk_9445412479e8f5aa45af7b14","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",20,"Seite 21","2 Angabe Handoverpoints\r\n\r\nHandoverpoint Beispiele (3/5):\r\n\r\nPassau Gbf einbrechend: Passau Gbf ausbrechend:\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 21",21,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":21,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","07ae682586b5151d6a36db42e40e8f53c667b775c5960d9721343930ad8b8c2a"]]');
