INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_1de3541a28c50d653659cbe9","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",21,"Seite 22","2 Angabe Handoverpoints\r\n\r\nHandoverpoint Beispiele (4/5):\r\n\r\nBasel Bad einbrechend: Basel Bad ausbrechend:\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 22",21,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":22,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","a6a927e4650d2c2ac5aaf0727ac8af901382ce181d3e8324d181cb5d50353ea6"],["chunk_e200b5448cb2f166acf08f3a","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",22,"Seite 23","2 Angabe Handoverpoints\r\n\r\nHandoverpoint Beispiele (5/5):\r\n\r\nPadborg einbrechend: Padborg ausbrechend:\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 23",19,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":23,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","bd73dffaf1e69d19257a919e71aa4824d8a8642ab73f451ee094d79b296f617c"],["chunk_963309303922c97efa51e6d2","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",23,"Seite 24","3 Umgang mit neuen Network Specific Parameter\r\n\r\nNetwork Specific Parameter auf Territory Level in PCS\r\n\r\n‒ MarktProdukt: Angabe “TRA” für ‒ kzLaermschutz: Kennzeichnung des ‒ verkehrsArtKunde: Angabe der\r\n\r\neine Trassenanmeldung. Der Zuges im Bereich der BR Deutschland Verkehrsartbezeichnung.\r\n\r\nDefault ist mit “TRA” vorbelegt. gemäß Schienenlärmschutzgesetz.\r\n\r\nDefault: 1 = Leiser Zug\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 24",59,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":24,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","7b3a658d71d0ce8ec8b8ca0a4271363b5b219058719c3bd0dfa7ad9a9f9db241"],["chunk_d850f31d47647d2f6d886c81","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",24,"Seite 25","3 Umgang mit neuen Network Specific Parameter\r\n\r\nNetwork Specific Parameter auf Location Level in PCS\r\n\r\n‒ Angabe der Zuggattung: Neu in ‒ Angabe der Kundennummer für das\r\n\r\ndrei separaten Attribute. bestellende und durchführende EVU\r\n\r\n‒ Hauptnummer der Zuggattung\r\n\r\n‒ Kurzbezeichnung der Zuggattung\r\n\r\n‒ Unternummer der Zuggattung\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 25",55,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":25,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","970f117ef99c88a7e4bd486b8ee9c089b2a975eea9e3d4d601a2c410ba61421e"],["chunk_1a17c07e43f02badc684032c","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",25,"Seite 26","3 Umgang mit neuen Network Specific Parameter\r\n\r\nWeitere wichtige Parameter in PCS\r\n\r\n‒ Angabe der Train Control ‒ Angabe einer BZA oder\r\n\r\nInformation: Dauberbeförderungsanordnung\r\n\r\nBeispiel:\r\n\r\n‒ Train Radio System: Bei\r\n\r\nInfraGO ist nur die Ausprägung\r\n\r\nGSMR bestellbar.\r\n\r\n‒ Train control System: Angabe der\r\n\r\nZugbeeinflussungssysteme, sowie die\r\n\r\nelekronische Führerstandsanzeige (EFA)\r\n\r\nBeispiel: PZB90 und EFA\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 26",62,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":26,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","f75cc2fa91f1f85e19f0cbdcde272ea52429788e3f3fe02cc6018a24251a3744"],["chunk_25b9bb420d164bf717ede81e","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",26,"Seite 27","4 Umgang mit Fehlern in PCS Bestellungen\r\n\r\nUmgang von DB InfraGO mit PCS-Bestellungen, die nicht korrekt\r\n\r\nautomatisiert von PCS nach pathOS übernommen werden\r\n\r\n• DB InfraGO nutzt eine Schnittstelle, um die Trassenanmeldungen aus PCS nach pathOS und die nachfolgenden\r\n\r\nFahrplansysteme automatisiert zu übernehmen.\r\n\r\n• Falls Trassenanmeldungen in einen Validierungsfehler laufen, wird dies in PCS dem Anwender nicht angezeigt und dort\r\n\r\ngibt es keine Korrekturmöglichkeit.\r\n\r\n• Zur Vermeidung von Validierungsfehlern bitten wir Sie – wenn möglich – an Start und Ziel des Zuglaufs Betriebsstellen\r\n\r\nauszuwählen, die einen Ril100-Code haben.\r\n\r\n• DB InfraGO wird daher Trassenanmeldungen, die nicht korrekt automatisiert übernommen werden, manuell in pathOS\r\n\r\nerfassen. Dazu wird eine neue Variantennummer (P1, P2,...) zur PathRequestID vergeben.\r\n\r\n• Wenn Sie nach Vertragsschluss solche Trassenverträge per ObjectInfoMessage über die PathID aufrufen, ist die\r\n\r\nPathRequestID nicht die von Ihnen in PCS vergebene.\r\n\r\n• Die PCS-Trassenanmeldung ist in beiden Fällen – direkt aus PCS via Schnittstelle übernommen – oder manuell übertragen,\r\n\r\nin pathOS sichtbar.\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 27",167,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":27,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","7bed96b3eb7543c143c98e753296e46cdc2242d7c35ce6f472df9ae18adedab4"],["chunk_db019f5678305541b98dab1b","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",27,"Seite 28","5. TTT im Betrieb\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 28",13,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":28,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","3a86797a5ac26e7871511e29381d7fd03def106e1b6a99276f7d487c7439be7e"],["chunk_65435ecd568a28fb81055a9d","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",28,"Seite 29","Von E-Mail zu standardisierten Schnittstellen: NSS wird\r\n\r\nTAF/TAP TSI-konform\r\n\r\nAusgangssituation Was ändert sich konkret? Was bedeutet das für Sie?\r\n\r\n• TAF/TAP TSI-Vorgaben (EU-weite • Heute: Fahrplandatenbereitstellung • Nutzung neuer Schnittstellen\r\n\r\nHarmonisierung) (GFD(Bestellte)-/BZD(Betriebliche)- erforderlich\r\n\r\nZug) u. a. per E-Mail aus der NSS\r\n\r\n• Deutlich steigende Datenmengen bzw- • Höhere Stabilität und Datenqualität\r\n\r\nFahrpläne u.a. durch Wegfall durch • Zielbild:\r\n\r\n• Reduzierte Schnittstellen und\r\n\r\nStamm- und Ergänzungsfahrpläne (≈\r\n\r\n• Zu 12/26: E-Mail Empfänger werden Abstimmungsaufwände\r\n\r\nFaktor 13)\r\n\r\nvia SFTP umgestellt oder alternativ\r\n\r\n• Manuelle E-Mail-Kommunikation nicht direkt BDV / pathOS-CI\r\n\r\nmehr skalierbar\r\n\r\n• Zu 06/27: Einstellung der\r\n\r\nBereitstellung von Daten an der NSS\r\n\r\n➢ Fazit: Bisheriger Ansatz nicht mehr • Vorteil: Standardisierte, sichere und\r\n\r\npraktikabel nachvollziehbare Kommunikation\r\n\r\nBis Juni 2027: Migration\r\n\r\nZeitplan für Kunden\r\n\r\nauf BDV / pathOS-CI\r\n\r\nAb 13.12.2026: Ab Juni 2027:\r\n\r\nEinstellung des Emailversands Einstellung der\r\n\r\nan der NSS & neue Logik (30- Bereitstellung von Daten\r\n\r\nTage-Vorschau BZD-Zug) an der NSS\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 29",160,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":29,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","f72a230e44d6dba9103ab81481859effce5aa811c53db6485b61c52314052c93"],["chunk_3b4689a30fe1dcde135ac1d7","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",29,"Seite 30","Update zu Datenqualität P/TCM und Vorblick auf Delta-Liste\r\n\r\nSeit dem 14.12.2025 ist gemäß Infrastrukturnutzungsbedingungen der DB InfraGO AG (INB) die Versendung der\r\n\r\naktuellen Zugcharakteristik durch Passenger/Train Composition Message (P/TCM) an die DB InfraGO\r\n\r\nLink offizielle\r\n\r\nverpflichtend.\r\n\r\nKundeninformation\r\n\r\nFolgende Auffälligkeiten wurden unter anderem festgestellt:\r\n\r\n• Plausibilitätsfehler\r\n\r\n• Meldungen zu Zügen, die nicht existieren bzw. nicht gefahren sind\r\n\r\nEs wurden zunächst folgende Werte auf Plausibilität geprüft:\r\n\r\n▪ Zugnummer zwischen 2 und 99999 ▪ Anzahl Wagen zwischen 0 und 100\r\n\r\n▪ Bremshundertstel zwischen 6 und 230 ▪ Anzahl Triebfahrzeuge > 0\r\n\r\n▪ Höchstgeschwindigkeit zwischen 10 km/h und 330 km/h ▪ Länge pro Einheit (Wagen oder Triebfahrzeug) < 450 m\r\n\r\n▪ Gesamtzuggewicht zwischen 10 t und 8.350 t ▪ Meterlast des Gesamtzugs zwischen 0,7 t/m und 10,0 t/m\r\n\r\n▪ Gesamtzuglänge zwischen 10 m und 835 m\r\n\r\nWir bitten um eine umgehende Prüfung der geschilderten Auffälligkeiten sowie um eine Stellungnahme, ob die genannten\r\n\r\nAbweichungen bei den EVUn ebenfalls festgestellt wurden.\r\n\r\nDie EVUn haben die korrekte Eingabe der Daten für die Zukunft sicher zu stellen.\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 30",178,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":30,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","5d03da4757972af87ab8846ab34d23a6d7b7b3613925499f525d9cea450822d3"],["chunk_ccc16860ea8595b8b0bcfa72","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",30,"Seite 31","Update zum Markttest nach Kick-Off\r\n\r\n26.03.2026\r\n\r\nTAF/TAP TSI – Dialog mit nächsten Schritten basierend auf Anmeldungen\r\n\r\nInformationsveranstaltung zum Ende-zu-Ende Kundentests: Besprechung\r\n\r\n08.04.2026\r\n\r\nweiterer Details mit angemeldeten Testpartnern, je nach angemeldetem\r\n\r\nTestbedarf\r\n\r\nKW 15/16\r\n\r\nBetriebssprechstunde inkl. Experten von LeiDis-D, BDV und TTT\r\n\r\n14.04.- 14.06.\r\n\r\nDurchführung Ende-zu-Ende Kundentests TAF/TAP TSI mit Identifiern\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 31",59,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":31,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","6f9b9c58edb9ab7835d6426720b4798e060cb7d52c89364161a0be37f6ee488e"],["chunk_7bc96b9aa3bdf7d4f7771e54","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",31,"Seite 32","Kundenfragen zu TTT-Identifier im Betrieb\r\n\r\nFrage: Wird der TAF/P-Identifier (z. B. für Betriebsphase TR/0001/AB12345.../2026-12-29)\r\n\r\nzukünftig für die Meldungen des Tf benötigt oder genügt bei den Meldungen weiterhin die\r\n\r\nOTN als Identifikator?\r\n\r\nAntwort: Fernmündliche Meldungen des Tf an die DB InfraGO unterliegen nicht dem TTT-\r\n\r\nMeldungsaustausch. Die TTT-Identifier sind nicht für die „mündliche Kommunikation“\r\n\r\nvorgesehen, dies geschieht unverändert anhand der Zugnummer/OTN.\r\n\r\nFrage: Wird der TAF/P-Identifier (z. B. für Betriebsphase TR/0001/AB12345.../2026-12-29)\r\n\r\nab 12/2026 in der (Passenger)TrainComposition message P/TCM verpflichtend sein?\r\n\r\nAntwort: Die Angabe der ReferenceTrainID ist grundsätzlich verpflichtend, jedoch\r\n\r\nakzeptiert DB InfraGO in den betrieblichen TTT-Meldungen übergangsweise bis auf Weiteres\r\n\r\nauch Meldungen nur mit Angabe des OTN-Identifier (analog des aktuellen Verfahrens seit\r\n\r\n06/2025).\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 32",120,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":32,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","7ca759bac752eee85063a5062abee1e27fe7065af905ab02755d17d312afa345"],["chunk_b7389b5b2011603797006023","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",32,"Seite 33","6. Update KOMBau\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 33",12,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":33,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","751133b1a4899c0c6b94652cb585a6e9001a4e2d34db02e5d0708789a9ff5ece"],["chunk_c1c02f0cf4b04253d1c82c1f","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",33,"Seite 34","KOMBau – Kundentesttage und Einweisungen\r\n\r\nKundentesttage\r\n\r\n• Zum Testen des Front-Ends bieten wir 2-3 Kundentesttage an:\r\n\r\n• Pro Tag etwa sechs Session von je einer Stunde (Vergabe der Sessions nach First come,\r\n\r\nfirst served)\r\n\r\n• Einzelbetreuung der Kunden, um die Fragen direkt beantworten und das Feedback\r\n\r\nentgegennehmen zu können\r\n\r\n• Die Einladung zu den Kundentests wird in Kürze über eine Kundeninformation erfolgen\r\n\r\n• Vorgesehene Termine: in Abstimmung (vsl. Kw 20)\r\n\r\nEinweisungen für GPE und weitere Erklärvideos\r\n\r\n• Wie angekündigt, bieten wir auf Basis unserer Schulungsvideos auch zwei Einweisungen für\r\n\r\nden Umgang mit den neuen Planungsergebnissen und den Stellungnahmen an\r\n\r\n• Die Einladung zu den Einweisungen wird in Kürze über eine Kundeninformation erfolgen\r\n\r\n• Ergänzt werden die Einweisungen durch Sprechstunden zur Unterstützung der Nutzer zur\r\n\r\nKlärung von aufkommenden Fragen\r\n\r\n• weitere Erklärvideos zu BKE und BAE sind auf der KOMBau-Seite verfügbar\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 34",149,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":34,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","a7a3d1520cd96112775d887e8e779ff48af0b8e628a4fbdd40498059307375ab"],["chunk_43057a1b5c31642c42615c9e","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",34,"Seite 35","Hinweis zu Anfragen an die KOMBau\r\n\r\nART-KOM Support Adresse\r\n\r\n• Bitte den ARTKOM-Support [E-Mail-Adresse entfernt] anschreiben\r\n\r\n• Gerne themenspezifisch nach Konsultationsphasen getrennt, um die Anfragen besser\r\n\r\nbeantworten zu können\r\n\r\nMassenverarbeitung - Mehrfachstellungnahme\r\n\r\n• Umsetzung war für einen späteren Zeitpunkt vorgesehen\r\n\r\n• Zur Zeit werden die Möglichkeiten zum Vorziehen der Grundfunktionalität geprüft\r\n\r\n→ genauere Infos zum Planungsstand können wir zum nächsten TTT-Dialog liefern\r\n\r\nExport GPE\r\n\r\n• Wegen der vorhandenen TTT-Schnittstelle war ein Export der Planungsergebnisse\r\n\r\nursprünglich nicht vorgesehen\r\n\r\n• Die Anforderung wurde aufgenommen, ein Konzept dafür wird zur Zeit erstellt\r\n\r\n→ genauer Infos zum Planungsstand können wir zum nächsten TTT-Dialog liefern\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 35",109,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":35,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","9e196dd066dc277f135a2aa24cd47443c520619bbbc924c6ff3161e94d2ec535"],["chunk_7d539eaad9d7a83fbe1c0c3f","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",35,"Seite 36","7. ujBau Implementierungsdetails\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 36",12,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":36,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","1419261a017616ad27b77f19181bebdbc0b8ee0d1845f16b096f542890863faf"],["chunk_2540380b49983864a2cf8452","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",36,"Seite 37","Umgang mit fehlender BKE-ID in Fahrplanprodukten\r\n\r\nAusgangslage\r\n\r\nIn bestimmten Fällen (z.B. Havarie) ist keine BKE-ID\r\n\r\nvorhanden.\r\n\r\nFolgen\r\n\r\nDie Dokumente zur unterjährigen Baukonsultation sowie\r\n\r\ndas Vertragsdokument NAÄ werden ohne BKE-ID\r\n\r\nversendet.\r\n\r\nHinweis\r\n\r\nErkennung Bauherkunft durch FPE sichergestellt (FPE\r\n\r\nwerden nur im Bau- und Havariefall gesendet).\r\n\r\nFPE: Feinplanungsergebnis\r\n\r\nNAÄ: Netzausgelöste Änderung\r\n\r\nBKE: Baukapazitätseinschränkung\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 37",60,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":37,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","667776d190121a57094fded3e04faeccb9eabb050522ee6b4514089e8bfee396"],["chunk_8c2565b167d1204e0921e66f","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",37,"Seite 38","8. Fragen & Antworten\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 38",13,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":38,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","70ded24629b63e7d16b56308ff732f6c14f3789afde3b11a99e2f25bb1dc6b6d"],["chunk_550fcb8c61cc1529dd762f1e","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",38,"Seite 39","Zeit für Ihre Fragen!\r\n\r\nGerne beantworten wir Ihnen\r\n\r\nIhre Fragen direkt im Termin.\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 39",22,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":39,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","7eab037e979f8994ca39a7f64c9405b2b65ddc0444d8cc7ddb9bafc06ec7671b"],["chunk_00a6eee56d71fc6559343661","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",39,"Seite 40","9. Zum Nachlesen:\r\n\r\nNächste Termine & Antworten im Nachgang\r\n\r\nzum TTT-Dialog am 09.03.\r\n\r\nAlle Informationen immer aktuell unter:\r\n\r\nwww.dbinfrago.com/taf-tap-tsi\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 40",28,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":40,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","de135c88756987c57796dcbf242f4f5ae80f5dd56ebbf36d3ef535f1efa7d4b3"],["chunk_8f2c7ac793931f10f45af3f1","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",40,"Seite 41","Übersicht TAF/TAP TSI-Kommunikation\r\n\r\nArbeitsweise (A)/Turnus (T)\r\n\r\nTeilnehmer: Management & Experten aller EVU u. deren IT-Partner A: online\r\n\r\nTAF/TAP TSI\r\n\r\n1 Ziel: Überblick für GF-Ebene, allg. Infos (Betrieb + Fahrplan), zzgl. Vertiefung T: ca. monatlich\r\n\r\n-Dialog\r\n\r\naktueller Fokusthemen in Entwicklung/Testing Nächster Termin: 22.04.2026\r\n\r\nSprechstunde Teilnehmer: Alle künftigen Schnittstellenpartner (EVU, ZB) A: online\r\n\r\n2 Onboarding für Ziel: Informationen und Sprechstunde zum Onboarding der SST-Partner inkl. T: mittwochs - Details auf pathOS-\r\n\r\nSchnittstellenpartner Vorbereitung und Begleitung der Tests und Anbindung an die SST Homepage unter Kapitel 3)\r\n\r\nTAF/TAP TSI –\r\n\r\nTeilnehmer: Schnittstellenpartner Fahrplan, die bereits mit uns testen A: online\r\n\r\n3 Schnittstellen-\r\n\r\nZiel: Aktuelle Informationen/Entwicklungen; Sprechstunde, Updates T: nach Bedarf\r\n\r\npartner Fahrplan\r\n\r\nTeilnehmer: Alle künftigen Anwendenden von pathOS A: online\r\n\r\npathOS -\r\n\r\n3 Ziel: Erklärung der Grundlagen und wesentlichen Inhalte von pathOS in einzelnen T: seit 23.10. – Termine auf pathOS-\r\n\r\nSchulungen\r\n\r\ne\r\n\r\ng Terminen. Regelmäßige Sprechstunde startet am 22.01.26 Homepage (in Kapitel 2.4)\r\n\r\no\r\n\r\nla\r\n\r\ni D TAF/TAP TSI - Teilnehmer: Gesamtmarkt inkl. EIU A: online / in Präsenz\r\n\r\n5\r\n\r\nSektormeeting Ziel: nationale Spiegelgruppe TTT (Infos zu TTT, Verordnungen, ...) T: 4x jährlich, Nächster Termin: 27.03.\r\n\r\nA: in Präsenz\r\n\r\nRunder Tisch Bau Teilnehmer: 35 Mitglieder aus SPNV, SPV, SGV, BNetzA, Verbände, AT\r\n\r\n6 T: 4x p.a. + Arbeitsgruppe;\r\n\r\n(RTB) AG 3 Ziel: Beratung DB InfraGO bei Erarbeitung und Entwicklung für ujBau\r\n\r\nNächster Termin: 19.05.\r\n\r\nEVU-Informations- Teilnehmer: Gesamtmarkt\r\n\r\nA: online\r\n\r\n7 veranstaltung unter- Ziel: Information zum neuen unterjährigen Baufahrplanprozess mit neuen\r\n\r\nT: nach Bedarf, Nächster Termin: 27.03.",244,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":41,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","b1b8e1b257c482629caed6373ea0b8134065af08b1f34c908efab0f67825c235"]]');
