INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_41d5de7fcdf4792da3bd9e2b","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",41,"Seite 41","jähriger Bau Fahrplanprodukten und der digitalen BauFplo\r\n\r\nA: online\r\n\r\nTeilnehmer: Geschäftspartner mit G-INV\r\n\r\n8 BDV Nächster Termin: 08.04. (nur für\r\n\r\nZiel: Informationen, To-Dos vermitteln\r\n\r\nTeilnehmer des Kundentests)\r\n\r\no Homepage + Teilnehmer: für alle zugängliches Format, KI an Verteiler (inkl. IT-Partner, nicht alle EVU) A: Homepage\r\n\r\nf 9\r\n\r\nn Newsletter (KI) Ziel: aktuelle Informationen zum Nachlesen: Testing-Zugang, Ansprechpartner, Updates T: kontinuierlich\r\n\r\nI\r\n\r\nDB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 41",70,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":41,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","6f28f2c90ec94bc0ea61602f1fe3828fb3300497caf2d940e107798a05850a92"],["chunk_7047ccc45cd20c13f41f1d08","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",42,"Seite 42","Offene Punkte und Antworten (1/3)\r\n\r\nFrage Antwort DB InfraGO\r\n\r\nSollen Fahrzeuge fehlen, inhaltlich Für die Anmeldung neuer Triebfahrzeugbaureihen während der Trassenanmeldephase ist zwingend\r\n\r\nfalsch sein. Wo melden wir uns dazu, der offizielle Regelprozess gemäß Richtlinie 402 einzuhalten. Das bedeutet, dass Sie rechtzeitig vor\r\n\r\ndamit Fehler behoben werden? Abgabe der Trassenanmeldung einen formalen Antrag auf Aufnahme des Triebfahrzeugs in die Tfz-\r\n\r\nDatenbank stellen müssen, indem Sie das \"Anforderungsprofil für fahrdynamische\r\n\r\nTriebfahrzeugdaten\" (Vordruck 402.0202V05) bei der DB InfraGO AG einreichen. Nur über diesen\r\n\r\nWeg wird das Fahrzeug fahrdynamisch bewertet und offiziell in den Stammdaten des Bestellsystems\r\n\r\nhinterlegt, was Voraussetzung für die Nutzung in einer Trassenanmeldung ist.\r\n\r\nGleichzeitig ist es jedoch unterstützend sehr hilfreich, wenn Sie das Fehlen der benötigten Baureihe\r\n\r\nzusätzlich via Ticket melden. Diese parallele Information erleichtert die Nachverfolgung und hilft\r\n\r\nsicherzustellen, dass die erforderlichen Stammdaten rechtzeitig für Ihre konkreten Trassenentwürfe\r\n\r\nim System zur Verfügung stehen.\r\n\r\nDB InfraGO wird vor Ende der Anmeldefrist ein zusätzliches Stammdatenupdate bereitstellen. Damit\r\n\r\nIhre benötigten Baureihen in dieses Update einfließen können, ist eine Meldung fehlender\r\n\r\nTriebfahrzeuge (TFZ) bis spätestens 31.03.2026 erforderlich. Dieses Vorgehen ersetzt nicht den\r\n\r\noffiziellen Regelprozess gemäß Richtlinie 402, unterstützt aber die fristgerechte Bereitstellung der\r\n\r\nStammdaten.\r\n\r\nDB InfraGO AG | Follow-up: TAF/TAP TSI-Dialog am 09.03.2026 ​ 42",203,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":42,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","4abf7691c402bdd664c23c05aa1a700966ef2244dbff86cd3c08d00e85231cd3"],["chunk_52d96ea6a3208f65eef6aa88","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",43,"Seite 43","Offene Punkte und Antworten (2/3)\r\n\r\nFrage Antwort DB InfraGO\r\n\r\nWann wird es denn überhaupt möglich Es gibt aktuell einen Defect im pathOS Webportal, der die Angabe des durchführenden EVU am\r\n\r\nsein, die „synthetische“ Handoverpunkt stört. Dieser wird bis zum 18.03.2026 behoben. Bitte bestellen Sie betroffene\r\n\r\nKundennummer für die Grenzstrecke Trassen ab diesem Datum.\r\n\r\nim Ausland anzugeben?\r\n\r\nAktualisierung: Der Defect ist seit dem 18.03.2026 behoben.\r\n\r\nDB InfraGO AG | Follow-up: TAF/TAP TSI-Dialog am 09.03.2026 ​ 43",75,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":43,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","9bb9c45b6121eb9782ad1b30ab98d56219c621a847463684b0b2477f2fd30022"],["chunk_d79e23ea05d4c4b723193117","wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md",44,"Seite 44","Offene Punkte und Antworten (3/3)\r\n\r\nFrage Antwort DB InfraGO\r\n\r\nHinweis auf abweichende Die TCM/PTCM muss an das jeweils betrieblich verantwortliche EIU für den jeweiligen\r\n\r\nTrainCompositionMessage / Streckenabschnitt geschickt werden. Ferner sind die Inhalte der TCM/PTCM für die Disposition\r\n\r\nProbleme bei TCM-Trassen- relevant und müssen der InfraGO daher für den Bereich vorliegen, in dem sie die Disposition für den\r\n\r\nZuordnung: In Fällen, in denen die Zug übernimmt. Daher wird diese von Netzgrenze bis Netzgrenze an die DB InfraGO geschickt.\r\n\r\nFahrplanbearbeitungsgrenze im\r\n\r\nAusland liegt, enthält die PDM der\r\n\r\nInfraGO einen ausländischen\r\n\r\nAbschnitt, während die TCM an das\r\n\r\nausländische EIU geschickt werden\r\n\r\nmuss.\r\n\r\nDB InfraGO AG | Follow-up: TAF/TAP TSI-Dialog am 09.03.2026 ​ 44",111,"{\"canonical_url\":null,\"normalized_sha256\":\"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692\",\"page\":44,\"source_id\":\"src_3144bf05b4098f1b3f75\",\"source_sha256\":\"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008\",\"source_version_id\":\"sv_44fe2d3163612d9c0a1e9803\"}","0b387166df6fb4b23c7d8f90e78efa1c642cd7c11d5dfe8bb08dc3c138a39fe0"],["chunk_a0d037cddc9c68f73211d51b","wiki/sources/taf-tap-tsi-faq.md",0,"Inhalt","Bitte beachten Sie, dass sich Inhalte und Zeitpläne beispielsweise durch übergreifende regulatorische Anforderungen (z. B. TAF/TAP TSI oder weitere EU-Verordnungen) sowie durch technische oder fachliche Anpassungen ändern können. Die hier bereitgestellten Informationen dienen der Orientierung und haben keinen verbindlichen Charakter.\r\n\r\nVerbindliche Regelungen und offizielle Informationen entnehmen Sie bitte den jeweils zugrunde liegenden Dokumenten, wie beispielsweise den EU-Verordnungen, dem Sektorhandbuch, der DB InfraGO-Schnittstellendokumentation oder den Informationen auf der Webseite der DB InfraGO AG.\r\n\r\nZur besseren Übersicht sind die Fragen thematisch gruppiert. Aufgrund des Umfangs empfehlen wir die Nutzung der Suchfunktion (Strg + F), um gezielt nach Themen zu navigieren.",98,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/netzzugang-und-regulierung/taf-tap-tsi/TAF-TAP-TSI-FAQ-13868920\",\"normalized_sha256\":\"97bc3bb746068822730652b85d950b631a9901e1f53d4728d99bef285fb45739\",\"page\":null,\"source_id\":\"src_41228a549ad00f141eea\",\"source_sha256\":\"001147e3eec4df3b47c092cac0b059cf11d3ef1aa86dbcd443f452d502fe8314\",\"source_version_id\":\"sv_a6f59414e6ebc1e04ca2c673\"}","21c0a29065274889487ad263b3fb9f182de50e0ff1fa9492e9b1d48399b143da"],["chunk_4f2bca48d27bef5227b5fc84","wiki/sources/taf-tap-tsi-faq.md",1,"1\\. Übergreifende Themen zu den EVU-Verordnungen","Müssen auch kleinere EVU TAF/TAP umsetzen?\r\n\r\nDie Umsetzung von TAF/TAP ist unabhängig von der Größe eines EVU. Sofern ein EIU, über dessen Netz ein EVU fahren möchte, TAF/TAP umsetzt und das in seinen Nutzungsbedingungen verankert, sind alle EVU gezwungen, TAF/TAP umzusetzen.",41,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/netzzugang-und-regulierung/taf-tap-tsi/TAF-TAP-TSI-FAQ-13868920\",\"normalized_sha256\":\"97bc3bb746068822730652b85d950b631a9901e1f53d4728d99bef285fb45739\",\"page\":null,\"source_id\":\"src_41228a549ad00f141eea\",\"source_sha256\":\"001147e3eec4df3b47c092cac0b059cf11d3ef1aa86dbcd443f452d502fe8314\",\"source_version_id\":\"sv_a6f59414e6ebc1e04ca2c673\"}","840494c4fff245ea181da31633102dd8d9f63a77ff9981c11f875b0375549a22"],["chunk_50e635e3356a6bf666216f34","wiki/sources/taf-tap-tsi-faq.md",2,"2\\. Identifikatoren und Objekte","Gibt es noch so etwas wie Kundennummern und in welchem TAF/TAP-Objekt stecken diese? Hintergrund: bisher unterscheiden einige EVU Linien mit den zugehörigen Zügen nach Kundennummer\r\n\r\nDie Kundennummern-Logik der DB InfraGO wird mit der Einführung von TAF/TAF TSI im Fahrplan 2027 nicht geändert. Diese Informationen stecken allerdings formal in keinem TAF/TAP Objekt, sondern sind ein zusätzlicher Parameter in Deutschland bei der DB InfraGO AG.\r\n\r\nIst die ReferenceTrainID die interne Referenznummer der EVU, die vom EIU übernommen wird? Werden Zugnummern damit obsolet?\r\n\r\nDie ReferenceTrainID ist ein Element der EVU und wird vom EIU übernommen - das stimmt. Zugnummern wird es weiterhin geben, nur heißen diese künftig OTN, sind aber weitestgehend wie heute. Die ReferenceTrainID ist allerdings die durchgängige Identifikation und somit in keiner Weise eine reine \"interne\" Referenznummer.\r\n\r\nKann/sollte eine ReferenceTrainID mehrfach vergeben werden, wenn z.B. ein Zuglauf abgeändert wird oder gestrandet ist und ist das z.B. auch für 20h-Bestellungen verwendbar zur besseren Identifikation?\r\n\r\nGenerell kann eine ReferenceTrainID mehrmals verwendet werden, allerdings muss sie immer je Verkehrstag eindeutig sein. Wird sie wiederholt verwendet, so müssen die zugehörigen Anmeldungen „zusammengehören“ (hinsichtlich Zug, Route, Zeiten etc.) und kein Verkehrstag darf doppelt vorkommen.\r\n\r\nKann die ReferenceTrainID auch grenzüberschreitend genutzt werden bzw. sollte es ggf. sogar? Wie sieht es EVU-übergreifend aus an z.B. Übergabepunkten?\r\n\r\nJa, sie soll auch grenzüberschreitend genutzt werden. Das federführende EVU (LeadRU) legt ReferenceTrainID und RouteID fest und kommuniziert sie an die Partner-EVU, welche diese dann wiederum in den entsprechenden Anmeldesystemen angeben müssen.",240,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/netzzugang-und-regulierung/taf-tap-tsi/TAF-TAP-TSI-FAQ-13868920\",\"normalized_sha256\":\"97bc3bb746068822730652b85d950b631a9901e1f53d4728d99bef285fb45739\",\"page\":null,\"source_id\":\"src_41228a549ad00f141eea\",\"source_sha256\":\"001147e3eec4df3b47c092cac0b059cf11d3ef1aa86dbcd443f452d502fe8314\",\"source_version_id\":\"sv_a6f59414e6ebc1e04ca2c673\"}","569013ae88332690cccfbe3df7e69248bf6dc459f7996c0422ae53ab20a1ed21"],["chunk_8bab3e77a93a668924550a7b","wiki/sources/taf-tap-tsi-faq.md",3,"3\\. Stammdaten","Wo sind die aktuellen Infrastrukturstammdaten zu finden?\r\n\r\nDie aktuellen Stammdaten sind unter folgendem Link auf unserer Webseite abrufbar: [Fahrplan: EVU-Schnittstelle](https://www.dbinfrago.com/web/schienennetz/netzzugang-und-regulierung/taf-tap-tsi/evu_schnittstelle-11089208)\r\n\r\nKann bzw. muss jedes EVU einen Company Code/Organisation Code beantragen?\r\n\r\nJa. Bis zum 31.12.2025 ist für den TAF/TAP-Nachrichtenaustausch für jedes beteiligte Unternehmen zwingend ein Company Code erforderlich. Dieser kann ohne großen Aufwand und derzeit kostenfrei bei der UIC beantragt werden. Ab dem 1.1.2026 wird die ERA diese Aufgabe übernehmen und der Company Code durch den Organisation Code ersetzt. Alle Telematics Stakeholder, die vor dem 01.01.2026 einen Company Code besitzen, müssen bei der ERA oder noch besser über das EBA einen gleichlautenden Organisation Code beantragen. Unternehmen des deutschen Eisenbahnsektors, die bisher weder über einen Company Code noch über einen Organisation Code verfügen, beantragen bitte bis zum 01.01.2026 einen Organisation Code, entweder über die ERA oder das EBA. Über folgenden Link kann der Antrag bei der ERA gestellt werden: [Antrag ERA](https://www.era.europa.eu/domains/registers/ocr_en).\r\n\r\nÜber folgenden Link kann der Antrag beim EBA gestellt werden: [Antrag EBA](https://www.eba.bund.de/DE/Themen/Fahrzeugeinstellungsregister/OCR/ocr_node.html)",161,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/netzzugang-und-regulierung/taf-tap-tsi/TAF-TAP-TSI-FAQ-13868920\",\"normalized_sha256\":\"97bc3bb746068822730652b85d950b631a9901e1f53d4728d99bef285fb45739\",\"page\":null,\"source_id\":\"src_41228a549ad00f141eea\",\"source_sha256\":\"001147e3eec4df3b47c092cac0b059cf11d3ef1aa86dbcd443f452d502fe8314\",\"source_version_id\":\"sv_a6f59414e6ebc1e04ca2c673\"}","14d284d6d8b7dfbaa43c4753d0a270de141ad9dbbc38d0f9372e3184836837dc"],["chunk_02bc4cdb3eaddbd818ded227","wiki/sources/taf-tap-tsi-faq.md",4,"3\\. Stammdaten","Wir empfehlen Ihnen dringend die Beantragung über das EBA, da Sie einen direkten Ansprechpartner mit Kommunikation in deutscher Sprache haben, der Sie in allen Belangen unterstützt. Besondere Aufmerksamkeit gilt für die EVUs. Sind Sie EVU und beantragen die Angleichung Ihres Organisation Codes an den Company Code, dann müssen Sie nach Anpassung des Organisation Code auch die Einträge im Nationalen und Europäischen Fahrzeugeinstellungsregister (NVR/EVR) aktualisieren.\r\n\r\nAnschließend muss der Company Code/Organisation Code an die Eisenbahninfrastrukturunternehmen gemeldet werden. Im Falle einer Angleichung des Organisation Code an den Company Code muss keine Meldung erfolgen, da der bisher unter dem Namen Company Code hinterlegte Code gleichbleibt. Bei der DB InfraGO bitte direkt an die Kundenberatung melden. Mehr kann im aktuellen Flyer auf der Informationsplattform nachgelesen werden.\r\n\r\nLeider gibt es weiterhin eine hohe Anzahl an EVU, die entweder keinen Company Code/Organisation Code haben oder diesen noch nicht an die DB InfraGO gemeldet haben. Da der Company Code/Organisation Code mit TAF/TAP ein verpflichtendes Element wird, ist es nicht zielführend, diesen aus (persönlichen) Gründen zu verweigern. Mit Einführung von TAF/TAP wird der Company Code/Organisation Code voraussichtlich via INB als Pflicht-Element im G-INV verankert.\r\n\r\nKönnen einem Company Code mehrere der heutigen Kundennummern zugeordnet sein? So, wie ein EVU heute verschiedene Kundennummern für die Trassenanmeldung nutzen kann?",207,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/netzzugang-und-regulierung/taf-tap-tsi/TAF-TAP-TSI-FAQ-13868920\",\"normalized_sha256\":\"97bc3bb746068822730652b85d950b631a9901e1f53d4728d99bef285fb45739\",\"page\":null,\"source_id\":\"src_41228a549ad00f141eea\",\"source_sha256\":\"001147e3eec4df3b47c092cac0b059cf11d3ef1aa86dbcd443f452d502fe8314\",\"source_version_id\":\"sv_a6f59414e6ebc1e04ca2c673\"}","b1b1844a9f98bbe18b5f324751846a42336922cd6cef4b46837456d5d3d4aac3"],["chunk_7eb93be67ab57a4c21d85a79","wiki/sources/taf-tap-tsi-faq.md",5,"3\\. Stammdaten","Ja - der Company Code ist ein vorgegebenes Element der TAF/TAP bzw. EU-Vorgaben. Jedes EVU (bzw. jedes Unternehmen), was an TAF/TAP beteiligt ist, benötigt zwingend (!) einen solchen Code. Die Kundennummern-Logik ist DB InfraGO-eigen. In der Regel gibt es je EVU/ZB eine Hauptkundennummer (für die es dann einen Company Code gibt) mit untergeordneten Kundennummern. Diese Kundennummern können gemeinsam den Company Code der Hauptkundennummer verwenden.\r\n\r\nWird der Company Code/Organisation Code bei einem Betreiberwechsel automatisch an den neuen Betreiber übertragen oder muss dieser neu beantragt/vergeben werden?\r\n\r\nKommt es zu einem Betreiberwechsel, gilt der Organisation Code des neuen Betreibers.\r\n\r\nVerfügt ein neuer Betreiber weder über den alten Company Code noch über den neuen Organisation Code, muss er bei der ERA oder dem EBA einen Organisation Code beantragen. Dabei empfehlen wir Ihnen die Antragstellung über das EBA vorzunehmen, da dies folgende Vorteile hat:\r\n\r\n- Unterstützung durch Mitarbeiter des EBA\r\n- Antragsstellung aus einer Hand\r\n- Geringerer administrativer Aufwand für den Antragssteller\r\n- Schnellere Bearbeitung\r\n\r\nSofern ein Betreiber bisher noch keinen Code hatte, kann er einen alphanumerischen Organisation Code beziehen.\r\n\r\nHat ein neuer Betreiber bereits einen Company Code aber keinen Organisation Code, muss er bei der ERA oder dem EBA einen dem Company Code gleichlautenden Organisation Code beantragen.\r\n\r\nSollte ein neuer Betreiber über einen Company Code und einen abweichenden Organisation Code verfügen, muss er den bestehenden Organisation Code löschen lassen und einen dem Company Code gleichlautenden Organisation Code bei der ERA oder dem EBA beantragen.",240,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/netzzugang-und-regulierung/taf-tap-tsi/TAF-TAP-TSI-FAQ-13868920\",\"normalized_sha256\":\"97bc3bb746068822730652b85d950b631a9901e1f53d4728d99bef285fb45739\",\"page\":null,\"source_id\":\"src_41228a549ad00f141eea\",\"source_sha256\":\"001147e3eec4df3b47c092cac0b059cf11d3ef1aa86dbcd443f452d502fe8314\",\"source_version_id\":\"sv_a6f59414e6ebc1e04ca2c673\"}","10640e62a09f9f7ceab4ba8e6ab42d01374797035512db5e9d5027bb5f5c45f5"],["chunk_8d04c2031581f61ca702ff76","wiki/sources/taf-tap-tsi-faq.md",6,"3\\. Stammdaten","Verfügt ein neuer Betreiber bereits über gleichlautende Codes (Company und Organisation Code stimmen überein), muss er nichts beantragen und es gilt der bestehende Organisation Code.\r\n\r\nKönnen weiterhin die bisherigen Bezeichnungen und Ril100-Codes bzw. DS100 Codes genutzt werden?\r\n\r\nIm Webportal von pathOS können die Laufwegspunkte auch mit Ril100-Code oder dem Klarnamen angegeben werden und werden automatisch dem PLC zugeordnet. Wer eine Schnittstellenlösung entwickelt, muss hingegen den PLC als eindeutigen Schlüssel verwenden. Die zusätzliche Angabe des Klarnamens in der Schnittstelle erleichtert die Lesbarkeit der xml-Datei, ist aber nicht unbedingt erforderlich.",88,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/netzzugang-und-regulierung/taf-tap-tsi/TAF-TAP-TSI-FAQ-13868920\",\"normalized_sha256\":\"97bc3bb746068822730652b85d950b631a9901e1f53d4728d99bef285fb45739\",\"page\":null,\"source_id\":\"src_41228a549ad00f141eea\",\"source_sha256\":\"001147e3eec4df3b47c092cac0b059cf11d3ef1aa86dbcd443f452d502fe8314\",\"source_version_id\":\"sv_a6f59414e6ebc1e04ca2c673\"}","a35337f204bf78e6267a29e1de26a34769d6247d548de00290da1fd7cf20aac2"],["chunk_ffa28d4bab0e47e0cfc80d63","wiki/sources/taf-tap-tsi-faq.md",7,"4\\. Trassenanmeldung allgemein","Wie weit (zeitlich, fachlich, prozessual) reicht der Kanalzwang?\r\n\r\nBei einer Trassenbestellung über das Webportal oder via Formular (Vordruck nach Ril 402.0202A01-A03) erfolgt keine Kommunikation über die PathOS Schnittstelle. Man muss sich die InfraGO-Angebote aus dem Portal manuell holen bzw. eine OIM (ObjectInfoMessage) exportieren. Wenn der Trassenbestellprozess so gestartet wurde, erfolgt prozessual bis zum Trassennutzungsvertrag keine Kommunikation über die PathOS Schnittstelle (ausgenommen KOMBau).\r\n\r\nWürde eine Netzausgelöste Änderung nach Vertrag dann wieder über die Schnittstelle kommen?\r\n\r\nDer Kanalzwang gilt bis zum Abschluss des jeweiligen Prozesses; bei einer über das Portal initiierten Trassenbestellung bis zum Vertragsschluss. Währenddessen erfolgt die Kommunikation ausschließlich über den Startkanal. Nach Vertragsschluss werden netzausgelöste Änderungen (NAÄ) initial parallel über CI und Portal bereitgestellt (sofern ein CI existiert). Der weitere NAÄ-Prozess richtet sich nach Ihrer ersten Reaktion: Reagieren Sie über das CI (z. B. per RCM), wird der Prozess über das CI fortgeführt; andernfalls über das Portal. Unabhängig davon erfolgt die Kommunikation zu GPE und FPE grundsätzlich ohne Kanalzwang; eine Reaktion ist jederzeit entweder über das CI oder über die KomBau möglich.\r\n\r\nWird Click & Ride mit Einführung von TAF/TAP weitergeführt?\r\n\r\nJa. Click & Ride wird künftig für TAF/TAP ertüchtigt. Am generellen Anwendungsfall für C&R ändert sich durch die TAF/TAP Einführung nichts. Für das Fahrplanjahr 2025 und 2026 bleibt Click&Ride parallel zu TPN als Eingangskanal verfügbar.\r\n\r\nBis wann kann TPN für GelV 2026 noch genutzt werden?\r\n\r\nTPN bleibt bis zum Fahrplanwechsel am 13.12.2026 produktiv für GelV verfügbar.",237,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/netzzugang-und-regulierung/taf-tap-tsi/TAF-TAP-TSI-FAQ-13868920\",\"normalized_sha256\":\"97bc3bb746068822730652b85d950b631a9901e1f53d4728d99bef285fb45739\",\"page\":null,\"source_id\":\"src_41228a549ad00f141eea\",\"source_sha256\":\"001147e3eec4df3b47c092cac0b059cf11d3ef1aa86dbcd443f452d502fe8314\",\"source_version_id\":\"sv_a6f59414e6ebc1e04ca2c673\"}","747e3cc5826ec589de6601bc43b151c835b0b1eaf43416629a8177a29736496a"],["chunk_e1ab311730a36236c34ae2b7","wiki/sources/taf-tap-tsi-faq.md",8,"4\\. Trassenanmeldung allgemein","Legt man im PlannedCalendar fest, ob es sich um Regeltrassen oder Ad-hoc Trassen handelt?\r\n\r\nNein. Ob es sich um einen Regel- oder Sonderzug handelt, ergibt sich aus dem Bestellzeitpunkt und den bestellten Verkehrstagen. Daher muss das EVU dies nicht gesondert angeben.\r\n\r\nWie stellt man den Bezug von Zug und Gegenzug her? Beispiel: ein EVU will 3x von A nach B und zurück fahren mit jeweils 15 Min. Aufenthalt, dann stehen diese Trassen in Bezug zueinander?\r\n\r\nMan kann auf eine Vor- oder Nachleistung referenzieren. Dies geschieht über die TrainActivityCodes 0044 bzw. 0045. Sie können dabei über die OTN oder die TrainID auf den anderen Zug verweisen.\r\n\r\nBetrifft die Umstellung von TAF/TAP TSI auch die Trassenabrechnung? Verändern sich dadurch Dateiformate (heute CSV) und Inhalte?\r\n\r\nIn den Abrechnungssystemen wird aktuell der Umgang mit den neuen Identifikatoren geprüft.\r\n\r\nGanz grob gesprochen soll die Abrechnung mit Attributen aus TAF/TAP TSI erweitert und eventuell vorhandene Attribute durch die jeweiligen neuen ausgetauscht werden. Das trifft zum einen unsere internen Systeme aber auch die CSV-Dateien. Grundsätzlich werden wir erstmal die Dateien weiter im CSV-Format verwenden, analog zu heute.\r\n\r\nPerspektivisch gibt es die Idee mit der Umstellung der Abrechnung auf TAF/TAP TSI künftig die Abrechnungsdaten komfortabel in einem Webportal zur Verfügung zu stellen. Der Zeitpunkt der Umsetzung ist aber offen, das aktuelle LB-Portal bleibt also weiterhin der gewohnte Kanal.",220,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/netzzugang-und-regulierung/taf-tap-tsi/TAF-TAP-TSI-FAQ-13868920\",\"normalized_sha256\":\"97bc3bb746068822730652b85d950b631a9901e1f53d4728d99bef285fb45739\",\"page\":null,\"source_id\":\"src_41228a549ad00f141eea\",\"source_sha256\":\"001147e3eec4df3b47c092cac0b059cf11d3ef1aa86dbcd443f452d502fe8314\",\"source_version_id\":\"sv_a6f59414e6ebc1e04ca2c673\"}","59a39f581ecddbf2bf20e481f74b975ba079d100977558fa6607d1856a87c65f"],["chunk_af1b9651b6bd508d6ffa509e","wiki/sources/taf-tap-tsi-faq.md",9,"5\\. Common Interface / Schnittstelle","Wenn mehrere Kundennummern demselben Company Code zugewiesen sind, können diese Kunden dann dasselbe Common Interface verwenden? Gibt es eine gute Möglichkeit die Nachrichten dann im Common Interface nach Kundennummer zu routen?\r\n\r\nAuch hier gilt, generell können mehrere Kundennummern einen Company Code verwenden (z.B. wenn diese in der DB InfraGO-Logik einer Hauptkundennummer zugeordnet sind).\r\n\r\nEin Common Interface ist immer auf Ebene Company Code angelegt und kann dementsprechend auch von mehreren Kundennummern verwendet werden (gilt dann auch für die entsprechenden Softwares).\r\n\r\nDB InfraGO-seitig routen wir auf Ebene Company Code, d.h. bei uns wird EIN Empfänger je Company Code hinterlegt. Ein Routing nach Kundennummern sollte dann entsprechend auf Kundenseite (im CI bzw. nach dem CI) erfolgen.\r\n\r\nIst es richtig, dass ujBau-Nachrichten ausschließlich über das Fahrplan-CI eines EVU (und nicht etwa über das CI für operativen Betrieb) gesendet werden?\r\n\r\nDie Nachrichten für den Prozess zum unterjährigen Bau erfolgen nur über das Fahrplan-CI. Im Anschluss an den Bauprozess erfolgt die Aktualisierung des Vertrages dann über pathOS, es bleibt also bei dem gleichen CI. Der Versand der Nachrichten zum unterjährigen Bau erfolgt nicht über das CI des operativen Betriebs.\r\n\r\nWie werden die neuen betrieblichen Nachrichten von einem EVU technisch an die DB InfraGO AG übermittelt?\r\n\r\nDiese Meldungen werden vom Common Interface des EVU an das Common Interface (Betriebsdatenverteiler, BDV) der DB InfraGO gesendet. Dies sind die gleichen Schnittstellen, die auch bei TAF/TAP-Meldungen von DB InfraGO an die EVU genutzt werden - nur eben in umgekehrter Richtung.",240,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/netzzugang-und-regulierung/taf-tap-tsi/TAF-TAP-TSI-FAQ-13868920\",\"normalized_sha256\":\"97bc3bb746068822730652b85d950b631a9901e1f53d4728d99bef285fb45739\",\"page\":null,\"source_id\":\"src_41228a549ad00f141eea\",\"source_sha256\":\"001147e3eec4df3b47c092cac0b059cf11d3ef1aa86dbcd443f452d502fe8314\",\"source_version_id\":\"sv_a6f59414e6ebc1e04ca2c673\"}","6f1064644897e9bc5f47ff9d23af5a5fd7529e81126647ae5521f7cb0fc1f0dd"],["chunk_e000cc14aea62cc0d8dad532","wiki/sources/taf-tap-tsi-faq.md",10,"6\\. pathOS Webportal","Gibt es die Möglichkeit im Webportal Vorlagen (Muster) abzuspeichern und für eine neue Trassenanmeldung zu nutzen?\r\n\r\nJa, das neue Onlineportal hat selbstverständlich eine Entwurfsfunktion. Diese Entwürfe können auf verschiedene Wege erstellt werden: Über eine neue, leere Anmeldung, aus bestehenden Entwürfen, aus abgeschickten Anmeldungen, aus Verträgen oder aus dem Archiv. Prinzipiell kann aus jedem Vorgang in Sekunden eine Vorlage erstellt werden.",60,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/netzzugang-und-regulierung/taf-tap-tsi/TAF-TAP-TSI-FAQ-13868920\",\"normalized_sha256\":\"97bc3bb746068822730652b85d950b631a9901e1f53d4728d99bef285fb45739\",\"page\":null,\"source_id\":\"src_41228a549ad00f141eea\",\"source_sha256\":\"001147e3eec4df3b47c092cac0b059cf11d3ef1aa86dbcd443f452d502fe8314\",\"source_version_id\":\"sv_a6f59414e6ebc1e04ca2c673\"}","b85636d563da4f3d1b9e8598e796185302284c1de20a8cf98be72e64973af732"],["chunk_10843acd986f8ed5c30c8f12","wiki/sources/taf-tap-tsi-faq.md",11,"7\\. Kundensupport","Zu welchen Zeiten ist die Telefonhotline +49 69 26515555 erreichbar?\r\n\r\nUnser fachliches Support-Team von pathOS steht Montag bis Freitag zwischen 8 Uhr und 16:30 Uhr zur Verfügung. Danach erfolgt eine Weiterleitung auf ein anderes Supportteam, sodass wir Ihre Anliegen auch außerhalb dieser Zeiten aufnehmen können und bspw. auf IT-Ausfälle reagieren können.",51,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/netzzugang-und-regulierung/taf-tap-tsi/TAF-TAP-TSI-FAQ-13868920\",\"normalized_sha256\":\"97bc3bb746068822730652b85d950b631a9901e1f53d4728d99bef285fb45739\",\"page\":null,\"source_id\":\"src_41228a549ad00f141eea\",\"source_sha256\":\"001147e3eec4df3b47c092cac0b059cf11d3ef1aa86dbcd443f452d502fe8314\",\"source_version_id\":\"sv_a6f59414e6ebc1e04ca2c673\"}","da911a2cfc6d2b3c6bb245d254aec173c2ef15798a8c0a5882587b76024b40fb"],["chunk_7c4790372dc83181168fb6e7","wiki/sources/trassenanmeldung-im-gelegenheitsverkehr.md",0,"Inhalt","Bei Anmeldungen zum Gelegenheitsverkehr handelt es sich um:\r\n\r\n- Anmeldungen außerhalb des Netzfahrplans bzw. außerhalb der Fristen des Netzfahrplans\r\n- Änderungsanmeldungen zu Trassen des Netzfahrplans\r\n- Änderungsanmeldungen zu Trassen des Gelegenheitsverkehrs\r\n\r\nTrassen für den Gelegenheitsverkehr werden im Rahmen der vorhandenen freien Kapazitäten der Infrastruktur konstruiert.\r\n\r\nUm eine hochwertige, den Ansprüchen der Kund:innen genügende Trasse zu konstruieren, bedarf es detaillierter Angaben in der Trassenanmeldung wie zum Beispiel dem vorgesehenen Fahrzeugeinsatz, dem gewünschten Verkehrszeitraum und dem geplanten Fahrtverlauf.\r\n\r\nDie DB InfraGO AG stellt für die Trassenanmeldung das **Trassenportal Netz (TPN)** zur Verfügung, das über eine Schnittstelle an interne IT-Systeme angebunden und auch aus dem Internet zugänglich ist. Die Nutzung des elektronischen Datenaustauschs ist zwischen der DB InfraGO AG und den Zugangsberechtigten zu vereinbaren.\r\n\r\nTrassenanmeldungen und alle zugehörigen Folgeaufträge müssen über TPN erfolgen. Fragen rund um TPN beantworten Ihnen gerne unsere Ansprechpartner:innen in den Regionen. Weitere Informationen finden Sie auch [hier](https://preview-ecm.intranet.deutschebahn.com/blueprint/servlet/infra/schienennetz/leistungen/trassen/Trassenbestellung/Trassenanmeldung/trassenportal_netz-11249618 \"Wird in einem neuen Tab geöffnet\") im Internet. Im Fall des technischen Ausfalls bzw. im Fall von Übertragungsstörungen des Systems TPN oder im Fall eines nicht verfügbaren IT-Systems beim Antragsteller können Trassenanmeldungen per E-Mail oder Fax unter Verwendung des jeweils gültigen Anmeldeformulars erfolgen.",191,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/gelegenheitsverkehr-10907274\",\"normalized_sha256\":\"1f4ac919ba695429e938615de28752003e54d04b09802cfdd71f8cd019811c9d\",\"page\":null,\"source_id\":\"src_a84dc841278f39fe70cc\",\"source_sha256\":\"e50d6d625061099073b4a3ed0a0f661a658aac0ab369daaeadca08b09775c4a7\",\"source_version_id\":\"sv_778cf7ecc04d4171056d4583\"}","5690a2e4bd848fd596d4c8c7f93c3a2b1b08c993184945c6865e49857579eee1"],["chunk_7a8af2bce3efe1fc8750be8e","wiki/sources/trassenanmeldung-im-gelegenheitsverkehr.md",1,"Inhalt","Die für diesen Fall verbindlichen Anmeldeformulare und Leitfäden stehen nachfolgend zum Download zur Verfügung. Mündliche oder fernmündliche Trassenanmeldungen sind in allen Fällen ausgeschlossen.\r\n\r\nFolgende Anmeldeformulare und Leitfäden für die Trassenanmeldung im Gelegenheitsverkehr stehen zum Download zur Verfügung:\r\n\r\n- Erläuterungen zu den Trassenanmeldungen finden Sie in der (Richtlinie 402.0202)\r\n- Leitfaden für die **Trassenanmeldung Gelegenheitsverkehr** (Ril 402.0202A02)\r\n- Leitfaden für die **Trassenanmeldung Netzfahrplan** (Ril 402.0202A01)\r\n- Leitfaden für **Trassenanmeldung Baufahrzeuge / Nebenfahrzeuge** (Ril 402.0202A03)\r\n- Leitfaden für die **Bremsstellung von Zügen** (Ril 402.0202A04)\r\n- **Vordruck Anmeldung zum Gelegenheitsverkehr** (Ril 402.0202V02)\r\n- **Vordruck Anmeldung zum Netzfahrplan** (Ril 402.0202V01)\r\n- **Vordruck Anmeldung von Baumaschinen und sonstigen Nebenfahrzeugen** (Ril 402.0202V03)\r\n- **Vordruck Anmeldung von außergewöhnlichen Transporten mit Bza-Nr.** (Ril 402.0202V04)\r\n- **Vordruck Anforderungsprofil für Fahrdynamische Triebfahrzeugdaten** (Ril 402.0202V05)\r\n\r\nSie finden die Downloads auf der Seite [*Anmeldeformulare*](https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/formulare-10907276).",132,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/gelegenheitsverkehr-10907274\",\"normalized_sha256\":\"1f4ac919ba695429e938615de28752003e54d04b09802cfdd71f8cd019811c9d\",\"page\":null,\"source_id\":\"src_a84dc841278f39fe70cc\",\"source_sha256\":\"e50d6d625061099073b4a3ed0a0f661a658aac0ab369daaeadca08b09775c4a7\",\"source_version_id\":\"sv_778cf7ecc04d4171056d4583\"}","e20bcea054348eb86c0f4c58192326565435df65d6016ef3acc8b9daee4b73e1"],["chunk_e820dee74632576c0eb649bc","wiki/sources/trassenanmeldung-im-netzfahrplan.md",0,"Inhalt","Die DB InfraGO AG konstruiert die Trassen des Netzfahrplans auf der Basis von Trassenanmeldungen. Um eine hochwertige, den Ansprüchen der Kund:innen genügende Trasse zu konstruieren, bedarf es detaillierter Angaben wie zum Beispiel dem vorgesehenen Fahrzeugeinsatz, dem gewünschten Verkehrszeitraum und dem geplanten Fahrtverlauf.\r\n\r\nDie jeweilige Trassenanmeldefristen für die Netzfahrpläne sind in Ziffer 4.2 der Infrastrukturnutzungsbedingungen (INB) genannt.\r\n\r\nDie DB InfraGO AG stellt für die Trassenanmeldung das Trassenanmeldesystem pathOS zur Verfügung, das über eine Schnittstelle an interne IT-Systeme angebunden und auch aus dem Internet zugänglich ist. Die Nutzung des elektronischen Datenaustauschs ist zwischen der DB InfraGO AG und den Zugangsberechtigten zu vereinbaren.\r\n\r\nTrassenanmeldungen und im Rahmen der Zuweisung erforderliche Angaben bzw. Handlungen im Netzfahrplan i. S. d. der INB müssen über pathOS erfolgen. Insbesondere im Fall des technischen Ausfalls bzw. im Fall von Übertragungsstörungen des Systems oder im Fall eines nicht verfügbaren IT-Systems beim Antragsteller können Trassenanmeldungen per E-Mail unter Verwendung des jeweils gültigen Anmeldeformulars erfolgen.\r\n\r\nDie für diesen Fall verbindlichen Anmeldeformulare und Leitfäden stehen nachfolgend zum Download zur Verfügung. Mündliche oder fernmündliche Trassenanmeldungen sind in allen Fällen ausgeschlossen.\r\n\r\nFolgende Anmeldeformulare und Leitfäden stehen für die Trassenanmeldung im Netzfahrplan zum Download zur Verfügung:",191,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/netzfahrplan-11861526\",\"normalized_sha256\":\"f9cac652f176673dedf0f4e6f85f4b0cd2a1c35ba85d27e97c4fb6efb4025caf\",\"page\":null,\"source_id\":\"src_55f3c19c14f539666c5f\",\"source_sha256\":\"2bbb0a1d9156b3b52057c4c9a5227ea83b4180ae65010634fe7333260185819c\",\"source_version_id\":\"sv_5d5a297063e24f3830a5c3dc\"}","b2a0807744ed3991964664f2581c77db0a6f081c8e5de1f5abd4119c8f7d0a2a"],["chunk_cc8349855afbe31e5b1c2a7d","wiki/sources/trassenanmeldung-im-netzfahrplan.md",1,"Inhalt","| Erläuterungen zu den Trassenanmeldungen finden Sie in der (Richtlinie 402.0202) | [402.0202 (PDF \\| 412,3 KB)](https://www.dbinfrago.com/resource/blob/13699814/21ef89a8cc867ed4a02809b3c981bdf4/Ril-402-0202-INB-2027-data.pdf \"Es wird eine Datei heruntergeladen\") |\r\n| --- | --- |\r\n| Leitfaden für die **Trassenanmeldung Netzfahrplan** (Ril 402.0202A01) | [402.0202A01 (PDF \\| 1,1 MB)](https://www.dbinfrago.com/resource/blob/13699806/d3c759db4e70759c8340d3b0394a7f7a/Ril-402-0202A01-INB-2027-data.pdf \"Es wird eine Datei heruntergeladen\") |\r\n| **Vordruck Anmeldung zum Netzfahrplan** (Ril 402.0202V01) | [402.0202V01 (PDF \\| 740,4 KB)](https://www.dbinfrago.com/resource/blob/13699830/79f484ebfdcc90776cdace760d35b8e1/Ril-402-0202V01-INB-2027-data.pdf \"Es wird eine Datei heruntergeladen\") |\r\n| **Vordruck Anforderungsprofil für Fahrdynamische Triebfahrzeugdaten** (Ril 402.0202V05) | [402.0202V05 (PDF \\| 1,0 MB)](https://www.dbinfrago.com/resource/blob/13699804/a1af1bc96855f37f750b8378cf7b7aea/Ril-402-0202V05-INB-2027-data.pdf \"Es wird eine Datei heruntergeladen\") |",87,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/netzfahrplan-11861526\",\"normalized_sha256\":\"f9cac652f176673dedf0f4e6f85f4b0cd2a1c35ba85d27e97c4fb6efb4025caf\",\"page\":null,\"source_id\":\"src_55f3c19c14f539666c5f\",\"source_sha256\":\"2bbb0a1d9156b3b52057c4c9a5227ea83b4180ae65010634fe7333260185819c\",\"source_version_id\":\"sv_5d5a297063e24f3830a5c3dc\"}","42e0af90ea259537a04b40fc4b8075a5d69567a947f4333eccbd3988cff952bf"]]');
